/* ─── Mini KPI cards ──────────────────────────────────────── */

.kpi-card {
  --x: 50;
  --y: 50;
  position: relative;
  overflow: hidden;
  padding: 8px 11px 9px;
  border-radius: 10px;
  min-width: 98px;
  flex-shrink: 0;
  cursor: default;
  backdrop-filter: blur(18px) saturate(220%) brightness(1.12);
  -webkit-backdrop-filter: blur(18px) saturate(220%) brightness(1.12);
  transition:
    transform   0.30s cubic-bezier(0.34, 1.5, 0.64, 1),
    box-shadow  0.26s ease,
    border-color 0.22s ease;
}

/* Radial spotlight — always-on subtle layer */
.kpi-card::before {
  content: '';
  position: absolute; inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    500px circle at calc(var(--x) * 1px) calc(var(--y) * 1px),
    rgba(255,255,255,0.07),
    transparent 50%
  );
  pointer-events: none;
  z-index: 1;
}

/* Radial spotlight — hover-activated brighter layer */
.kpi-card::after {
  content: '';
  position: absolute; inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    320px circle at calc(var(--x) * 1px) calc(var(--y) * 1px),
    rgba(255,255,255,0.20),
    transparent 50%
  );
  pointer-events: none;
  z-index: 2;
  opacity: 0;
  transition: opacity 0.35s ease;
}
.kpi-card:hover::after { opacity: 1; }

/* Per-card color identity */
.kpi-muszak {
  background: linear-gradient(135deg, rgba(200,65,0,0.28) 0%, rgba(255,107,53,0.15) 100%);
  border: 1px solid rgba(255,107,53,0.28);
  box-shadow: 0 2px 14px rgba(255,107,53,0.14), inset 0 1px 0 rgba(255,255,255,0.12);
}
.kpi-muszak:hover {
  transform: translateY(-7px) scale(1.07);
  border-color: rgba(255,107,53,0.70);
  box-shadow:
    0 0 0 1px rgba(255,107,53,0.75),
    0 0 20px rgba(255,107,53,0.55),
    0 0 55px rgba(255,107,53,0.28),
    0 18px 38px rgba(0,0,0,0.48),
    inset 0 1px 0 rgba(255,255,255,0.22);
}

.kpi-bec {
  background: linear-gradient(135deg, rgba(60,20,160,0.28) 0%, rgba(124,114,220,0.15) 100%);
  border: 1px solid rgba(124,114,220,0.28);
  box-shadow: 0 2px 14px rgba(124,114,220,0.14), inset 0 1px 0 rgba(255,255,255,0.12);
  cursor: pointer;
  user-select: none;
  align-self: flex-start;
}

/* kpi-bec hover/pin glow — triggered by wrapper */
.kpi-bec-wrapper:hover .kpi-bec,
.kpi-bec-wrapper.kpi-bec-pinned .kpi-bec {
  transform: translateY(-7px) scale(1.07);
  border-color: rgba(124,114,220,0.70);
  box-shadow:
    0 0 0 1px rgba(124,114,220,0.75),
    0 0 20px rgba(124,114,220,0.55),
    0 0 55px rgba(124,114,220,0.28),
    0 18px 38px rgba(0,0,0,0.48),
    inset 0 1px 0 rgba(255,255,255,0.22);
}

/* ── Sub-cards — hierarchically lower: darker, less saturated ── */
.kpi-sub-card {
  min-width: 80px;
  padding: 6px 10px 7px;
  backdrop-filter: blur(12px) saturate(140%) brightness(0.9);
  -webkit-backdrop-filter: blur(12px) saturate(140%) brightness(0.9);
}
.kpi-sub-card .kpi-value { font-size: 13px; }
.kpi-sub-card::after {
  background: radial-gradient(
    220px circle at calc(var(--x) * 1px) calc(var(--y) * 1px),
    rgba(255,255,255,0.22),
    transparent 55%
  );
}

.kpi-sub-felveve {
  background: rgba(40,75,140,0.55);
  border: 1px solid rgba(74,158,255,0.30);
  box-shadow: 0 1px 8px rgba(0,0,0,0.35), inset 0 1px 0 rgba(74,158,255,0.14);
}
.kpi-sub-felveve:hover {
  transform: translateY(-4px) scale(1.05);
  border-color: rgba(74,158,255,0.65);
  box-shadow: 0 0 16px rgba(74,158,255,0.45), 0 6px 18px rgba(0,0,0,0.45), inset 0 1px 0 rgba(255,255,255,0.18);
}
.kpi-sub-ertesito {
  background: rgba(110,45,15,0.55);
  border: 1px solid rgba(255,107,53,0.30);
  box-shadow: 0 1px 8px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,107,53,0.14);
}
.kpi-sub-ertesito:hover {
  transform: translateY(-4px) scale(1.05);
  border-color: rgba(255,107,53,0.65);
  box-shadow: 0 0 16px rgba(255,107,53,0.45), 0 6px 18px rgba(0,0,0,0.45), inset 0 1px 0 rgba(255,255,255,0.18);
}
