/* Light mode */






/* ════════════════════════════════════════════════════════════════════════
   Műszak hourly chart — hover/pin panel anchored on the Műszak KPI card.
   Mirrors the kpi-bec wrapper/panel anatomy; hosts an SVG area-line chart.
   ═══════════════════════════════════════════════════════════════════════ */
.kpi-muszak-wrapper { position: relative; }
.kpi-muszak { cursor: pointer; user-select: none; align-self: flex-start; }

/* Hover/pin glow + lift. The transform is intentionally identical for hover and
   pinned, and is also folded into the late .kpi-muszak:hover override group (see
   "~line 8108") exactly like kpi-bec — so clicking to pin never produces a jump. */
.kpi-muszak-wrapper:hover .kpi-muszak,
.kpi-muszak-wrapper.kpi-muszak-pinned .kpi-muszak {
  transform: translateY(-7px) scale(1.07);
  border-color: rgba(255,107,53,0.70);
  box-shadow:
    0 0 0 1px rgba(255,107,53,0.75),
    0 0 20px rgba(255,107,53,0.55),
    0 0 55px rgba(255,107,53,0.28),
    0 18px 38px rgba(0,0,0,0.48),
    inset 0 1px 0 rgba(255,255,255,0.22);
}
.kpi-muszak-wrapper:hover .kpi-expand-arrow,
.kpi-muszak-wrapper.kpi-muszak-pinned .kpi-expand-arrow {
  transform: rotate(180deg);
  opacity: 0.9;
}
.kpi-muszak-wrapper.kpi-muszak-pinned .kpi-muszak {
  outline: 1px solid rgba(255,107,53,0.45);
  outline-offset: 2px;
}
/* Pin confirmation pulse — reuses the shared keyframe the kpi-bec card uses, so
   both cards confirm a pin identically (glow ring, no positional movement). */
.kpi-muszak-wrapper.kpi-muszak-just-pinned .kpi-muszak {
  animation: kpiPinConfirm .82s cubic-bezier(.22,1,.36,1);
}

/* Floating panel — sibling of the card, escapes the card's overflow:hidden. */
.kpi-muszak-panel {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  transform: translateY(-10px);
  z-index: 300;
  pointer-events: none;
  opacity: 0;
  transition:
    opacity   0.22s ease,
    transform 0.34s cubic-bezier(0.34,1.2,0.64,1);
}
.kpi-muszak-wrapper:hover .kpi-muszak-panel,
.kpi-muszak-wrapper.kpi-muszak-pinned .kpi-muszak-panel {
  opacity: 1;
  transform: translateY(0);
  pointer-events: all;
}
.kpi-muszak-panel-arrow {
  width: 0; height: 0;
  margin: 0 0 4px 22px;
  border-left:  8px solid transparent;
  border-right: 8px solid transparent;
  border-bottom: 8px solid rgba(255,255,255,0.09);
}
.kpi-muszak-panel-inner {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  gap: 9px;
  width: 360px;
  max-width: calc(100vw - 32px);
  /* Frosted glass: kept light/translucent so the strong backdrop blur actually
     reads as frosted depth (a darker base just looks like a flat overlay). */
  background:
    radial-gradient(140% 105% at 12% -14%, rgba(255,255,255,0.30), transparent 44%),
    radial-gradient(120% 95% at 94% 122%, rgba(255,138,76,0.16), transparent 52%),
    linear-gradient(150deg, rgba(45,54,76,0.88), rgba(20,27,43,0.94) 48%, rgba(38,46,66,0.90)),
    rgba(14,18,30,0.92);
  backdrop-filter: blur(54px) saturate(230%) brightness(1.08) contrast(1.08);
  -webkit-backdrop-filter: blur(54px) saturate(230%) brightness(1.08) contrast(1.08);
  border: 1px solid rgba(255,255,255,0.19);
  border-radius: 16px;
  padding: 12px 13px 10px;
  box-shadow:
    0 26px 64px rgba(0,0,0,0.60),
    0 4px  14px rgba(0,0,0,0.34),
    inset 0 1px 0 rgba(255,255,255,0.28),
    inset 0 0 0 1px rgba(255,255,255,0.05),
    inset 0 -2px 18px rgba(0,0,0,0.38);
}
/* ── Liquid-glass treatment (renderer-safe: NO color-mix, NO mix-blend-mode).
   ::before = travelling specular sweep + big top-left lens flare.
   ::after  = masked chromatic rim that slowly cycles hue (colour-play). ── */
.kpi-muszak-panel-inner::before {
  content: '';
  position: absolute; inset: 0;
  border-radius: inherit;
  pointer-events: none; z-index: 0;
  background:
    radial-gradient(58% 42% at 18% 6%, rgba(255,255,255,0.18), transparent 62%),
    linear-gradient(118deg, transparent 34%, rgba(255,255,255,0.13) 47%,
                    rgba(255,255,255,0.035) 54%, transparent 66%);
  background-size: 100% 100%, 285% 100%;
  background-repeat: no-repeat;
  background-position: 0 0, -60% 0;
  animation: kpiGlassSweep 90s ease-in-out infinite;
}
@keyframes kpiGlassSweep {
  0%, 92%, 100% { background-position: 0 0, -60% 0; }
  96%           { background-position: 0 0, 155% 0; }
}
.kpi-muszak-panel-inner::after {
  content: '';
  position: absolute; inset: 0;
  border-radius: inherit;
  padding: 1.4px;                /* rim thickness */
  pointer-events: none; z-index: 1;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
  background: conic-gradient(from 135deg,
    rgba(255,154,77,0.05),
    rgba(255,154,77,0.65),
    rgba(125,211,252,0.50),
    rgba(167,139,250,0.55),
    rgba(80,255,214,0.40),
    rgba(255,176,102,0.62),
    rgba(255,154,77,0.05));
  backdrop-filter: blur(2px) saturate(1.3) brightness(1.08);
  -webkit-backdrop-filter: blur(2px) saturate(1.3) brightness(1.08);
  animation: kpiGlassRim 26s linear infinite;
}
@keyframes kpiGlassRim { to { filter: hue-rotate(360deg); } }

/* Card height parity with the "Várható beérkező" card: drop the on-card range line
   (it lives in the panel header) so both KPI cards share the same anatomy/height. */
.kpi-muszak .kpi-sub { display: none; }
.kpi-muszak .kpi-bec-summary {
  padding-inline: 21px;
  box-sizing: border-box;
}

/* Header: arrow · centered shift title · arrow. */
.kpi-hourly-head {
  display: grid;
  grid-template-columns: 22px 1fr 22px;
  align-items: center;
  gap: 6px;
  position: relative; z-index: 4;
}
.kpi-hourly-title {
  grid-column: 2;
  text-align: center;
  font-size: 12px; font-weight: 850; letter-spacing: 0.055em;
  text-transform: uppercase; color: rgba(255,255,255,0.82);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
/* Shared shift-nav arrow (panel header + on-card variants). */
.kpi-shift-nav {
  display: flex; align-items: center; justify-content: center;
  padding: 0; line-height: 1; font-weight: 700;
  cursor: pointer;
  border-radius: 7px;
  transition: background .2s ease, color .2s ease, border-color .2s ease,
              box-shadow .2s ease, transform .2s cubic-bezier(.34,1.5,.64,1),
              opacity .25s ease, visibility .25s ease;
}
.kpi-shift-nav.is-hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.kpi-shift-nav:active { transform: scale(0.92); }

/* Panel-header arrows */
.kpi-shift-nav-panel {
  width: 22px; height: 22px; font-size: 15px;
  color: rgba(255,255,255,0.7);
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.12);
}
.kpi-shift-nav-panel:hover {
  background: rgba(255,107,53,0.22);
  border-color: rgba(255,107,53,0.55);
  color: #ffd9c2;
  transform: scale(1.12);
}
.kpi-shift-nav-panel.kpi-shift-prev { grid-column: 1; justify-self: start; }
.kpi-shift-nav-panel.kpi-shift-next { grid-column: 3; justify-self: end; }

/* On-card arrows — sit on the card edges, vertically centred, above the spotlight
   layers but never overlapping the value text. */
.kpi-shift-nav-card {
  position: absolute;
  top: 50%; transform: translateY(-50%);
  width: 18px; height: 28px; font-size: 16px;
  z-index: 4;
  color: rgba(255,255,255,0.84);
  background: rgba(8,12,24,0.34);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.24), inset 0 1px 0 rgba(255,255,255,0.16);
  opacity: 0.58;
}
.kpi-shift-nav-card.kpi-shift-prev { left: 4px; }
.kpi-shift-nav-card.kpi-shift-next { right: 4px; }
.kpi-shift-nav-card:hover {
  color: #fff;
  background: rgba(255,107,53,0.30);
  border-color: rgba(255,107,53,0.6);
  transform: translateY(-50%) scale(1.12);
}
.kpi-shift-nav-card:active { transform: translateY(-50%) scale(0.92); }
/* Reveal card arrows when the card is hovered or pinned (and not hidden by view). */
.kpi-muszak-wrapper:hover .kpi-shift-nav-card,
.kpi-muszak-wrapper.kpi-muszak-pinned .kpi-shift-nav-card {
  opacity: 0.96;
  transform: translateY(calc(-50% - 7px)) scale(1.07);
}
.kpi-muszak-wrapper:hover .kpi-shift-nav-card:hover,
.kpi-muszak-wrapper.kpi-muszak-pinned .kpi-shift-nav-card:hover {
  transform: translateY(calc(-50% - 7px)) scale(1.14);
}
.kpi-muszak-wrapper:hover .kpi-shift-nav-card:active,
.kpi-muszak-wrapper.kpi-muszak-pinned .kpi-shift-nav-card:active {
  transform: translateY(calc(-50% - 7px)) scale(0.96);
}
.kpi-shift-nav-card.is-hidden { opacity: 0; }

.kpi-hourly-chart {
  position: relative; z-index: 3;
  transition: opacity .20s ease, transform .20s cubic-bezier(.4,0,.2,1);
}
.kpi-hourly-chart.is-redrawing { opacity: 0; transform: translateY(3px); }
.kpi-hourly-chart.is-slide-out-left  { opacity: 0; transform: translateX(-18px); }
.kpi-hourly-chart.is-slide-out-right { opacity: 0; transform: translateX(18px); }
.kpi-hourly-chart.is-slide-in-left   { opacity: 0; transform: translateX(-18px); }
.kpi-hourly-chart.is-slide-in-right  { opacity: 0; transform: translateX(18px); }
.kpi-hourly-empty {
  font-size: 10px; color: rgba(255,255,255,0.40);
  text-align: center; padding: 30px 0;
}

.kpi-hourly-svg { display: block; width: 100%; height: auto; overflow: visible; }
.kpi-hourly-futurezone { fill: rgba(255,255,255,0.04); }

/* Y-axis scale — gridline bands + compact kg labels (0 · mid · top). */
.kpi-hourly-band { fill: rgba(255,255,255,0.018); }
.kpi-hourly-band.band-1 { fill: rgba(255,255,255,0.038); }
.kpi-hourly-grid {
  stroke: rgba(255,255,255,0.10); stroke-width: 1; stroke-dasharray: 3 4;
  vector-effect: non-scaling-stroke;
}
.kpi-hourly-grid.is-base { stroke: rgba(255,255,255,0.20); stroke-dasharray: none; }
.kpi-hourly-ylabel {
  fill: rgba(255,255,255,0.60); font-size: 10.5px; font-weight: 800;
  font-variant-numeric: tabular-nums; letter-spacing: 0.02em;
}

/* Soft gradient under-glow that traces the curve (the "line shadow"). */
.kpi-hourly-glow {
  stroke: #ff7a3c; stroke-width: 6;
  stroke-linecap: round; stroke-linejoin: round;
  opacity: 0.32;
  filter: blur(4px);
  transition: stroke-dashoffset 4s cubic-bezier(0.22,1,0.36,1);
}
.kpi-hourly-line {
  stroke: url(#kpiHourlyStroke); stroke-width: 3.1;
  stroke-linecap: round; stroke-linejoin: round;
  filter: drop-shadow(0 2px 5px rgba(255,107,53,0.45)) drop-shadow(0 5px 12px rgba(255,107,53,0.28));
  transition: stroke-dashoffset 4s cubic-bezier(0.22,1,0.36,1);
  vector-effect: non-scaling-stroke;
}
.kpi-hourly-area { opacity: 0; transition: opacity 0.8s ease 3.2s; }
.kpi-hourly-area.is-shown { opacity: 1; }

/* Data points along the curve + an emphasised marker on the most recent hour. */
.kpi-hourly-dot {
  fill: rgba(255,255,255,0.92);
  opacity: 0;
  animation: kpiHourlyDotIn 0.45s ease 3.0s forwards;
  filter: drop-shadow(0 1px 2px rgba(0,0,0,0.45));
}
.kpi-hourly-peak {
  stroke-width: 1.6;
  opacity: 0;
  animation: kpiHourlyDotIn 0.45s ease 3.15s forwards;
  filter: drop-shadow(0 0 5px rgba(255,122,60,0.7));
}
.kpi-hourly-peak-halo {
  opacity: 0;
  animation: kpiHourlyHaloIn 0.5s ease 3.3s forwards;
}
@keyframes kpiHourlyDotIn { to { opacity: 1; } }
@keyframes kpiHourlyHaloIn { to { opacity: 0.3; } }
@media (prefers-reduced-motion: reduce) {
  .kpi-hourly-dot, .kpi-hourly-peak { animation: none; opacity: 1; }
  .kpi-hourly-peak-halo { animation: none; opacity: 0.24; }
}
.kpi-hourly-now {
  stroke: rgba(255,255,255,0.5); stroke-width: 1; stroke-dasharray: 2 3;
  vector-effect: non-scaling-stroke;
}
.kpi-hourly-guide {
  stroke: rgba(255,255,255,0.30); stroke-width: 1;
  vector-effect: non-scaling-stroke;
  transition: opacity 0.12s ease;
}
.kpi-hourly-hoverdot {
  fill: #fff; stroke: #ff6b35; stroke-width: 2;
  vector-effect: non-scaling-stroke;
  filter: drop-shadow(0 0 6px rgba(255,107,53,0.9));
  transition: opacity 0.12s ease;
}
.kpi-hourly-hoverdot.is-future { stroke: rgba(255,255,255,0.5); filter: none; }

/* Hover tooltip — the exact kg for the hour under the cursor. */
.kpi-hourly-tip {
  position: absolute;
  transform: translate(-50%, calc(-100% - 9px));
  padding: 4px 9px 5px;
  border-radius: 9px;
  background: rgba(12,16,28,0.97);
  border: 1px solid rgba(255,107,53,0.42);
  box-shadow: 0 8px 22px rgba(0,0,0,0.55);
  pointer-events: none; white-space: nowrap;
  display: flex; flex-direction: column; align-items: center; gap: 1px;
  transition: opacity 0.12s ease;
  z-index: 6;
}
.kpi-hourly-tip b { font-size: 11px; font-weight: 800; color: rgba(255,255,255,0.62); letter-spacing: 0.045em; }
.kpi-hourly-tip span { font-size: 18px; font-weight: 900; color: #fff; font-variant-numeric: tabular-nums; }
.kpi-hourly-tip span.muted { font-size: 11px; font-weight: 700; color: rgba(255,255,255,0.52); }

/* Inset to match the SVG plot area (PAD_L=26, PAD_R=14 of viewBox 360) so each
   hour label sits under its curve point. */
.kpi-hourly-axis {
  display: flex; justify-content: space-between; margin-top: 5px;
  padding-left: 7.22%; padding-right: 3.89%;
  box-sizing: border-box;
}
.kpi-hourly-h {
  font-size: 10.5px; font-weight: 800; font-variant-numeric: tabular-nums;
  color: rgba(255,255,255,0.50); transition: color 0.3s ease;
}
.kpi-hourly-h.is-future { color: rgba(255,255,255,0.20); }
.kpi-hourly-h.is-current {
  color: #ffae00; font-weight: 800; text-shadow: 0 0 6px rgba(255,174,0,0.55);
}

/* Light mode */





















.kpi-composition-card {
  position: relative;
  width: 218px;
  min-height: 54px;
  display: flex;
  align-items: center;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.14);
  background:
    linear-gradient(135deg, rgba(255,255,255,0.075), rgba(255,255,255,0.030)),
    rgba(8, 12, 24, 0.24);
  box-shadow:
    0 0 0 1px rgba(255,255,255,0.030),
    inset 0 1px 0 rgba(255,255,255,0.14),
    inset 0 -1px 0 rgba(0,0,0,0.22),
    0 12px 28px rgba(0,0,0,0.20);
  backdrop-filter: blur(18px) saturate(170%);
  -webkit-backdrop-filter: blur(18px) saturate(170%);
  transition: transform 0.28s cubic-bezier(0.22,1,0.36,1),
              border-color 0.22s ease,
              box-shadow 0.22s ease,
              background 0.22s ease;
}

.kpi-composition-card::before {
  content: '';
  position: absolute;
  inset: 5px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.055);
  pointer-events: none;
  z-index: 2;
}

.kpi-composition-card::after {
  content: '';
  position: absolute;
  left: 18px;
  right: 18px;
  top: 50%;
  height: 34px;
  transform: translateY(-50%);
  border-radius: 999px;
  pointer-events: none;
  z-index: 1;
  background:
    radial-gradient(55% 95% at 20% 50%, rgba(74,158,255,0.24), transparent 72%),
    radial-gradient(55% 95% at 72% 50%, rgba(255,107,53,0.20), transparent 72%),
    rgba(255,255,255,0.055);
  filter: blur(11px) saturate(1.25);
  opacity: 0.82;
}

.kpi-composition-card:hover {
  transform: translateY(-2px);
  border-color: rgba(255,255,255,0.20);
  background:
    linear-gradient(135deg, rgba(255,255,255,0.095), rgba(255,255,255,0.040)),
    rgba(8, 12, 24, 0.30);
  box-shadow:
    0 0 0 1px rgba(255,255,255,0.055),
    inset 0 1px 0 rgba(255,255,255,0.18),
    inset 0 -1px 0 rgba(0,0,0,0.20),
    0 16px 34px rgba(0,0,0,0.26);
}

.kpi-composition-track {
  position: relative;
  z-index: 3;
  width: 100%;
  height: 28px;
  display: flex;
  gap: 2px;
  padding: 2px;
  border-radius: 999px;
  background: rgba(255,255,255,0.055);
  box-shadow: inset 0 1px 3px rgba(0,0,0,0.42), inset 0 1px 0 rgba(255,255,255,0.07);
  overflow: visible;
}

.kpi-chart-segment {
  --bar-color: #8b949e;
  --bar-glow: rgba(139,148,158,0.25);
  position: relative;
  min-width: 0;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--bar-color) 86%, white 14%), var(--bar-color));
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.30), 0 0 14px var(--bar-glow);
  transition: width 0.52s cubic-bezier(0.22,1,0.36,1),
              transform 0.24s cubic-bezier(0.22,1,0.36,1),
              filter 0.22s ease,
              box-shadow 0.22s ease;
}

.kpi-chart-segment:hover {
  z-index: 4;
  transform: scaleY(1.18);
  filter: saturate(1.14) brightness(1.08);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.42), 0 0 20px var(--bar-glow), 0 0 36px var(--bar-glow);
}

.kpi-chart-segment-label {
  font-size: 9px;
  font-weight: 900;
  line-height: 1;
  color: rgba(255,255,255,0.88);
  text-shadow: 0 1px 4px rgba(0,0,0,0.32);
  letter-spacing: 0.06em;
  opacity: 0.92;
  pointer-events: none;
}

.kpi-chart-felveve     { --bar-color: #4a9eff; --bar-glow: rgba(74,158,255,0.34); }
.kpi-chart-ertesito    { --bar-color: #ff6b35; --bar-glow: rgba(255,107,53,0.34); }
.kpi-chart-megerkezett { --bar-color: #00d4aa; --bar-glow: rgba(0,212,170,0.34); }
.kpi-chart-szemles     { --bar-color: #ef4444; --bar-glow: rgba(239,68,68,0.34); }

.kpi-chart-segment::after {
  content: attr(data-tooltip);
  position: absolute;
  left: 50%;
  bottom: calc(100% + 11px);
  transform: translateX(-50%) translateY(4px);
  z-index: 30;
  opacity: 0;
  pointer-events: none;
  padding: 5px 8px;
  border-radius: 8px;
  border: 1px solid rgba(255,255,255,0.12);
  background: rgba(12,16,28,0.95);
  color: rgba(255,255,255,0.94);
  box-shadow: 0 10px 24px rgba(0,0,0,0.32);
  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
  transition: opacity 0.18s ease 0.55s, transform 0.18s ease 0.55s;
}

.kpi-chart-segment:hover::after {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}







@media (max-width: 960px) {
  .header-kpi { display: none; }
