/* ─── Stats bar — glass panel ─────────────────────────────── */

.stats-bar {
  display: flex; gap: 0;
  background: rgba(8, 10, 22, 0.42);
  backdrop-filter: blur(22px) saturate(160%);
  -webkit-backdrop-filter: blur(22px) saturate(160%);
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 12px;
  margin: 8px 16px;
  padding: 0 24px;
  overflow-x: auto;
  position: relative; z-index: 10;
}


.stat-item {
  display: flex; align-items: center; gap: 11px;
  padding: 11px 18px; border-radius: 10px;
  min-width: 110px; position: relative;
  cursor: pointer; user-select: none;
  border: 1px solid transparent;
  touch-action: manipulation;
  transition: background 0.18s ease, box-shadow 0.18s ease, transform 0.14s cubic-bezier(0.22,1,0.36,1), border-color 0.18s ease;
  overflow: hidden;
}
.stat-item + .stat-item { margin-left: 6px; }
.stat-item + .stat-item::before {
  content: ''; position: absolute; left: -3px; top: 50%;
  transform: translateY(-50%);
  width: 1px; height: 22px; background: var(--border);
  pointer-events: none;
}
.stat-item:hover {
  transform: translateY(-2px);
  background: rgba(255,255,255,0.05);
  box-shadow: 0 2px 12px rgba(0,0,0,0.20),
              0 0 12px var(--stat-glow, rgba(139,148,158,0.14));
  border-color: var(--stat-glow, rgba(139,148,158,0.12));
}
.stat-item:active {
  transform: translateY(0) scale(0.97);
  opacity: 0.88;
  transition-duration: 0.06s;
}

/* Ripple on stat button press (added via card_fx.js) */
@keyframes statRipple {
  from { transform: scale(0); opacity: 0.28; }
  to   { transform: scale(2.8); opacity: 0; }
}
.stat-item.btn-ripple::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: currentColor;
  animation: statRipple 0.40s cubic-bezier(0.4,0,0.2,1) both;
  pointer-events: none;
}
.stat-item.stat-active {
  background: var(--stat-glow, rgba(139,148,158,0.1));
  border-color: var(--stat-glow, rgba(139,148,158,0.22));
  box-shadow: 0 0 20px var(--stat-glow, rgba(139,148,158,0.22)),
              0 2px 10px rgba(0,0,0,0.18),
              inset 0 1px 0 rgba(255,255,255,0.06);
}
.stat-item.stat-active .stat-value {
  text-shadow: 0 0 16px var(--stat-color, rgba(255,255,255,0.4)),
               0 1px 4px rgba(0,0,0,0.5);
}
.stat-item.stat-active .stat-dot {
  box-shadow: 0 0 8px var(--stat-color, rgba(139,148,158,0.8)),
              0 0 18px var(--stat-glow, rgba(139,148,158,0.5));
}
.stat-item.stat-active .stat-label { color: #a0b0cc; }



.flow-switch {
  margin-left: auto;
  position: relative;
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 4px;
  min-width: 252px;
  border-radius: 11px;
  border: 1px solid rgba(255,255,255,0.12);
  background: linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0.03)), rgba(6,8,18,0.42);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.10), 0 10px 34px rgba(0,0,0,0.28);
  overflow: hidden;
  transform: translateZ(0);
  isolation: isolate;
  transition: box-shadow 0.28s ease, border-color 0.28s ease, background 0.28s ease;
}
.flow-switch:hover {
  border-color: rgba(255,255,255,0.22);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.16),
    inset 0 -10px 24px rgba(255,255,255,0.035),
    0 14px 34px rgba(0,0,0,0.28),
    0 0 28px rgba(0,212,170,0.10);
}
.flow-switch::before {
  content: '';
  position: absolute;
  inset: 4px auto 4px 4px;
  width: calc((100% - 11px) / 2);
  border-radius: 8px;
  background: linear-gradient(135deg, #ff6b35, #00d4aa);
  box-shadow: 0 0 20px rgba(0,212,170,0.28), 0 0 24px rgba(255,107,53,0.18);
  transition: transform 0.42s cubic-bezier(0.22,1.35,0.36,1), background 0.42s ease, box-shadow 0.42s ease;
  z-index: 0;
}
body.flow-uld-mode .flow-switch::before {
  transform: translateX(calc(100% + 3px));
  background: linear-gradient(135deg, #6366f1, #00d4aa);
  box-shadow: 0 0 20px rgba(99,102,241,0.30), 0 0 24px rgba(0,212,170,0.18);
}
body.flow-outbound-mode .flow-switch::before {
  transform: translateX(calc(200% + 6px));
  background: linear-gradient(135deg, #4a9eff, #f59e0b);
  box-shadow: 0 0 22px rgba(74,158,255,0.28), 0 0 28px rgba(245,158,11,0.20);
}
.flow-switch::after {
  content: '';
  position: absolute;
  inset: 3px;
  z-index: 2;
  pointer-events: none;
  border-radius: 9px;
  background: radial-gradient(circle at 35% 50%, rgba(255,255,255,0.16), transparent 44%);
  opacity: 0;
  transform: translateX(-42%) skewX(-12deg);
  mix-blend-mode: screen;
  transition: opacity 0.22s ease;
}
.flow-switch:hover::after {
  opacity: 0.55;
}
.flow-switch:hover::before {
  box-shadow:
    0 0 0 1px rgba(255,255,255,0.18),
    0 0 20px rgba(0,212,170,0.24),
    0 0 28px rgba(255,107,53,0.16);
}



.flow-option {
  position: relative;
  z-index: 1;
  flex: 1;
  border: 0;
  background: transparent;
  color: #7f8da6;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 7px 9px;
  border-radius: 8px;
  cursor: pointer;
  transition: color 0.22s ease, text-shadow 0.22s ease, transform 0.22s ease;
}
.flow-option:hover {
  transform: translateY(-1px);
  color: #dce6ff;
}
.flow-option.flow-active {
  color: #fff;
  text-shadow: 0 1px 10px rgba(0,0,0,0.28);
}
.flow-switch-glow {
  position: absolute;
  inset: -9px;
  border-radius: 16px;
  padding: 2px;
  background:
    linear-gradient(90deg, transparent 0 18%, rgba(255,255,255,0.95) 24%, transparent 34% 58%, rgba(255,255,255,0.64) 65%, transparent 76%),
    linear-gradient(90deg, transparent 0 18%, rgba(0,212,170,0.55) 24%, transparent 34% 58%, rgba(74,158,255,0.45) 65%, transparent 76%);
  background-size: 220% 100%, 220% 100%;
  background-position: 100% 50%, 100% 50%;
  opacity: 0;
  filter: none;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  transition: opacity 0.18s ease;
  pointer-events: none;
  z-index: 3;
}
.flow-switch:hover .flow-switch-glow {
  opacity: 1;
  animation: switchGlowTrace 0.78s ease-out;
}
@keyframes switchGlowTrace {
  0%   { background-position: 100% 50%, 100% 50%; opacity: 0; }
  20%  { opacity: 1; }
  75%  { opacity: 1; }
  100% { background-position: 0% 50%, 0% 50%; opacity: 0; }
}
.stat-dot { width: 3px; height: 30px; border-radius: 2px; flex-shrink: 0;
  transition: background 0.34s ease, box-shadow 0.25s, transform 0.22s ease; }
.stat-item:hover .stat-dot { transform: scaleY(1.12); }
.stat-nums { display: flex; flex-direction: column; gap: 1px; }
.stat-value {
  font-size: 21px; font-weight: 800;
  color: var(--text-primary); line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 6px rgba(0,0,0,0.4);
  transition: color 0.34s ease, text-shadow 0.25s, transform 0.22s ease;
}
.stat-item:hover .stat-value { transform: translateX(2px); }

.stat-label {
  font-size: 10px; font-weight: 600;
  color: #7888a0;
  text-transform: uppercase; letter-spacing: 0.08em;
  transition: color 0.28s ease, transform 0.22s ease, letter-spacing 0.22s ease;
}
.stat-item:hover .stat-label {
  transform: translateX(2px);
  letter-spacing: 0.105em;
}


/* ─── Legend ──────────────────────────────────────────────── */

.legend-bar {
  display: flex; gap: 22px; align-items: center;
  padding: 8px 20px;
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  margin: 0 16px 6px;
  background: rgba(6, 8, 18, 0.28);
  backdrop-filter: blur(16px) saturate(140%);
  -webkit-backdrop-filter: blur(16px) saturate(140%);
  flex-wrap: wrap; position: relative; z-index: 5;
}


.legend-item { display: flex; align-items: center; gap: 7px; }
.legend-dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; flex-shrink: 0; }
.legend-item span:last-child { font-size: 11px; font-weight: 500; color: var(--text-secondary); }

/* ─── Cards area ──────────────────────────────────────────── */

.cards-area {
  padding: 26px 32px;
  position: relative;
  z-index: 2;
  transition: opacity 0.24s ease, transform 0.24s cubic-bezier(0.22,1,0.36,1);
}
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 16px;
  transition: opacity 0.34s ease, transform 0.34s cubic-bezier(0.22,1,0.36,1);
}
.priority-card.card-filter-hidden {
  display: none !important;
}
/* Newly-revealed cards pop in when a filter changes (surviving cards FLIP-slide,
   handled in card_fx.js). */
@keyframes cardFilterIn {
  from { opacity: 0; transform: translateY(9px) scale(0.965); }
  to   { opacity: 1; transform: none; }
}
.priority-card.card-filter-in {
  animation: cardFilterIn 0.36s cubic-bezier(0.22,1,0.36,1) both;
}
/* Betárolva: a quick green check "stamp" flashes over the card as it leaves. */
.priority-card.card-store-flash::after {
  content: '';
  position: absolute; inset: 0; z-index: 6;
  background:
    radial-gradient(circle at 50% 46%, rgba(34,197,94,0.22), transparent 60%);
  opacity: 0;
  animation: storeFlash 0.42s ease-out forwards;
  pointer-events: none;
  border-radius: var(--radius-card);
  mix-blend-mode: screen;
}
@keyframes storeFlash {
  0%   { opacity: 0; }
  35%  { opacity: 1; }
  100% { opacity: 0; }
}
.badge-stored-empty:active,
.badge-stored-active:active { transform: scale(0.93); filter: brightness(1.18); }
@media (prefers-reduced-motion: reduce) {
  .priority-card.card-filter-in { animation: none; }
  .priority-card.card-store-flash::after { animation: none; }
}
.filter-empty-state {
  margin-top: 18px;
}
body.flow-switching .cards-area {
  animation: viewSoftSwap 0.38s cubic-bezier(0.22,1,0.36,1) both;
}
body.flow-switching .stat-item,
body.flow-switching .legend-item,
body.flow-switching .header-kpi,
body.flow-switching .refresh-info {
  animation: dataSoftFlip 0.72s cubic-bezier(0.22,1,0.36,1) both;
}
@keyframes viewSoftSwap {
  0%   { opacity: 0.58; transform: translateY(5px) scale(0.997); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes dataSoftFlip {
  0%   { opacity: 1; transform: translateY(0); }
  35%  { opacity: 0.45; transform: translateY(5px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* ─── Priority Card — Liquid Glass ───────────────────────── */

/* Per-card glow + tint colors */
.pcard-b2b           { --glow: rgba(239,68,68,0.78);   --glow-far: rgba(220,38,38,0.34);   --glow-ultra: rgba(239,68,68,0.15);   --glow-tint: rgba(239,68,68,0.32);  }
.pcard-rest-soon     { --glow: rgba(251,191,36,0.65);  --glow-far: rgba(251,191,36,0.28);  --glow-ultra: rgba(251,191,36,0.10);  --glow-tint: rgba(251,191,36,0.26); }
.pcard-at-hu         { --glow: rgba(255,107,53,0.55);  --glow-far: rgba(255,107,53,0.22);  --glow-ultra: rgba(255,107,53,0.08);  --glow-tint: rgba(255,107,53,0.22); }
.pcard-temu          { --glow: rgba(244,63,94,0.55);   --glow-far: rgba(244,63,94,0.22);   --glow-ultra: rgba(244,63,94,0.08);   --glow-tint: rgba(244,63,94,0.22);  }
.pcard-driver-active { --glow: rgba(0,212,170,0.50);   --glow-far: rgba(0,212,170,0.20);   --glow-ultra: rgba(0,212,170,0.07);   --glow-tint: rgba(0,212,170,0.17);  }
.pcard-driver-rest   { --glow: rgba(124,114,220,0.50); --glow-far: rgba(124,114,220,0.20); --glow-ultra: rgba(124,114,220,0.07); --glow-tint: rgba(124,114,220,0.18); }
.pcard-loading-plan  { --glow: rgba(74,158,255,0.50);  --glow-far: rgba(74,158,255,0.20);  --glow-ultra: rgba(74,158,255,0.07);  --glow-tint: rgba(74,158,255,0.17);  }
.pcard-standard      { --glow: rgba(139,148,158,0.32); --glow-far: rgba(139,148,158,0.12); --glow-ultra: rgba(139,148,158,0.05); --glow-tint: rgba(139,148,158,0.10); }
.pcard-betarolt        { --glow: rgba(120,136,160,0.35);  --glow-far: rgba(120,136,160,0.14); --glow-ultra: rgba(120,136,160,0.05); --glow-tint: rgba(120,136,160,0.12); }
.pcard-betarolt-stored { --glow: rgba(230,126,34,0.50);   --glow-far: rgba(230,126,34,0.20);  --glow-ultra: rgba(230,126,34,0.07);  --glow-tint: rgba(230,126,34,0.18);  }

.priority-test-view {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.priority-test-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 14px;
  border: 1px solid rgba(251,191,36,0.56);
  border-radius: 12px;
  color: #fef3c7;
  background: rgba(120,53,15,0.38);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 8px 22px rgba(0,0,0,0.18);
}

.priority-test-banner strong {
  font-size: 12px;
  letter-spacing: 0.06em;
}

.priority-test-banner span {
  color: #fde68a;
  font-size: 12px;
  font-weight: 700;
}

@media (max-width: 720px) {
  .priority-test-banner {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
}

.priority-card {
  position: relative;
  clip-path: inset(0 round var(--radius-card));
  /* Corner color-wash from top-left instead of a generic left stripe */
  background:
    linear-gradient(177deg, rgba(255,255,255,0.10) 0%, rgba(255,255,255,0.02) 26%, transparent 60%),
    radial-gradient(ellipse 125% 68% at -10% -10%, var(--glow-tint, transparent) 0%, transparent 58%),
    radial-gradient(ellipse 90% 45% at 100% 0%, var(--glow-ultra, transparent) 0%, transparent 54%),
    rgba(255, 255, 255, 0.062);
  backdrop-filter: blur(18px) saturate(215%) brightness(1.12) contrast(1.04);
  -webkit-backdrop-filter: blur(18px) saturate(215%) brightness(1.12) contrast(1.04);
  border-radius: var(--radius-card);
  border: 1px solid rgba(255,255,255,0.14);
  /* Beveled glass edge: bright top + dark bottom + soft side insets read as a
     thicker, light-bending rim (iOS liquid-glass "distortion"). Plus a faint
     colour-matched ambient halo so each card subtly emits its category light.
     Static box-shadows — compositor only, no per-frame repaint. */
  box-shadow:
    0 6px 26px rgba(0,0,0,0.36),
    0 0 30px var(--glow-ultra, transparent),
    inset 0 1.8px 2.4px rgba(255,255,255,0.34),
    inset 0 -1.8px 3px rgba(0,0,0,0.24),
    inset 2.5px 0 3px rgba(255,255,255,0.09),
    inset -2.5px 0 3px rgba(0,0,0,0.12);
  cursor: default;
  transition:
    transform 0.30s cubic-bezier(0.34,1.3,0.64,1),
    box-shadow 0.28s ease,
    border-color 0.22s ease,
    background 0.34s ease,
    opacity 0.24s ease;
  animation: fadeUp 0.52s cubic-bezier(0.34,1.15,0.64,1) backwards;
}

/* Glass refraction highlight */
.priority-card::after {
  content: '';
  position: absolute; inset: 0;
  background:
    radial-gradient(120% 78% at 12% 2%, rgba(255,255,255,0.30), transparent 36%),
    radial-gradient(85% 55% at 96% 0%, var(--glow-tint, rgba(255,255,255,0.10)), transparent 52%),
    linear-gradient(135deg, rgba(255,255,255,0.22) 0%, transparent 30%, transparent 56%, rgba(255,255,255,0.075) 100%);
  pointer-events: none; z-index: 1;
  border-radius: var(--radius-card);
  opacity: 0.82;
  mix-blend-mode: screen;
}

/* Shimmer sweep on hover */
.priority-card::before {
  content: '';
  position: absolute;
  inset: 0.5px;
  pointer-events: none;
  z-index: 2;
  border-radius: calc(var(--radius-card) - 0.5px);
  /* Thin gradient border that runs the FULL perimeter in the category colour
     (priority tint), with a white specular streak on top. Elegant + refractive. */
  padding: 1.5px;
  background:
    linear-gradient(135deg, var(--glow, rgba(255,255,255,0.22)) 0%, var(--glow-far, rgba(255,255,255,0.12)) 38%, var(--glow-far, rgba(255,255,255,0.12)) 62%, var(--glow, rgba(255,255,255,0.22)) 100%),
    radial-gradient(120% 120% at 0% 0%, var(--glow, rgba(255,255,255,0.2)), transparent 55%),
    linear-gradient(130deg, rgba(255,255,255,0.9), transparent 22% 70%, rgba(255,255,255,0.26));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0.8;
  filter: blur(0.5px);
  transform: translate3d(0,0,0);
  transition: opacity 0.3s ease, filter 0.3s ease, transform 0.4s var(--liquid-ease);
}
.priority-card:hover::before {
  opacity: 1;
  filter: blur(0.7px) saturate(1.7) brightness(1.22);
  transform: scale(1.012);
}

.priority-card:hover {
  transform: translateY(-5px) scale(1.018);
  border-color: var(--card-color, #8b949e);
  box-shadow:
    0 0 0 1px var(--card-color, #8b949e),
    0 0 18px var(--glow),
    0 0 55px var(--glow),
    0 0 100px var(--glow-far),
    0 0 200px var(--glow-ultra, transparent),
    0 24px 60px rgba(0,0,0,0.50),
    inset 0 1px 0 rgba(255,255,255,0.22),
    inset 0 -1px 0 rgba(0,0,0,0.15);
}
.priority-card.card-expanded:hover {
  transform: translateY(-2px) scale(1.008);
}

/* Light mode glass */




/* Animation stagger */
.priority-card:nth-child(1)  { animation-delay: 0.00s; }
.priority-card:nth-child(2)  { animation-delay: 0.04s; }
.priority-card:nth-child(3)  { animation-delay: 0.08s; }
.priority-card:nth-child(4)  { animation-delay: 0.12s; }
.priority-card:nth-child(5)  { animation-delay: 0.16s; }
.priority-card:nth-child(6)  { animation-delay: 0.20s; }
.priority-card:nth-child(7)  { animation-delay: 0.24s; }
.priority-card:nth-child(8)  { animation-delay: 0.28s; }
.priority-card:nth-child(n+9){ animation-delay: 0.32s; }

/* ─── Card exit animation (Betárolva / manual store) ──────── */
@keyframes cardExit {
  0%   { opacity: 1;    transform: scale(1)    translateY(0px);   }
  55%  { opacity: 0.08; transform: scale(0.91) translateY(-10px); }
  100% { opacity: 0;    transform: scale(0.88) translateY(-14px); }
}
.priority-card.card-exiting {
  animation: cardExit 0.30s cubic-bezier(0.4, 0, 1, 1) both;
  pointer-events: none;
}
.priority-card.card-flipping {
  pointer-events: none;
}
.card-removal-placeholder {
  min-width: 0;
  border-radius: var(--radius-card);
  opacity: 1;
  transform: scale(1);
  transition:
    width 0.34s cubic-bezier(0.22,1,0.36,1),
    height 0.34s cubic-bezier(0.22,1,0.36,1),
    opacity 0.24s ease,
    transform 0.34s cubic-bezier(0.22,1,0.36,1);
}
.card-exit-ghost {
  contain: paint style;
  content-visibility: visible !important;
  animation: none !important;
  clip-path: inset(0 round var(--radius-card));
  transform: translate3d(0,0,0) scale(1);
  opacity: 1;
}
.card-exit-ghost-run {
  opacity: 0;
  transform: translate3d(0,-14px,0) scale(0.92);
  filter: blur(1px) saturate(0.95);
  transition:
    transform 0.32s cubic-bezier(0.4,0,1,1),
    opacity 0.32s cubic-bezier(0.4,0,1,1),
    filter 0.32s ease;
}

/* ─── Card strip ──────────────────────────────────────────── */

.card-strip {
  display: flex; align-items: center; gap: 7px;
  padding: 7px 12px;
  position: relative; z-index: 3;
}
/* Uniform header height — badges (clock, notes, cargo…) center, never stretch it. */
.priority-card .card-strip {
  min-height: 38px;
  flex-wrap: nowrap;
}
.rank-num {
  font-size: 11px; font-weight: 700;
  color: rgba(255,255,255,0.88);
  background: rgba(0,0,0,0.24);
  padding: 2px 6px; border-radius: 20px;
