/* ─── Betárolva action button ─────────────────────────────── */
/* Hierarchically above ULD/PLT info badges — has real action behind it */

.badge-stored {
  font-size: 11px; font-weight: 700;
  padding: 3px 9px; border-radius: 6px;
  letter-spacing: 0.03em; flex-shrink: 0;
  cursor: pointer;
  border: 1px solid transparent;
  font-family: inherit; line-height: 1.5;
  transition: background 0.15s, color 0.15s, border-color 0.15s,
              box-shadow 0.15s, transform 0.10s;
  outline: none;
  position: relative;
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
}
.badge-stored:active {
  transform: scale(0.91);
  transition-duration: 0.06s;
}

/* Empty: not yet stored — dark base so text is visible on ANY strip color */
.badge-stored-empty {
  background: rgba(0,0,0,0.36);
  color: rgba(255,255,255,0.72);
  border-color: rgba(255,255,255,0.42);
}
.badge-stored-empty:hover {
  background: rgba(0,0,0,0.45);
  color: #fbbf24;
  border-color: rgba(251,191,36,0.65);
  box-shadow: 0 0 10px rgba(251,191,36,0.28);
}

/* Active: item is stored — amber on dark base, clearly toggled-on */
.badge-stored-active {
  background: rgba(0,0,0,0.32);
  color: #fbbf24;
  border-color: rgba(251,191,36,0.75);
  box-shadow: 0 0 10px rgba(251,191,36,0.35), inset 0 1px 0 rgba(255,255,255,0.10);
}
.badge-stored-active:hover {
  /* Hover = hint that click will UN-store → red/danger tint */
  background: rgba(0,0,0,0.40);
  color: #fca5a5;
  border-color: rgba(252,165,165,0.70);
  box-shadow: 0 0 10px rgba(239,68,68,0.30);
}

/* Disabled: snapshot items — muted, no interaction */
.badge-stored-disabled {
  font-size: 10px; font-weight: 600;
  padding: 2px 8px; border-radius: 20px;
  background: rgba(0,0,0,0.22);
  color: rgba(255,255,255,0.38);
  border-color: rgba(255,255,255,0.18);
  cursor: default;
  pointer-events: none;
  letter-spacing: 0.04em;
}






