  background:
    radial-gradient(90% 140% at 0% 0%, rgba(255,255,255,0.105), transparent 54%),
    rgba(255,255,255,0.062);
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 7px; padding: 2px 7px; white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.08);
  transform: translateZ(0);
  transition:
    transform 0.18s cubic-bezier(0.22,1,0.36,1),
    color 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}
.colli-text:hover {
  color: #f6f9ff;
  transform: translateY(-1px) scale(1.035);
  background:
    radial-gradient(90% 140% at 0% 0%, rgba(255,255,255,0.18), transparent 54%),
    color-mix(in srgb, var(--card-color, #8b949e) 16%, rgba(255,255,255,0.08));
  border-color: color-mix(in srgb, var(--card-color, #8b949e) 52%, rgba(255,255,255,0.18));
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--card-color, #8b949e) 26%, transparent),
    0 8px 18px rgba(0,0,0,0.16),
    0 0 16px color-mix(in srgb, var(--card-color, #8b949e) 18%, transparent),
    inset 0 1px 0 rgba(255,255,255,0.16);
}


.weight-text { font-size: 13px; font-weight: 700; margin-left: 0; flex-shrink: 0; font-variant-numeric: tabular-nums; }
.weight-text {
  transition: transform 0.22s ease, filter 0.22s ease, text-shadow 0.22s ease;
}
.weight-text:hover {
  transform: translateY(-1px);
  filter: brightness(1.15);
  text-shadow: 0 0 12px currentColor;
}
.card-row { display: flex; align-items: center; gap: 6px; margin-bottom: 10px; }
.row-label {
  font-size: 11px; font-weight: 600; color: #7888a0;
  text-transform: uppercase; letter-spacing: 0.07em; white-space: nowrap;
  transition: color 0.22s ease, letter-spacing 0.22s ease;
}
.card-row:hover .row-label {
  color: #9eb1d4;
  letter-spacing: 0.095em;
}

.row-value {
  font-size: 12px; font-weight: 700; color: #b8c5dd;
  font-variant-numeric: tabular-nums;
  transition: color 0.22s ease, transform 0.22s ease;
}
.card-row:hover .row-value {
  color: var(--text-primary);
  transform: translateX(2px);
}


/* ─── Compact card body ───────────────────────────────────── */

/* Compact always-visible section (replaces card-body-inner for inbound) */
.card-body-compact {
  padding: 11px 15px 10px;
  position: relative;
  z-index: 3;
  cursor: pointer;
}
.priority-card.card-expanded .card-body-compact { cursor: default; }

/* Quick meta: LMP · weight · colli in one line */
.card-quick-meta {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-bottom: 5px;
}
.meta-sep {
  color: rgba(184,197,221,0.38);
  font-size: 12px;
  font-weight: 400;
  flex-shrink: 0;
  user-select: none;
}


/* Compact time row: Felvéve label + value + eltelt idő inline */
.card-time-compact {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-top: 2px;
}
.since-compact {
  font-size: 11px;
  font-weight: 700;
  color: rgba(184,197,221,0.65);
  margin-left: 2px;
  letter-spacing: 0.01em;
}


/* ─── Expand / collapse details section ───────────────────── */

.card-details-section {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.38s cubic-bezier(0.22, 1, 0.36, 1),
              opacity 0.28s ease;
  opacity: 0;
}
.card-details-inner {
  overflow: hidden;
  min-height: 0;
}
.priority-card.card-expanded .card-details-section {
  grid-template-rows: 1fr;
  opacity: 1;
}

/* Expand hint: subtle bottom-right indicator on compact cards */
.card-body-compact::after {
  content: '▾';
  position: absolute;
  right: 14px;
  bottom: 10px;
  font-size: 10px;
  color: rgba(184,197,221,0.32);
  pointer-events: none;
  transition: color 0.22s ease, transform 0.22s ease;
}
.priority-card:hover .card-body-compact::after {
  color: rgba(184,197,221,0.65);
}
.priority-card.card-expanded .card-body-compact::after {
  content: '▴';
  color: rgba(184,197,221,0.55);
}



/* ─── Floating quick-info tooltip ────────────────────────── */

.card-tooltip-float {
  position: fixed;
  pointer-events: none;
  z-index: 8800;
  background: rgba(8, 12, 28, 0.78);
  backdrop-filter: blur(22px) saturate(180%);
  -webkit-backdrop-filter: blur(22px) saturate(180%);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 12px;
  padding: 10px 14px;
  min-width: 190px;
  max-width: 270px;
  display: none;
  opacity: 0;
  transform: translateY(6px) scale(0.97);
  transition: opacity 0.18s ease, transform 0.22s cubic-bezier(0.22,1,0.36,1);
  box-shadow:
    0 16px 48px rgba(0,0,0,0.55),
    0 4px 12px rgba(0,0,0,0.35),
    inset 0 1px 0 rgba(255,255,255,0.12),
    inset 0 -1px 0 rgba(0,0,0,0.18);
}
.card-tooltip-float.ftip-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
}
.ftip-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 3px 0;
}
.ftip-row + .ftip-row {
  border-top: 1px solid rgba(255,255,255,0.055);
}
.ftip-label {
  font-size: 10px;
  font-weight: 600;
  color: rgba(184,197,221,0.50);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  white-space: nowrap;
  min-width: 54px;
  flex-shrink: 0;
}
.ftip-val {
  font-size: 12px;
  font-weight: 700;
  color: #d9e4f8;
  line-height: 1.3;
}

/* ─── GLABS / driver ──────────────────────────────────────── */

.lp-section { margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border-light); }
.card-details-inner .lp-section { margin-top: 0; padding: 10px 15px 12px; }
.card-compact-glabs { margin-top: 5px; line-height: 1; }
.glabs-id-compact   { font-size: 11px !important; border: none !important; background: none !important; padding: 0 !important; }
.glabs-row  { margin-bottom: 5px; }
.glabs-id   { font-size: 11px; font-weight: 700; color: #7888a0; letter-spacing: 0.08em; text-transform: uppercase; }
.glabs-id {
  transition: filter 0.22s ease, letter-spacing 0.22s ease, text-shadow 0.22s ease;
}
.glabs-id:hover {
  filter: brightness(1.25);
  letter-spacing: 0.11em;
  text-shadow: 0 0 12px currentColor;
}

.glabs-progress-wrap { display: flex; align-items: center; gap: 10px; margin-bottom: 9px; }
.glabs-progress-wrap {
  transition: transform 0.22s ease;
}
.glabs-progress-wrap:hover {
  transform: translateX(2px);
}
.glabs-progress-track {
  flex: 1; height: 4px;
  background: rgba(255,255,255,0.09);
  border-radius: 99px; overflow: hidden;
  transition: height 0.22s ease, background 0.22s ease, box-shadow 0.22s ease;
}
.glabs-progress-wrap:hover .glabs-progress-track {
  height: 6px;
  background: rgba(255,255,255,0.14);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.05);
}

.glabs-progress-fill {
  position: relative;
  height: 100%; border-radius: 99px;
  min-width: 4px;
  transform-origin: left center;
  /* Fills in once on (re)render — render only happens on real data change.
     No idle loop, so it costs nothing while scrolling/morphing. */
  animation: glabsFillIn 0.7s var(--liquid-ease) both;
  transition: width 0.3s cubic-bezier(0.22,1,0.36,1), background-color 0.22s ease;
}
@keyframes glabsFillIn { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@media (prefers-reduced-motion: reduce) {
  .glabs-progress-fill { animation: none; }
}
.glabs-progress-label { font-size: 11px; font-weight: 700; white-space: nowrap; font-variant-numeric: tabular-nums; }
.glabs-progress-num { font-weight: 800; font-variant-numeric: tabular-nums; }
.glabs-progress-rest { opacity: 0.9; }
.glabs-progress-label {
  transition: transform 0.22s ease, filter 0.22s ease;
}
.glabs-progress-wrap:hover .glabs-progress-label {
  transform: translateX(2px);
  filter: brightness(1.15);
}
.driver-row  {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 8px 0 6px;
  padding: 9px 10px 9px 12px;
  border-radius: 12px;
  background:
    radial-gradient(90% 120% at 0% 0%, color-mix(in srgb, var(--card-color, #8b949e) 12%, transparent), transparent 54%),
    rgba(255,255,255,0.052);
  border: 1px solid rgba(255,255,255,0.09);
  border-left: 3px solid var(--card-color, #8b949e);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.07);
  transition: transform 0.16s cubic-bezier(0.22,1,0.36,1), background 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease;
}
.driver-row:hover {
  transform: translateY(-1px);
  background:
    radial-gradient(90% 120% at 0% 0%, color-mix(in srgb, var(--card-color, #8b949e) 18%, transparent), transparent 54%),
    rgba(255,255,255,0.075);
  border-color: rgba(255,255,255,0.15);
  border-left-color: var(--card-color, #8b949e);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.11), 0 8px 18px rgba(0,0,0,0.13);
}
.driver-row::before {
  content: '';
  width: 8px;
  height: 8px;
  margin-top: 4px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--card-color, #8b949e);
  box-shadow: 0 0 12px color-mix(in srgb, var(--card-color, #8b949e) 45%, transparent);
}
.driver-info { display: flex; flex-direction: column; gap: 4px; flex: 1; min-width: 0; }
.driver-text { font-size: 12px; font-weight: 800; color: #d9e4f8; font-variant-numeric: tabular-nums; letter-spacing: 0.01em; }

.wait-badge  { font-size: 11px; font-weight: 700; letter-spacing: 0.02em; }
.since-badge { display: block; margin-bottom: 10px; }
.no-driver {
  border-left-color: #8b949e;
  background:
    radial-gradient(90% 120% at 0% 0%, rgba(139,148,158,0.12), transparent 54%),
    rgba(255,255,255,0.045);
}
.no-driver::before {
  background: #8b949e;
  box-shadow: 0 0 10px rgba(139,148,158,0.30);
}
.no-driver-text { font-size: 12px; font-weight: 750; color: #aebbd1; letter-spacing: 0.01em; }




.rest-warning {
  display: flex; align-items: center;
  width: 100%;
  background:
    radial-gradient(90% 120% at 0% 0%, rgba(124,114,220,0.18), transparent 54%),
    rgba(124,114,220,0.08);
  border: 1px solid rgba(124,114,220,0.24);
  border-left: 3px solid #7c72dc;
  border-radius: 12px; padding: 9px 10px 9px 12px; margin-top: 8px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.07);
  transition: transform 0.16s cubic-bezier(0.22,1,0.36,1), background 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease;
}
.rest-warning:hover {
  transform: translateY(-1px);
  background:
    radial-gradient(90% 120% at 0% 0%, rgba(124,114,220,0.24), transparent 54%),
    rgba(124,114,220,0.11);
  border-color: rgba(124,114,220,0.34);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.10), 0 8px 18px rgba(0,0,0,0.12);
}
.rest-text { font-size: 12px; font-weight: 800; color: #a9a2ff; letter-spacing: 0.01em; }



/* Outbound truck cards */
.outbound-grid {
  grid-template-columns: repeat(auto-fill, minmax(390px, 1fr));
}
.outbound-card .card-strip {
  min-height: 42px;
  background-image: linear-gradient(135deg, var(--card-color), rgba(255,255,255,0.10));
}
.outbound-card:hover .card-strip {
  background-image: linear-gradient(135deg, var(--card-color), rgba(255,255,255,0.24));
}
.outbound-card-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.outbound-plate {
  font-size: 24px;
  letter-spacing: 0.04em;
}
.outbound-summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.outbound-summary-grid > div {
  min-width: 0;
  padding: 9px 10px;
  border-radius: 10px;
  background: rgba(255,255,255,0.055);
  border: 1px solid var(--border-light);
  transition: transform 0.24s cubic-bezier(0.22,1,0.36,1), background 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}
.outbound-summary-grid > div:hover {
  transform: translateY(-3px);
  background: rgba(255,255,255,0.085);
  border-color: rgba(255,255,255,0.14);
  box-shadow: 0 10px 24px rgba(0,0,0,0.16);
}
.outbound-summary-grid strong {
  display: block;
  margin-top: 3px;
  color: var(--text-primary);
  font-size: 13px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}


.outbound-glabs-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.outbound-glabs-block {
  padding: 10px;
  border-radius: 12px;
  background: rgba(0,0,0,0.12);
  border: 1px solid var(--border-light);
  transition: border-color 0.26s ease, background 0.26s ease, transform 0.26s cubic-bezier(0.22,1,0.36,1), box-shadow 0.26s ease;
}
.outbound-glabs-block:hover {
  transform: translateY(-2px);
  border-color: rgba(255,255,255,0.16);
  background: rgba(255,255,255,0.075);
  box-shadow: 0 12px 28px rgba(0,0,0,0.18);
}
.outbound-glabs-block[open] {
  background: rgba(255,255,255,0.08);
  border-color: rgba(255,255,255,0.18);
}

.outbound-glabs-summary {
  list-style: none;
  cursor: pointer;
}
.outbound-glabs-summary::-webkit-details-marker {
  display: none;
}
.outbound-glabs-summary::after {
  content: 'Részletek';
  display: inline-flex;
  margin-top: 8px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color 0.22s ease, transform 0.22s ease;
}
.outbound-glabs-block[open] .outbound-glabs-summary::after {
  content: 'Elrejtés';
  color: var(--card-color, #8b949e);
}
.outbound-glabs-summary:hover::after {
  transform: translateX(4px);
}
.outbound-glabs-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 7px;
}
.outbound-ready-pill {
  flex-shrink: 0;
  font-size: 10px;
  font-weight: 800;
  color: #22c55e;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 3px 7px;
  border-radius: 999px;
  background: rgba(34,197,94,0.10);
  border: 1px solid rgba(34,197,94,0.20);
  transition: transform 0.22s ease, background 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease;
}
.outbound-ready-pill:hover {
  transform: translateY(-1px);
  background: rgba(34,197,94,0.16);
  border-color: rgba(34,197,94,0.32);
  box-shadow: 0 0 16px rgba(34,197,94,0.13);
}
.outbound-lmp-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.outbound-lmp-row {
  display: grid;
  grid-template-columns: minmax(84px, 0.8fr) minmax(0, 1.6fr);
  gap: 8px;
  align-items: center;
  padding: 5px 0;
  border-top: 1px solid var(--border-light);
}
.outbound-lmp-row:first-child {
  border-top: 0;
}
.outbound-lmp-name {
  min-width: 0;
  font-size: 12px;
  font-weight: 800;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: color 0.22s ease, transform 0.22s ease, text-shadow 0.22s ease;
}
.outbound-lmp-name:hover {
  color: #dfe8ff;
  transform: translateX(3px);
  text-shadow: 0 0 12px rgba(74,158,255,0.22);
}
.outbound-lmp-meta {
  min-width: 0;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: color 0.22s ease, transform 0.22s ease;
}
.outbound-lmp-meta:hover {
  color: var(--text-primary);
  transform: translateX(2px);
}
.outbound-notes {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.outbound-note {
  max-width: 100%;
  padding: 5px 8px;
  border-radius: 999px;
  background: rgba(245,158,11,0.10);
  border: 1px solid rgba(245,158,11,0.20);
  color: #f6bd48;
  font-size: 11px;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: transform 0.24s cubic-bezier(0.22,1,0.36,1), background 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease, color 0.24s ease;
}
.outbound-note:hover {
  transform: translateY(-2px) scale(1.015);
  background: rgba(245,158,11,0.18);
  border-color: rgba(245,158,11,0.36);
  color: #ffd27a;
  box-shadow: 0 8px 22px rgba(245,158,11,0.12), 0 0 18px rgba(245,158,11,0.10);
}


.outbound-awb-list {
  display: grid;
  gap: 6px;
  margin-top: 10px;
  max-height: 360px;
  overflow: auto;
  animation: detailsReveal 0.28s cubic-bezier(0.22,1,0.36,1) both;
}
.outbound-awb-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 9px 8px 12px;
  border-radius: 10px;
  background: rgba(255,255,255,0.045);
  border: 1px solid transparent;
  border-left: 4px solid var(--lmp-accent, rgba(139,148,158,0.55));
  transition: transform 0.22s cubic-bezier(0.22,1,0.36,1), background 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease;
}
.outbound-awb-row.lmp-g0 { --lmp-accent: #00d4aa; --lmp-bg: rgba(0,212,170,0.12); }
.outbound-awb-row.lmp-g1 { --lmp-accent: #4a9eff; --lmp-bg: rgba(74,158,255,0.12); }
.outbound-awb-row.lmp-g2 { --lmp-accent: #f59e0b; --lmp-bg: rgba(245,158,11,0.13); }
.outbound-awb-row.lmp-g3 { --lmp-accent: #f43f5e; --lmp-bg: rgba(244,63,94,0.12); }
.outbound-awb-row.lmp-g4 { --lmp-accent: #7c72dc; --lmp-bg: rgba(124,114,220,0.13); }
.outbound-awb-row.lmp-g5 { --lmp-accent: #22c55e; --lmp-bg: rgba(34,197,94,0.12); }
.outbound-awb-row.lmp-g6 { --lmp-accent: #e879f9; --lmp-bg: rgba(232,121,249,0.12); }
.outbound-awb-row.lmp-g7 { --lmp-accent: #38bdf8; --lmp-bg: rgba(56,189,248,0.12); }
.outbound-awb-row:hover {
  transform: translateX(4px);
  background: rgba(255,255,255,0.08);
  border-color: rgba(255,255,255,0.13);
  border-left-color: var(--lmp-accent);
  box-shadow: 0 8px 20px rgba(0,0,0,0.14), 0 0 18px color-mix(in srgb, var(--lmp-accent) 18%, transparent);
}
.outbound-awb-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.outbound-awb-head {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
}
.outbound-awb-code {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
  transition: color 0.22s ease, transform 0.22s ease, text-shadow 0.22s ease;
}
.outbound-awb-row:hover .outbound-awb-code {
  transform: translateX(2px);
  text-shadow: 0 0 12px color-mix(in srgb, var(--lmp-accent) 28%, transparent);
}
.outbound-lmp-chip {
  flex-shrink: 1;
  min-width: 0;
  max-width: 170px;
  padding: 2px 7px;
  border-radius: 999px;
  color: var(--lmp-accent);
  background: var(--lmp-bg);
  border: 1px solid color-mix(in srgb, var(--lmp-accent) 34%, transparent);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.035em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: transform 0.22s ease, background 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease;
}
.outbound-lmp-chip:hover,
.outbound-awb-row:hover .outbound-lmp-chip {
  transform: translateY(-1px);
  background: color-mix(in srgb, var(--lmp-accent) 18%, transparent);
  border-color: color-mix(in srgb, var(--lmp-accent) 50%, transparent);
  box-shadow: 0 0 14px color-mix(in srgb, var(--lmp-accent) 16%, transparent);
}
.outbound-awb-meta {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: color 0.22s ease, transform 0.22s ease;
}
.outbound-awb-row:hover .outbound-awb-meta {
  color: var(--text-primary);
  transform: translateX(2px);
}
.outbound-status-pill {
  flex-shrink: 0;
  max-width: 145px;
  padding: 4px 7px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: #cbd7ef;
  background: rgba(139,148,158,0.13);
  border: 1px solid rgba(139,148,158,0.20);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: transform 0.22s ease, background 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease, color 0.22s ease;
}
.outbound-status-pill:hover,
.outbound-awb-row:hover .outbound-status-pill {
  transform: translateY(-1px);
  box-shadow: 0 0 14px rgba(255,255,255,0.10);
}
.outbound-awb-row.is-ready .outbound-status-pill {
  color: #7ee8c8;
  background: rgba(0,212,170,0.12);
  border-color: rgba(0,212,170,0.24);
}
.outbound-awb-row.is-issued .outbound-status-pill {
  color: #c6cfdd;
  background: rgba(139,148,158,0.12);
}






/* Neutral text contrast pass: keep colored status/accent elements untouched. */
.row-label,
.glabs-id,
.outbound-glabs-summary::after,
.empty-state,
.last-refresh-text,
.legend-item span:last-child {
  color: var(--text-muted);
}

.lmp-text,
.row-value,
.outbound-awb-meta,
.outbound-lmp-meta,
.stat-label,
.countdown-text {
  color: var(--text-secondary);
}

.driver-text,
.no-driver-text,
.outbound-awb-code,
.outbound-summary-grid strong,
.outbound-lmp-name {
  color: var(--text-primary);
}






@keyframes detailsReveal {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ─── Empty / error ───────────────────────────────────────── */

.empty-state {
  text-align: center; padding: 80px 20px;
  color: var(--text-muted); font-size: 15px; font-weight: 500;
}
.error-toast {
  margin: 14px 32px 0; padding: 11px 16px;
  background: rgba(255,71,87,0.08);
  border: 1px solid rgba(255,71,87,0.22);
  border-radius: 7px; color: #ff4757;
  font-size: 13px; font-weight: 500;
}

/* ─── Scroll fade — liquid glass edge at bottom ──────────── */

.scroll-fade {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  height: 80px;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    rgba(13,16,32,0.80) 65%,
    rgba(13,16,32,0.97) 100%
  );
  backdrop-filter: blur(14px) saturate(160%);
  -webkit-backdrop-filter: blur(14px) saturate(160%);
  /* Mask feathers the whole element — backdrop-filter and overlay both fade in together */
  -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 45%);
  mask-image: linear-gradient(to bottom, transparent 0%, black 45%);
  pointer-events: none;
  z-index: 60;
}


/* ─── Scrollbar ───────────────────────────────────────────── */

::-webkit-scrollbar { width: 5px; height: 5px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.12); border-radius: 99px; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.22); }

/* Final liquid-glass pass: keep text crisp, make the surface itself liquid. */
.app-header,
.stats-bar,
.legend-bar,
.priority-card,
.kpi-card,
.kpi-bec-panel-inner,
.flow-switch,
.outbound-glabs-block,
.outbound-summary-grid > div {
  backdrop-filter: blur(16px) saturate(220%) brightness(1.10) contrast(1.03);
  -webkit-backdrop-filter: blur(16px) saturate(220%) brightness(1.10) contrast(1.03);
  box-shadow:
    0 8px 18px rgba(0,0,0,0.22),
    0 0 26px rgba(0,0,0,0.12),
    inset 2px 2px 1px rgba(255,255,255,0.30),
    inset -1px -1px 1px rgba(255,255,255,0.16),
    inset 0 0 28px var(--glow-ultra, rgba(255,255,255,0.045));
}
.app-header,
.stats-bar,
.legend-bar,
.kpi-card,
.kpi-bec-panel-inner,
.flow-switch {
  background:
    radial-gradient(110% 90% at 8% 0%, rgba(255,255,255,0.18), transparent 42%),
    linear-gradient(135deg, rgba(255,255,255,0.13), rgba(255,255,255,0.035)),
    rgba(6,8,18,0.30);
}
.priority-card {
  background:
    radial-gradient(ellipse 125% 68% at -10% -10%, var(--glow-tint, transparent) 0%, transparent 58%),
    radial-gradient(ellipse 90% 45% at 100% 0%, var(--glow-ultra, transparent) 0%, transparent 54%),
    rgba(255,255,255,0.045);
}



.outbound-glabs-block,
.outbound-summary-grid > div,
.kpi-card,
.kpi-bec-panel-inner {
  position: relative;
  overflow: hidden;
}
.outbound-glabs-block::before,
.outbound-summary-grid > div::before,
.kpi-card::before,
.kpi-bec-panel-inner::before {
  content: '';
  position: absolute;
  inset: 1px;
  border-radius: inherit;
  pointer-events: none;
  padding: 1px;
  background:
    linear-gradient(130deg, rgba(255,255,255,0.52), transparent 20% 72%, rgba(255,255,255,0.14)),
    radial-gradient(80% 120% at 0% 0%, rgba(255,255,255,0.20), transparent 48%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0.50;
  filter: blur(0.2px);
}
.outbound-glabs-block:hover::before,
.outbound-summary-grid > div:hover::before,
.kpi-card:hover::before,
.kpi-bec-panel-inner:hover::before {
  opacity: 0.82;
  filter: blur(0.45px) saturate(1.18);
}


/* ─── Opening animations — triggered by body.app-ready ──────── */
/*
   Timing (t=0 = overlay disappears):
     0.00s   header sweeps down
     0.14s   KPI group springs in
     0.38s   stats bar panel appears
     0.46–0.78s  stat items pop in (staggered 0.08s each)
     0.82s   legend bar slides up
     0.88–1.08s  legend items slide in (staggered 0.05s each)
     0.94s   cards area fades in; individual cards stagger inside
     1.10s   scroll-fade edge last
*/

/* 1 — Header sweeps in from above */
body.app-ready .app-header {
  animation: openHeader 0.72s cubic-bezier(0.22,1,0.36,1) 0.00s both;
}
@keyframes openHeader {
  from { opacity: 0; transform: translateY(-52px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* 2 — KPI kártyák egyenként spring-gel */
body.app-ready .kpi-muszak    { animation: openKpiCard 0.55s cubic-bezier(0.34,1.5,0.64,1) 0.16s both; }
body.app-ready .kpi-bec-wrapper { animation: openKpiCard 0.55s cubic-bezier(0.34,1.5,0.64,1) 0.32s both; }
@keyframes openKpiCard {
  from { opacity: 0; transform: translateY(-32px) scale(0.80); }
  to   { opacity: 1; transform: translateY(0)     scale(1);    }
}

/* 3 — Stats bar panel */
body.app-ready .stats-bar {
  animation: openPanel 0.40s cubic-bezier(0.4,0,0.2,1) 0.38s both;
}
@keyframes openPanel {
  from { opacity: 0; transform: translateY(-10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* 4 — Stat items pop in with spring bounce, staggered */
body.app-ready .stats-bar .stat-item:nth-child(1) { animation: openStat 0.42s cubic-bezier(0.34,1.55,0.64,1) 0.46s both; }
body.app-ready .stats-bar .stat-item:nth-child(2) { animation: openStat 0.42s cubic-bezier(0.34,1.55,0.64,1) 0.54s both; }
body.app-ready .stats-bar .stat-item:nth-child(3) { animation: openStat 0.42s cubic-bezier(0.34,1.55,0.64,1) 0.62s both; }
body.app-ready .stats-bar .stat-item:nth-child(4) { animation: openStat 0.42s cubic-bezier(0.34,1.55,0.64,1) 0.70s both; }
body.app-ready .stats-bar .stat-item:nth-child(5) { animation: openStat 0.42s cubic-bezier(0.34,1.55,0.64,1) 0.78s both; }
body.app-ready .stats-bar .stat-item:nth-child(6) { animation: openStat 0.42s cubic-bezier(0.34,1.55,0.64,1) 0.86s both; }
body.app-ready .stats-bar .stat-item:nth-child(7) { animation: openStat 0.42s cubic-bezier(0.34,1.55,0.64,1) 0.94s both; }
@keyframes openStat {
  from { opacity: 0; transform: translateY(16px) scale(0.82); }
  to   { opacity: 1; transform: translateY(0)    scale(1);    }
}

/* 5 — Legend bar slides up */
body.app-ready .legend-bar {
  animation: openLegend 0.44s cubic-bezier(0.4,0,0.2,1) 0.82s both;
}
@keyframes openLegend {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* 6 — Legend dots/labels slide in from left, staggered */
body.app-ready .legend-bar .legend-item:nth-child(1) { animation: openLegendItem 0.32s cubic-bezier(0.34,1.35,0.64,1) 0.88s both; }
body.app-ready .legend-bar .legend-item:nth-child(2) { animation: openLegendItem 0.32s cubic-bezier(0.34,1.35,0.64,1) 0.93s both; }
body.app-ready .legend-bar .legend-item:nth-child(3) { animation: openLegendItem 0.32s cubic-bezier(0.34,1.35,0.64,1) 0.98s both; }
body.app-ready .legend-bar .legend-item:nth-child(4) { animation: openLegendItem 0.32s cubic-bezier(0.34,1.35,0.64,1) 1.03s both; }
body.app-ready .legend-bar .legend-item:nth-child(5) { animation: openLegendItem 0.32s cubic-bezier(0.34,1.35,0.64,1) 1.08s both; }
body.app-ready .legend-bar .legend-item:nth-child(6) { animation: openLegendItem 0.32s cubic-bezier(0.34,1.35,0.64,1) 1.13s both; }
@keyframes openLegendItem {
  from { opacity: 0; transform: translateX(-14px) scale(0.88); }
  to   { opacity: 1; transform: translateX(0)     scale(1);    }
}

/* 7 — A kártyák saját fadeUp animációval jönnek be (backwards fill-mode),
        nincs szükség container animációra — nem ismétlődne jól pollon */

/* 8 — Scroll fade enters last */
body.app-ready .scroll-fade {
  animation: openScrollFade 1.0s ease 1.10s both;
}
@keyframes openScrollFade {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* 9 — Cím spelling: betűk egyenként pottyannak le */
body.app-ready .app-title .title-letter {
  animation: letterReveal 0.32s cubic-bezier(0.34,1.45,0.64,1) both;
}
@keyframes letterReveal {
  from { opacity: 0; transform: translateY(-14px) scale(0.6); }
  to   { opacity: 1; transform: translateY(0)     scale(1);   }
}
/* 20 betű, 0.04s stagger, 0.06s alap delay */
body.app-ready .app-title .title-letter:nth-child(1)  { animation-delay: 0.06s; }
body.app-ready .app-title .title-letter:nth-child(2)  { animation-delay: 0.10s; }
body.app-ready .app-title .title-letter:nth-child(3)  { animation-delay: 0.14s; }
body.app-ready .app-title .title-letter:nth-child(4)  { animation-delay: 0.18s; }
body.app-ready .app-title .title-letter:nth-child(5)  { animation-delay: 0.22s; }
body.app-ready .app-title .title-letter:nth-child(6)  { animation-delay: 0.26s; }
body.app-ready .app-title .title-letter:nth-child(7)  { animation-delay: 0.30s; }
body.app-ready .app-title .title-letter:nth-child(8)  { animation-delay: 0.34s; }
body.app-ready .app-title .title-letter:nth-child(9)  { animation-delay: 0.38s; }
body.app-ready .app-title .title-letter:nth-child(10) { animation-delay: 0.42s; }
body.app-ready .app-title .title-letter:nth-child(11) { animation-delay: 0.46s; }
body.app-ready .app-title .title-letter:nth-child(12) { animation-delay: 0.50s; }
body.app-ready .app-title .title-letter:nth-child(13) { animation-delay: 0.54s; }
body.app-ready .app-title .title-letter:nth-child(14) { animation-delay: 0.58s; }
body.app-ready .app-title .title-letter:nth-child(15) { animation-delay: 0.62s; }
body.app-ready .app-title .title-letter:nth-child(16) { animation-delay: 0.66s; }
body.app-ready .app-title .title-letter:nth-child(17) { animation-delay: 0.70s; }
body.app-ready .app-title .title-letter:nth-child(18) { animation-delay: 0.74s; }
body.app-ready .app-title .title-letter:nth-child(19) { animation-delay: 0.78s; }
body.app-ready .app-title .title-letter:nth-child(20) { animation-delay: 0.82s; }

/* Performance pass for outbound-heavy views.
   Primary surfaces keep liquid glass; nested rows avoid blur, masks and filters. */
.app-header,
.stats-bar,
.legend-bar,
.priority-card,
.kpi-card,
.kpi-bec-panel-inner,
.flow-switch {
  backdrop-filter: blur(10px) saturate(165%) brightness(1.06);
  -webkit-backdrop-filter: blur(10px) saturate(165%) brightness(1.06);
}



.priority-card,
.outbound-glabs-block,
.outbound-awb-row,
.outbound-summary-grid > div,
.kpi-card,
.kpi-bec-panel-inner {
