              transform .16s cubic-bezier(.22,1,.36,1), box-shadow .2s ease;
}
/* Leading status dot — empty ring when idle, filled glow when active. */
.uld-stack-tool-btn::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: 0 0 auto;
  border: 1.5px solid currentColor;
  background: transparent;
  opacity: .55;
  transition: background .2s ease, box-shadow .2s ease, opacity .2s ease, transform .2s ease;
