  border-color: #818cf8;
  color: #e0e7ff;
  box-shadow: 0 0 0 1px rgba(129,140,248,.35) inset, 0 4px 16px rgba(99,102,241,.30);
}
.uld-stack-tool-btn.uld-stack-tool-active::before {
  background: #c7d2fe;
  border-color: #c7d2fe;
  opacity: 1;
  /* Static glow — the former infinite box-shadow pulse caused a continuous flicker
     and forced a repaint every frame, which stutters on weaker machines. */
  box-shadow: 0 0 10px rgba(199,210,254,.95), 0 0 3px rgba(255,255,255,.85);
