  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: .8px;
  margin: 0;
}
.uld-new-stack-btn {
  padding: 7px 14px;
  border-radius: 8px;
  border: 1px dashed rgba(99,102,241,.40);
  background: rgba(99,102,241,.08);
  color: #a5b4fc;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .3px;
  cursor: pointer;
  transition: background .18s ease, border-color .18s ease, color .18s ease, transform .18s ease, box-shadow .18s ease;
}
.uld-new-stack-btn:hover {
  background: rgba(99,102,241,.18);
  border-color: #6366f1;
  border-style: solid;
  color: #c7d2fe;
  transform: translateY(-1px);
  box-shadow: 0 6px 18px rgba(99,102,241,.30);
}
.uld-new-stack-btn:active { transform: translateY(0); }
.uld-new-stack-btn:disabled,
.uld-new-stack-btn.uld-op-busy {
  opacity: .72;
  cursor: progress;
  transform: none;
  border-style: solid;
}



/* Single-column accordion: collapsed stacks stack vertically; ~4 headers fit
   the scroll viewport (JS caps the height to 4 stacks — see capStackGridHeight). */
.uld-stacks-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-content: start;
  /* The real scroll container. A STABLE definite cap (not toggled on open/close)
     guarantees scrolling once content is tall, while staying compact when short:
     height = min(content, this cap). The 52px ≈ the "STACK-EK" header bar + gaps.
     --uld-sticky-top is kept in sync with the page header by updateStickyOffset(). */
  max-height: calc(100vh - var(--uld-sticky-top, 96px) - 16px - 52px);
  overflow-y: auto;
  overflow-x: hidden;
  /* room so cards / scrollbar don't sit under the glass rim */
  padding-right: 4px;
  scroll-behavior: smooth;
}
.uld-stacks-empty {
  grid-column: 1 / -1;
  font-size: 13px;
  color: var(--text-muted);
  text-align: center;
  padding: 32px 16px;
  border: 1.5px dashed var(--border);
  border-radius: 12px;
  background: rgba(255,255,255,.02);
}

/* Stack card */
.uld-stack {
  border: 1.5px solid var(--stack-gha-border, rgba(255,255,255,0.2));
  border-radius: 16px;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
  box-shadow: 0 0 0 0 var(--stack-gha-glow, transparent);
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
  position: relative;
  contain: layout paint style;
  will-change: transform;
}
.uld-stack:hover {
  transform: translateY(-2px);
  border-color: var(--stack-gha-border, rgba(99,102,241,0.40));
  box-shadow: 0 10px 26px rgba(0,0,0,0.30);
}
/* Drop target highlight — solid + box-shadow only (no layout shift) */
.uld-stack.uld-drop-over {
  border-color: #6366f1;
  background: linear-gradient(135deg, rgba(99,102,241,.14), rgba(99,102,241,.04));
  box-shadow: 0 0 0 2px rgba(99,102,241,.36);
  transform: translateY(-2px);
}
.uld-stack.uld-gha-blocked {
  opacity: 0.55;
  border-color: rgba(239,68,68,.48) !important;
  box-shadow: 0 0 0 2px rgba(239,68,68,.22) !important;
  cursor: not-allowed;
}
.uld-stack.uld-stack-deleting {
  pointer-events: none;
  overflow: hidden;
  transform-origin: center top;
  animation: uldStackDelete .3s cubic-bezier(.55,0,.67,.2) both;
}
@keyframes uldStackDelete {
  0%   { opacity: 1; transform: scale(1) translateX(0); filter: blur(0); max-height: 600px; }
  35%  { opacity: .7; transform: scale(.97) translateX(10px); filter: blur(.4px); }
  100% { opacity: 0; transform: scale(.9) translateX(40px); filter: blur(2px); max-height: 0; margin: 0; padding-top: 0; padding-bottom: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .uld-stack.uld-stack-deleting { animation: none; opacity: .4; }
}
.uld-stack.uld-stack-dispatching {
  pointer-events: none;
  overflow: hidden;
  transform-origin: center top;
  animation: uldStackDispatch .38s cubic-bezier(.22,1,.36,1) both;
}
@keyframes uldStackDispatch {
  0%   { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); max-height: 680px; }
  45%  { opacity: .82; transform: translateY(-4px) scale(.985); filter: blur(.2px); box-shadow: 0 0 0 1px rgba(56,189,248,.5), 0 12px 32px rgba(56,189,248,.16); }
  100% { opacity: 0; transform: translateY(-20px) scale(.94); filter: blur(1.5px); max-height: 0; margin: 0; padding-top: 0; padding-bottom: 0; }
}
.uld-row.uld-row-dispatching {
  pointer-events: none;
  animation: uldRowDispatch .34s cubic-bezier(.22,1,.36,1) both;
}
@keyframes uldRowDispatch {
  0% { opacity: 1; transform: translateX(0); }
  100% { opacity: .18; transform: translateX(22px); filter: grayscale(.7); }
}
@media (prefers-reduced-motion: reduce) {
  .uld-stack.uld-stack-dispatching,
  .uld-row.uld-row-dispatching { animation: none; opacity: .35; }
}
.uld-stack.uld-stack-just-created {
  animation: uldStackPop .9s cubic-bezier(0.22,1,0.36,1);
}

/* ── "Összekészítve" toggle button ───────────────────────────────────── */
