/* ── Prepared stack visual: faded + grayscale + smooth entry ──────────
   !important so this state wins over search-hit / hover / theme toggles.
   The fade+dashed border IS the lock indicator. */
.uld-stack.uld-stack-prepared,
body.flow-uld-mode .uld-stack.uld-stack-prepared,
.uld-stack[data-prepared="1"] {
  opacity: .58 !important;
  filter: saturate(.45) !important;
  border-style: dashed !important;
  transition: opacity .42s cubic-bezier(0.22,1,0.36,1),
              filter .42s ease,
              transform .42s cubic-bezier(0.22,1,0.36,1),
              border-color .3s ease,
              box-shadow .3s ease;
}
/* Items in a prepared stack: not draggable, no remove button, lock cursor. */
.uld-stack.uld-stack-prepared .uld-si,
.uld-stack[data-prepared="1"] .uld-si {
  cursor: not-allowed !important;
}
.uld-stack.uld-stack-prepared .uld-si-remove,
.uld-stack[data-prepared="1"] .uld-si-remove {
  display: none !important;
}
/* Rows whose ULD lives in a prepared stack: not selectable, not draggable.
   The faded look + dashed border already signals the lock visually. */
.uld-row.uld-row-prepared,
.uld-row[data-prepared="1"] {
  cursor: not-allowed !important;
}
/* Selection-bar target chip: prepared stack rejects drops, show clear lock. */
.uld-target-chip.uld-target-chip-prepared {
  opacity: .38 !important;
  cursor: not-allowed !important;
  filter: grayscale(.4) !important;
  text-decoration: line-through !important;
  border-style: dashed !important;
}
.uld-stack.uld-stack-prepared:hover,
body.flow-uld-mode .uld-stack.uld-stack-prepared:hover {
  opacity: .82 !important;
  filter: saturate(.75) !important;
}
.uld-stack.uld-stack-prepared .uld-si,
.uld-stack[data-prepared="1"] .uld-si {
  opacity: .82 !important;
  filter: saturate(.65) !important;
  transition: opacity .32s ease, filter .32s ease;
}

/* ── Prepared row in the list: faded + dashed, persists during search ── */
.uld-row.uld-row-prepared,
.uld-row[data-prepared="1"],
body.flow-uld-mode .uld-row.uld-row-prepared {
  opacity: .50 !important;
  filter: saturate(.5) !important;
  border-style: dashed !important;
  transition: opacity .42s cubic-bezier(0.22,1,0.36,1),
              filter .42s ease,
              transform .42s cubic-bezier(0.22,1,0.36,1),
              border-color .3s ease;
}
.uld-row.uld-row-prepared:hover,
body.flow-uld-mode .uld-row.uld-row-prepared:hover {
  opacity: .85 !important;
  filter: saturate(.85) !important;
}
@keyframes uldStackPop {
