/* ── Accordion stacks ───────────────────────────────────────────────────
   Each non-empty stack collapses to just its header so ~4 fit on screen.
   The whole header is the toggle (clicks on action buttons and the rename
   name are excluded in JS). uld_manager.js measures heights and animates
   open/close; the rules here are the pre-JS collapsed fallback so there is
   no flash on load. Multiple stacks may be open at once. */
.uld-stack-collapsible .uld-stack-hdr {
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  transition: background .16s ease, border-color .18s ease;
}
.uld-stack-collapsible:not(.uld-stack-expanded) .uld-stack-hdr {
  border-bottom-color: transparent;
}
.uld-stack-collapsible .uld-stack-hdr:hover { background: rgba(99,102,241,0.10); }


/* Caret — rotates ▸ → ▾ when the stack opens. Hidden for empty/non-collapsible
   stacks (they're always open, so a toggle indicator would be misleading). */
.uld-stack-caret { display: none; }
.uld-stack-collapsible .uld-stack-caret {
  display: inline-block;
  flex-shrink: 0;
  width: 14px;
  text-align: center;
  font-size: 10px;
  line-height: 1;
  color: var(--text-muted);
  transition: transform .3s cubic-bezier(.22,1,.36,1), color .16s ease;
}
.uld-stack-accordion .uld-stack-hdr:hover .uld-stack-caret { color: #a5b4fc; }
.uld-stack-expanded .uld-stack-caret { transform: rotate(90deg); color: #a5b4fc; }

/* Collapsible body — overflow clipped, max-height animated. When a stack holds
   many ULDs the body caps at ~50vh and scrolls internally (JS controls the px
   max-height + overflow), so 3 open big stacks each stay reachable. */
.uld-stack-collapsible .uld-stack-body {
  overflow: hidden;
  max-height: 0;
  opacity: .25;
  overscroll-behavior: contain;
  transition: max-height .34s cubic-bezier(.22,1,.36,1), opacity .24s ease;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,.18) transparent;
}
.uld-stack-collapsible.uld-stack-expanded .uld-stack-body {
  opacity: 1;   /* max-height + overflow set inline by JS */
}
/* Empty / non-collapsible stacks always show their body (drop hint visible). */
.uld-stack:not(.uld-stack-collapsible) .uld-stack-body {
  max-height: none;
  opacity: 1;
}
.uld-stack-body::-webkit-scrollbar { width: 7px; }
.uld-stack-body::-webkit-scrollbar-thumb { background: rgba(255,255,255,.16); border-radius: 6px; }
.uld-stack-body::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,.28); }

/* In a single-column accordion the 3D tilt-on-hover reads as jitter and the
   preserve-3d/will-change layers can paint one header over the next — keep a
   calm, flat hover (border/shadow only, no lift, no 3D context). */
.uld-stack-accordion,
body.flow-uld-mode .uld-stack-accordion {
  transform-style: flat;
  will-change: auto;
}
.uld-stack-accordion:hover,
body.flow-uld-mode .uld-stack-accordion:hover { transform: none; }

/* Stronger, GHA-tinted borders so stacks read clearly when there are many.
   (The flow-uld glass layer flattened every border to a faint blue — restore
   the GHA colour and bump the weight.) */
.uld-stack-accordion { border-width: 1.5px; }
body.flow-uld-mode .uld-stack-accordion {
  border-color: var(--stack-gha-border, rgba(190,212,255,0.30)) !important;
}

/* Open stacks pop a touch more so the active one is obvious. */
.uld-stack-accordion.uld-stack-expanded {
  border-color: var(--stack-gha-border, rgba(129,140,248,0.55)) !important;
  box-shadow: 0 8px 22px rgba(0,0,0,0.28);
}

.uld-stack-empty-hint {
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  padding: 14px 8px;
  font-style: italic;
  border: 1.5px dashed rgba(255,255,255,0.10);
  border-radius: 8px;
  background: rgba(255,255,255,0.02);
  transition: border-color .22s ease, background .22s ease;
}
body.uld-drag-active .uld-stack-empty-hint {
  border-color: rgba(99,102,241,.40);
  background: rgba(99,102,241,.08);
  color: #a5b4fc;
}

/* Stack items — draggable for stack-internal reorder */
.uld-si {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 8px 10px 8px 11px;
  border-radius: 11px;
  border: 1px solid rgba(255,255,255,0.08);
  background: rgba(255,255,255,0.05);
  position: relative;
  transition: background .15s ease, border-color .15s ease, transform .15s ease, box-shadow .15s ease;
  cursor: grab;
  contain: layout paint style;
}
.uld-si:active { cursor: grabbing; }
.uld-si.uld-dragging { opacity: .45; cursor: grabbing; }
.uld-si:hover {
  background: rgba(255,255,255,0.09);
  border-color: rgba(255,255,255,0.18);
}
.uld-si.uld-selected,
body.flow-uld-mode .uld-si.uld-selected {
  opacity: 1 !important;
  filter: none !important;
  border-color: rgba(99,102,241,.88) !important;
  background: linear-gradient(135deg, rgba(99,102,241,.26), rgba(99,102,241,.11)) !important;
  box-shadow:
    0 0 0 1px rgba(99,102,241,.55) inset,
    0 0 0 2px rgba(99,102,241,.30),
    0 8px 22px rgba(99,102,241,.22) !important;
}
.uld-si.uld-selected::before {
  background: linear-gradient(180deg, #818cf8, #4f46e5) !important;
  width: 6px;
}

.uld-si-search-hit {
  border-color: rgba(250,204,21,.62);
  background: rgba(250,204,21,.10);
}
/* Drop-position indicators — ::after line, no layout shift, doesn't fight ::before */
.uld-si.uld-si-drop-above::after,
.uld-si.uld-si-drop-below::after,
.uld-si.uld-si-drop-before::after,
.uld-si.uld-si-drop-after::after {
  content: '';
  position: absolute;
  background: #6366f1;
  border-radius: 2px;
  box-shadow: 0 0 10px rgba(99,102,241,.7);
  pointer-events: none;
  z-index: 3;
}
.uld-si.uld-si-drop-above::after,
.uld-si.uld-si-drop-below::after {
  left: 4px;
  right: 4px;
  height: 3px;
}
.uld-si.uld-si-drop-above::after { top: -3px; }
.uld-si.uld-si-drop-below::after { bottom: -3px; }
.uld-si.uld-si-drop-before::after,
.uld-si.uld-si-drop-after::after {
  top: 5px;
  bottom: 5px;
  width: 3px;
}
.uld-si.uld-si-drop-before::after { left: 6px; }
.uld-si.uld-si-drop-after::after { right: 6px; }
.uld-si::before {
  content: '';
  position: absolute;
  left: -1px; top: -1px; bottom: -1px;
  width: 4px;
  border-radius: 11px 0 0 11px;
}
.uld-si-ok::before       { background: linear-gradient(180deg, #22c55e, #16a34a); }
.uld-si-warning::before  { background: linear-gradient(180deg, #f59e0b, #d97706); }
.uld-si-critical::before { background: linear-gradient(180deg, #ef4444, #dc2626); }
.uld-si-expired::before  { background: linear-gradient(180deg, #f87171, #ef4444); }
.uld-si-manual::before   { background: linear-gradient(180deg, #a78bfa, #6366f1); }
.uld-si-inactive::before { background: linear-gradient(180deg, #64748b, #334155); }




/* 1-based stacking-order badge (top of stack = 1). The single, clear order cue —
   a round chip tinted by the ULD prefix colour (set inline per item). Replaces
   the old 3-letter type box, so each row stays readable even in columns. */
.uld-si-index {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  font-size: 12px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--uld-index-text, #fff);
  border: 2px solid var(--uld-index-ring, currentColor);
  background: linear-gradient(135deg, var(--uld-index-bg, rgba(99,102,241,.92)), var(--uld-index-bg-soft, rgba(99,102,241,.58)));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.20),
    0 0 0 1px rgba(255,255,255,.08),
    0 7px 16px rgba(0,0,0,.24);
  text-shadow: 0 1px 2px rgba(0,0,0,.45);
  transition: transform .16s cubic-bezier(.22,1,.36,1), box-shadow .18s ease;
}
.uld-si:hover .uld-si-index {
  transform: scale(1.06);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.26),
    0 0 0 1px rgba(255,255,255,.12),
    0 9px 20px rgba(0,0,0,.30);
}
/* Top / bottom of the stack get a small caret marker above/below the chip so the
   physical orientation is obvious without extra text. */
.uld-si-index-top,
.uld-si-index-bottom { position: relative; }
.uld-si-index-top::after,
.uld-si-index-bottom::after {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  font-size: 8px;
  font-weight: 900;
  line-height: 1;
  opacity: .85;
  color: inherit;
}
.uld-si-index-top::after    { content: '▲'; top: -8px; }
.uld-si-index-bottom::after { content: '▼'; bottom: -8px; }
/* Focus mode: the order chip is the key cue, so maximise legibility — a bright
   bold numeral on a dark fill, with the prefix colour kept as a glowing ring.
   (Inline color/background are overridden; the inline border-color stays.) */
body.uld-stacks-focus .uld-si-index {
  color: #fff !important;
  background: linear-gradient(135deg, rgba(15,23,42,.96), rgba(30,41,59,.88)) !important;
  border-width: 2px;
  font-size: 13px;
  font-weight: 900;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.20),
    0 0 0 1px rgba(255,255,255,.16),
    0 0 0 3px var(--uld-index-bg-soft, rgba(99,102,241,.28)),
    0 8px 18px rgba(0,0,0,.30);
  text-shadow: 0 1px 2px rgba(0,0,0,.6);
}


/* Stale stack card hidden (not removed) pending the Dash unmount — see
   applyServerStackState. Keeping the node lets React tear it down safely. */
.uld-stack.uld-stack-gone { display: none !important; }
.uld-stack-inactive {
  opacity: .72;
}
.uld-stack-inactive .uld-stack-hdr {
  background: rgba(100,116,139,.10);
}
.uld-si-inactive {
  opacity: .58;
  border-style: dashed;
  background: rgba(100,116,139,.09);
  filter: saturate(.55);
}
.uld-si-inactive:hover {
  opacity: .82;
  background: rgba(100,116,139,.13);
}



.uld-si-top {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
}
/* Search-match highlight on active-page stack items — same amber language as the
   dispatched view, so a searched ULD that sits inside a stack is unmistakable.
   Stacks with a hit auto-open (even when prepared/collapsed), so this stays visible. */
.uld-si.uld-si-search-match {
  border-color: #eab308 !important;
  background: linear-gradient(135deg, rgba(253,224,71,.22), rgba(250,204,21,.13)) !important;
  box-shadow: 0 0 0 1px rgba(250,204,21,.5) inset, 0 0 14px -2px rgba(250,204,21,.55) !important;
}
.uld-si.uld-si-search-match .uld-si-num { color: #fde047; }



.uld-si-num {
  font-size: 12px;
  font-weight: 800;
  font-family: monospace;
