  padding: 2px 7px;
  line-height: 1.2;
  transition: background .15s, color .15s, border-color .15s, transform .15s;
}
.uld-stack-print:hover {
  background: rgba(99,102,241,.16);
  color: #c7d2fe;
  border-color: rgba(99,102,241,.45);
