}
.uld-stack-copy:hover {
  background: rgba(34,197,94,.14);
  color: #86efac;
  border-color: rgba(34,197,94,.45);
  transform: scale(1.06);
}
.uld-stack-print:active, .uld-stack-copy:active, .uld-stack-del:active, .uld-stack-dispatch-btn:active { transform: scale(.94); }

/* ULD delete modal */
.uld-delete-modal {
  position: fixed;
  inset: 0;
  z-index: 10002;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(0,0,0,.62);
  backdrop-filter: blur(6px);
}
.uld-delete-modal.uld-delete-modal-show {
  display: flex;
  animation: fadeIn .18s ease;
}
.uld-delete-modal.uld-delete-modal-closing { animation: fadeOut .2s ease forwards; }
@keyframes fadeOut { to { opacity: 0; } }
.uld-delete-dialog {
  width: min(520px, 100%);
  max-height: min(82vh, 720px);
  display: flex;
  flex-direction: column;
  border-radius: 16px;
  background:
    radial-gradient(120% 70% at 0% -10%, rgba(239,68,68,.12), transparent 55%),
    #1a1d2e;
  border: 1px solid rgba(239,68,68,.38);
  box-shadow: 0 28px 80px rgba(0,0,0,.6), 0 0 0 1px rgba(239,68,68,.12);
  padding: 22px 22px 20px;
  animation: uldDeleteDialogIn .34s cubic-bezier(.22,1,.36,1);
}
.uld-delete-modal-closing .uld-delete-dialog {
  animation: uldDeleteDialogOut .2s cubic-bezier(.55,0,.67,.2) forwards;
}
@keyframes uldDeleteDialogIn {
  0%   { opacity: 0; transform: translateY(14px) scale(.96); }
  100% { opacity: 1; transform: none; }
}
@keyframes uldDeleteDialogOut {
  0%   { opacity: 1; transform: none; }
  100% { opacity: 0; transform: translateY(8px) scale(.97); }
}
.uld-delete-kicker {
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .8px;
  color: #fca5a5;
  margin-bottom: 6px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
}
.uld-delete-kicker::before {
  content: '⚠';
  font-size: 12px;
}
.uld-delete-title {
  font-size: 19px;
  font-weight: 850;
  color: #fff;
  margin-bottom: 12px;
  letter-spacing: -.01em;
  word-break: break-word;
}
.uld-delete-text {
  font-size: 13px;
  line-height: 1.45;
  color: var(--text-muted);
  margin-bottom: 18px;
  overflow-y: auto;
  min-height: 0;
  flex: 1 1 auto;
  padding-right: 4px;
}
.uld-delete-text::-webkit-scrollbar { width: 8px; }
.uld-delete-text::-webkit-scrollbar-thumb { background: rgba(255,255,255,.16); border-radius: 4px; }

/* Summary pills */
.uld-delete-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 12px;
}
.uld-delete-pill {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .2px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid transparent;
}
.uld-delete-pill-count { color: #fecaca; background: rgba(239,68,68,.16); border-color: rgba(239,68,68,.4); }
.uld-delete-pill-gha { color: #c7d2fe; background: rgba(99,102,241,.16); border-color: rgba(99,102,241,.4); }
.uld-delete-pill-inactive { color: #cbd5e1; background: rgba(100,116,139,.2); border-color: rgba(148,163,184,.34); }
.uld-delete-hint {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 10px;
}
.uld-delete-empty {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 12px;
  background: rgba(255,255,255,.04);
  border: 1px dashed rgba(255,255,255,.14);
}
.uld-delete-empty-icon { font-size: 26px; color: #64748b; line-height: 1; }

/* ULD list inside the delete dialog */
.uld-delete-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.uld-delete-item {
  display: grid;
  grid-template-columns: 28px minmax(0, 1.3fr) auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.07);
  border-left: 3px solid var(--dc, #64748b);
  opacity: 0;
  transform: translateX(-8px);
  animation: uldDeleteRowIn .32s cubic-bezier(.22,1,.36,1) forwards;
  animation-delay: calc(var(--i, 0) * 28ms + 80ms);
}
@keyframes uldDeleteRowIn {
  to { opacity: 1; transform: none; }
}
.uld-delete-item-inactive { filter: grayscale(.4); }
.uld-delete-item-inactive .uld-delete-uld { color: var(--text-muted); }
.uld-delete-pos {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.uld-delete-uld {
  font-family: ui-monospace, "Cascadia Code", monospace;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .4px;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.uld-delete-gha {
  font-size: 11px;
  font-weight: 700;
  color: #c7d2fe;
  white-space: nowrap;
}
.uld-delete-gha-none { color: var(--text-muted); }
.uld-delete-awb {
  font-family: ui-monospace, "Cascadia Code", monospace;
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: right;
}
.uld-delete-tag {
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .35px;
  color: #cbd5e1;
  padding: 2px 6px;
  border-radius: 999px;
  background: rgba(100,116,139,.22);
  border: 1px solid rgba(148,163,184,.3);
  white-space: nowrap;
}




