/* ULD manual add modal */
.uld-manual-modal {
  position: fixed;
  inset: 0;
  z-index: 10003;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background:
    radial-gradient(48% 38% at 48% 14%, rgba(255,255,255,.08), transparent 58%),
    radial-gradient(54% 44% at 50% 18%, rgba(99,102,241,.16), transparent 66%),
    radial-gradient(38% 30% at 18% 84%, rgba(14,165,233,.11), transparent 68%),
    linear-gradient(135deg, rgba(15,23,42,.28), rgba(2,6,23,.46)),
    rgba(2,6,23,.30);
  backdrop-filter: blur(9px) saturate(138%) contrast(1.02);
  -webkit-backdrop-filter: blur(9px) saturate(138%) contrast(1.02);
}
.uld-manual-modal.uld-manual-modal-show {
  display: flex;
  animation: fadeIn .16s ease;
}
.uld-manual-modal.uld-manual-modal-morphing {
  pointer-events: none;
  background:
    radial-gradient(42% 32% at 50% 22%, rgba(99,102,241,.16), transparent 68%),
    rgba(2,6,23,.22);
  animation: uldManualBackdropLift .42s cubic-bezier(.22,1,.36,1) forwards;
}
.uld-manual-modal.uld-manual-modal-closing {
  display: flex;
  animation: uldManualFadeOut .22s ease forwards;
}
.uld-manual-dialog {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  width: min(590px, 96vw);
  border: 1px solid rgba(225,242,255,.23);
  border-radius: 16px;
  background:
    radial-gradient(82% 60% at 12% -8%, rgba(255,255,255,.26), transparent 48%),
    radial-gradient(78% 74% at 108% 2%, rgba(99,102,241,.22), transparent 54%),
    radial-gradient(58% 74% at 0% 110%, rgba(14,165,233,.14), transparent 56%),
    linear-gradient(132deg, rgba(255,255,255,.155), rgba(255,255,255,.055) 44%, rgba(255,255,255,.095)),
    rgba(13,18,32,.64);
  backdrop-filter: blur(28px) saturate(190%) brightness(1.08);
  -webkit-backdrop-filter: blur(28px) saturate(190%) brightness(1.08);
  box-shadow:
    0 34px 92px rgba(0,0,0,.52),
    0 12px 34px rgba(99,102,241,.20),
    0 0 0 1px rgba(255,255,255,.045),
    inset 1px 1px 0 rgba(255,255,255,.34),
    inset -1px -1px 0 rgba(255,255,255,.075);
  padding: 20px;
  transform-origin: center;
  animation: uldManualIn .24s cubic-bezier(.22,1,.36,1);
}
.uld-manual-modal-morphing .uld-manual-dialog {
  animation: uldManualDialogCollapse .34s cubic-bezier(.22,1,.36,1) forwards;
}
.uld-manual-dialog::before {
  content: "";
  position: absolute;
  inset: -1px;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(1px 1px at 18% 22%, rgba(255,255,255,.48), transparent),
    radial-gradient(1px 1px at 72% 34%, rgba(255,255,255,.28), transparent),
    radial-gradient(1px 1px at 44% 78%, rgba(255,255,255,.20), transparent),
    linear-gradient(112deg, rgba(255,255,255,.34), transparent 18%, transparent 62%, rgba(255,255,255,.11)),
    linear-gradient(180deg, rgba(255,255,255,.11), transparent 42%);
  opacity: .86;
}
.uld-manual-dialog::after {
  content: "";
  position: absolute;
  left: -18%;
  right: -18%;
  top: -35%;
  height: 72%;
  background:
    linear-gradient(102deg, transparent 18%, rgba(255,255,255,.32) 44%, rgba(255,255,255,.06) 55%, transparent 76%);
  opacity: .44;
  transform: rotate(-3deg);
  pointer-events: none;
}
.uld-manual-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
}
.uld-manual-kicker {
  color: #a5b4fc;
  font-size: .72rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .08em;
}
.uld-manual-title {
  color: #f8fafc;
  font-size: 1.15rem;
  font-weight: 900;
  line-height: 1.2;
}
.uld-manual-close {
  width: 32px;
  height: 32px;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 8px;
  background: rgba(255,255,255,.05);
  color: #cbd5e1;
  cursor: pointer;
  transition: background .16s ease, transform .14s ease, border-color .16s ease;
}
.uld-manual-close:hover {
  background: rgba(239,68,68,.13);
  border-color: rgba(239,68,68,.36);
  color: #fecaca;
  transform: scale(1.04);
}
.uld-manual-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.uld-manual-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: #94a3b8;
  font-size: .78rem;
  font-weight: 800;
}
.uld-manual-input {
  width: 100%;
  min-height: 40px;
  border: 1px solid rgba(210,230,255,.16);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.075), rgba(255,255,255,.025)),
    rgba(15,23,42,.58);
  color: #f8fafc;
  padding: 8px 10px;
  outline: none;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08);
