}
.uld-manual-input:focus {
  border-color: rgba(129,140,248,.70);
  box-shadow:
    0 0 0 3px rgba(99,102,241,.18),
    0 14px 30px rgba(15,23,42,.22),
    inset 0 1px 0 rgba(255,255,255,.12);
  background:
    linear-gradient(180deg, rgba(255,255,255,.105), rgba(255,255,255,.035)),
    rgba(15,23,42,.86);
  transform: translateY(-1px);
}
.uld-manual-input:disabled,
.uld-manual-input-locked {
  color: #dbeafe;
  border-color: rgba(14,165,233,.34);
  background:
    radial-gradient(100% 120% at 12% 0%, rgba(14,165,233,.18), transparent 54%),
    linear-gradient(180deg, rgba(255,255,255,.085), rgba(255,255,255,.025)),
    rgba(15,23,42,.62);
  cursor: default;
  opacity: 1;
}
.uld-manual-field em {
  color: #fbbf24;
  font-style: normal;
  font-size: .68rem;
  font-weight: 850;
}
.uld-manual-select {
  appearance: auto;
}
.uld-manual-note {
  min-height: 18px;
  color: #93c5fd;
  font-size: .69rem;
  font-weight: 850;
  letter-spacing: 0;
  line-height: 1.25;
