  transform: translateY(-1px);
}
.uld-manual-time-field {
  grid-column: 1 / -1;
  gap: 7px;
}
.uld-manual-datetime {
  flex: 1 1 auto;
  min-height: 34px;
  height: 34px;
  max-width: 300px;
  font-size: 12px;
  /* Dark UA widgets (spinners + picker popup) on the dark modal. */
  color-scheme: dark;
}
/* Force the native calendar/clock picker icon white so it reads on the dark
   glass modal instead of the default near-black glyph. */
.uld-manual-datetime::-webkit-calendar-picker-indicator {
  filter: invert(1) brightness(1.8);
  opacity: .85;
  cursor: pointer;
  transition: opacity .15s ease;
}
.uld-manual-datetime::-webkit-calendar-picker-indicator:hover {
  opacity: 1;
}
.uld-manual-time-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 350px;
}
.uld-manual-datetime-clear {
  flex: 0 0 auto;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 8px;
  background:
    linear-gradient(145deg, rgba(255,255,255,.075), rgba(255,255,255,.025)),
    rgba(15,23,42,.45);
  color: #cbd5e1;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
  transition: transform .15s ease, background .15s ease, border-color .15s ease, color .15s ease;
}
.uld-manual-datetime-clear:hover {
