  border: 1px solid rgba(251,191,36,.28);
  background:
    radial-gradient(80% 120% at 0% 0%, rgba(251,191,36,.16), transparent 52%),
    linear-gradient(145deg, rgba(255,255,255,.095), rgba(255,255,255,.028)),
    rgba(30,23,12,.48);
  box-shadow: inset 1px 1px 0 rgba(255,255,255,.15), 0 16px 36px rgba(0,0,0,.22);
  padding: 12px;
}
.uld-manual-duplicate-show {
  display: block;
  animation: uldDuplicateIn .22s cubic-bezier(.22,1,.36,1);
}
.uld-manual-error-show {
  border-color: rgba(248,113,113,.42);
  background:
    radial-gradient(80% 120% at 0% 0%, rgba(248,113,113,.18), transparent 52%),
    linear-gradient(145deg, rgba(255,255,255,.095), rgba(255,255,255,.028)),
    rgba(38,15,18,.54);
}
.uld-manual-input-error {
  border-color: rgba(248,113,113,.72) !important;
  box-shadow: 0 0 0 3px rgba(248,113,113,.18) !important;
}
.uld-manual-field-error {
