  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: #fde68a;
  margin-bottom: 9px;
}
.uld-manual-duplicate-kicker {
  color: #fbbf24;
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}
.uld-manual-duplicate-grid {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 6px 12px;
  font-size: 12px;
}
.uld-manual-duplicate-grid span {
