}
.uld-manual-modal-saving .uld-manual-dialog {
  animation: uldManualSavePulse .46s cubic-bezier(.22,1,.36,1) both;
}
.uld-manual-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 16px;
}
.uld-manual-cancel,
.uld-manual-save {
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 8px;
  padding: 9px 13px;
  font-weight: 900;
  cursor: pointer;
  transition: background .16s ease, transform .14s ease, border-color .16s ease;
}
.uld-manual-cancel {
  background: rgba(255,255,255,.05);
  color: #cbd5e1;
}
.uld-manual-save {
  background:
    linear-gradient(135deg, rgba(99,102,241,.42), rgba(14,165,233,.26)),
    rgba(99,102,241,.18);
