    linear-gradient(135deg, rgba(99,102,241,.54), rgba(14,165,233,.34)),
    rgba(99,102,241,.24);
  border-color: rgba(165,180,252,.62);
  box-shadow: 0 14px 34px rgba(99,102,241,.26), inset 0 1px 0 rgba(255,255,255,.16);
}










@keyframes uldManualIn {
  from { opacity: 0; transform: translateY(12px) scale(.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes uldManualFadeOut {
  from { opacity: 1; }
  to { opacity: 0; }
}
@keyframes uldDuplicateIn {
  from { opacity: 0; transform: translateY(8px) scale(.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes uldManualBackdropLift {
  from { opacity: 1; backdrop-filter: blur(22px) saturate(170%) contrast(1.04); }
  to { opacity: .18; backdrop-filter: blur(10px) saturate(120%) contrast(1); }
}
@keyframes uldManualDialogCollapse {
  from { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
  to { opacity: 0; transform: translateY(-8px) scale(.965); filter: blur(5px); }
}
@keyframes uldManualSavePulse {
  0% { transform: translateY(0) scale(1); }
  44% { transform: translateY(-2px) scale(1.008); box-shadow: 0 34px 92px rgba(0,0,0,.52), 0 0 0 2px rgba(129,140,248,.34) inset, 0 0 42px rgba(99,102,241,.24); }
  100% { transform: translateY(0) scale(1); }
}
.uld-manual-flyer {
  position: fixed;
  z-index: 10005;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  border-radius: 16px;
  border: 1px solid rgba(225,242,255,.30);
  background:
    radial-gradient(92% 72% at 18% 4%, rgba(255,255,255,.32), transparent 48%),
    radial-gradient(80% 80% at 110% 0%, rgba(99,102,241,.24), transparent 54%),
    linear-gradient(135deg, rgba(255,255,255,.16), rgba(255,255,255,.055)),
    rgba(13,18,32,.74);
  backdrop-filter: blur(24px) saturate(185%);
  -webkit-backdrop-filter: blur(24px) saturate(185%);
  color: #fff;
  font-family: monospace;
  font-size: 12px;
  font-weight: 900;
  box-shadow:
    0 26px 70px rgba(0,0,0,.42),
    0 10px 26px rgba(99,102,241,.24),
    inset 1px 1px 0 rgba(255,255,255,.30),
    inset -1px -1px 0 rgba(255,255,255,.07);
  pointer-events: none;
  transform: translateZ(0) scale(1);
  transition:
    left .72s cubic-bezier(.18,.86,.24,1),
    top .72s cubic-bezier(.18,.86,.24,1),
    width .72s cubic-bezier(.18,.86,.24,1),
    height .72s cubic-bezier(.18,.86,.24,1),
    border-radius .72s cubic-bezier(.18,.86,.24,1),
    opacity .26s ease,
    transform .72s cubic-bezier(.18,.86,.24,1);
}
.uld-manual-flyer::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(108deg, transparent 16%, rgba(255,255,255,.38) 42%, rgba(255,255,255,.06) 56%, transparent 76%),
    radial-gradient(1px 1px at 24% 26%, rgba(255,255,255,.42), transparent),
    radial-gradient(1px 1px at 78% 36%, rgba(255,255,255,.24), transparent);
  opacity: .74;
  pointer-events: none;
}
.uld-manual-morph-kicker,
.uld-manual-morph-meta {
  position: relative;
  z-index: 1;
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 11px;
  font-weight: 850;
  color: rgba(219,234,254,.86);
  transition: opacity .22s ease, transform .38s ease;
}
.uld-manual-morph-uld {
  position: relative;
  z-index: 1;
  font-size: 18px;
  letter-spacing: 0;
  transition: font-size .54s cubic-bezier(.18,.86,.24,1), transform .54s cubic-bezier(.18,.86,.24,1);
}
.uld-manual-morph-flight {
  border-radius: 10px;
  transform: translateZ(0) scale(.98);
}
.uld-manual-morph-flight .uld-manual-morph-kicker,
.uld-manual-morph-flight .uld-manual-morph-meta {
  opacity: 0;
  transform: translateY(-4px);
}
.uld-manual-morph-flight .uld-manual-morph-uld {
  font-size: 12px;
  transform: translateY(0);
}
.uld-manual-morph-landed {
  opacity: 0;
  transform: translateZ(0) scale(.72);
}
.uld-manual-target-pulse {
  animation: uldManualTargetPulse .82s cubic-bezier(.22,1,.36,1);
}
@keyframes uldManualTargetPulse {
  0% { box-shadow: var(--stack-shadow, 0 0 0 rgba(0,0,0,0)); }
  36% { box-shadow: 0 0 0 1px rgba(125,211,252,.48), 0 0 34px rgba(14,165,233,.24); }
  100% { box-shadow: var(--stack-shadow, 0 0 0 rgba(0,0,0,0)); }
}
@media (max-width: 680px) {
  .uld-manual-grid { grid-template-columns: 1fr; }
  .uld-manual-time-wrap,
  .uld-manual-datetime { max-width: none; }
  .uld-search-underbar { align-items: stretch; }
  .uld-manual-dialog { width: min(100%, 96vw); padding: 16px; }
}
@media (prefers-reduced-motion: reduce) {
  .uld-manual-modal,
  .uld-manual-dialog,
  .uld-manual-flyer,
  .uld-manual-target-pulse {
    animation: none !important;
    transition-duration: .001ms !important;
  }
}

/* ULD toast notification */
.uld-toast {
  position: fixed;
  bottom: 28px;
  right: 28px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
}
.uld-toast-item {
  padding: 10px 18px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  background: rgba(30,34,52,.92);
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: 0 8px 28px rgba(0,0,0,.32);
  backdrop-filter: blur(12px);
  animation: toastIn .25s ease forwards;
  pointer-events: none;
  white-space: nowrap;
}
.uld-toast-item.uld-toast-ok     { border-color: #22c55e44; }
.uld-toast-item.uld-toast-error  { border-color: #ef444444; color: #fca5a5; }
.uld-toast-item.uld-toast-info   { border-color: #6366f144; }
.uld-toast-item.uld-toast-fade   { animation: toastOut .3s ease forwards; }
@keyframes toastIn  { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { from { opacity: 1; transform: none; } to { opacity: 0; transform: translateY(8px); } }


