/* ════════════════════════════════════════════════════════════════════ */
/* LIQUID GLASS — performance-optimized: minimal blur, static gradients */
/* No backdrop-filter on body panels (was causing brightness shifts as  */
/* the bg orbs animated behind them). Only the header keeps a light blur.*/
/* ════════════════════════════════════════════════════════════════════ */

.glass-panel {
  position: relative;
  isolation: isolate;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 20px;
  background:
    radial-gradient(80% 60% at 0% 0%, rgba(255,255,255,0.05), transparent 55%),
    radial-gradient(60% 50% at 100% 100%, rgba(99,102,241,0.06), transparent 60%),
    linear-gradient(135deg, rgba(255,255,255,0.04), rgba(255,255,255,0.01)),
    rgba(20,24,38,0.55);
  box-shadow:
    0 10px 30px rgba(0,0,0,0.30),
    0 0 0 1px rgba(255,255,255,0.04) inset,
    0 1px 0 rgba(255,255,255,0.08) inset;
  contain: layout paint style;
  transition: border-color 0.30s ease, box-shadow 0.30s ease;
}
/* Static highlight stripe — fixed, no animation, no SVG filter */
.glass-panel::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.07) 0%, transparent 18%);
  pointer-events: none;
  z-index: 0;
}
.glass-panel > * { position: relative; z-index: 1; }



/* Glow hierarchy: header > panels > cards (kept subtle, no inner-glow blooms) */
.uld-header.glass-panel {
  box-shadow:
    0 12px 36px rgba(0,0,0,0.32),
    0 0 0 1px rgba(255,255,255,0.06) inset,
    0 1px 0 rgba(255,255,255,0.10) inset;
}
.uld-stacks-panel.glass-panel,
.uld-list-panel.glass-panel {
  padding: 14px 14px 16px;
}
.uld-stacks-panel.glass-panel:hover,
.uld-list-panel.glass-panel:hover {
  box-shadow:
    0 12px 36px rgba(0,0,0,0.32),
    0 0 0 1px rgba(99,102,241,0.10) inset,
    0 1px 0 rgba(255,255,255,0.10) inset;
  border-color: rgba(99,102,241,0.18);
}

/* ════════════════════════════════════════════════════════════════════ */
/* ENTRANCE & TRANSITION ANIMATIONS                                     */
/* ════════════════════════════════════════════════════════════════════ */

/* The uld-area itself fades & slides up when flow-mode = uld */
body.flow-uld-mode .uld-area {
  animation: uldAreaIn 0.45s cubic-bezier(0.22,1,0.36,1) both;
}
@keyframes uldAreaIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: none; }
}

/* Header slides down */
body.flow-uld-mode .uld-header {
  animation: uldHeaderIn 0.5s cubic-bezier(0.22,1,0.36,1) both;
}
@keyframes uldHeaderIn {
  from { opacity: 0; transform: translateY(-12px); }
  to   { opacity: 1; transform: none; }
}

/* Stacks panel slides in from left */
body.flow-uld-mode .uld-stacks-panel {
  animation: uldSlideLeft 0.55s cubic-bezier(0.22,1,0.36,1) 0.08s both;
}
@keyframes uldSlideLeft {
  from { opacity: 0; transform: translateX(-24px) scale(.985); }
  to   { opacity: 1; transform: none; }
}

/* List panel slides in from right */
body.flow-uld-mode .uld-list-panel {
  animation: uldSlideRight 0.55s cubic-bezier(0.22,1,0.36,1) 0.14s both;
}
@keyframes uldSlideRight {
  from { opacity: 0; transform: translateX(24px) scale(.985); }
  to   { opacity: 1; transform: none; }
}

/* Stack cards stagger in — ONLY on tab switch (flow-switching) — cheap opacity */
body.flow-switching.flow-uld-mode .uld-stack {
  animation: uldCardIn 0.40s cubic-bezier(0.22,1,0.36,1) both;
}
body.flow-switching.flow-uld-mode .uld-stack:nth-child(1) { animation-delay: 0.14s; }
body.flow-switching.flow-uld-mode .uld-stack:nth-child(2) { animation-delay: 0.18s; }
body.flow-switching.flow-uld-mode .uld-stack:nth-child(3) { animation-delay: 0.22s; }
body.flow-switching.flow-uld-mode .uld-stack:nth-child(4) { animation-delay: 0.26s; }
body.flow-switching.flow-uld-mode .uld-stack:nth-child(n+5) { animation-delay: 0.30s; }
@keyframes uldCardIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: none; }
}

/* ULD rows stagger in — only on tab switch (cheap opacity) */
body.flow-switching.flow-uld-mode .uld-row {
  animation: uldRowIn 0.38s cubic-bezier(0.22,1,0.36,1) both;
}
body.flow-switching.flow-uld-mode .uld-row:nth-child(1) { animation-delay: 0.16s; }
body.flow-switching.flow-uld-mode .uld-row:nth-child(2) { animation-delay: 0.18s; }
body.flow-switching.flow-uld-mode .uld-row:nth-child(3) { animation-delay: 0.20s; }
body.flow-switching.flow-uld-mode .uld-row:nth-child(4) { animation-delay: 0.22s; }
body.flow-switching.flow-uld-mode .uld-row:nth-child(5) { animation-delay: 0.24s; }
body.flow-switching.flow-uld-mode .uld-row:nth-child(6) { animation-delay: 0.26s; }
body.flow-switching.flow-uld-mode .uld-row:nth-child(7) { animation-delay: 0.28s; }
body.flow-switching.flow-uld-mode .uld-row:nth-child(8) { animation-delay: 0.30s; }
body.flow-switching.flow-uld-mode .uld-row:nth-child(n+9) { animation-delay: 0.32s; }
@keyframes uldRowIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: none; }
}

/* Filter chips fade in on entrance */
body.flow-uld-mode .uld-filter-chips {
  animation: uldChipsIn 0.42s cubic-bezier(0.22,1,0.36,1) 0.12s both;
}
@keyframes uldChipsIn {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: none; }
}

/* ════════════════════════════════════════════════════════════════════ */
/* FILTER CHANGE — items have a one-shot entrance via CSS transition.  */
/* No looped animations on mount → no brightness flicker, no FPS hit.  */
/* The chip click triggers Dash render; React mounts new rows; their   */
/* transition on opacity+transform from initial → default = smooth.    */
/* ════════════════════════════════════════════════════════════════════ */

.uld-list .uld-row {
  transition: border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
}

/* In-stack badge: simple transition, no animation that could leave it invisible */
.uld-in-stack-badge { transition: opacity 0.2s ease, transform 0.2s ease; }

/* Reduced motion: disable all entrance animations */
@media (prefers-reduced-motion: reduce) {
  body.flow-uld-mode .uld-area,
  body.flow-uld-mode .uld-header,
  body.flow-uld-mode .uld-stacks-panel,
  body.flow-uld-mode .uld-list-panel,
  body.flow-uld-mode .uld-filter-chips,
  body.flow-switching.flow-uld-mode .uld-stack,
  body.flow-switching.flow-uld-mode .uld-row,
  .uld-si,
  .uld-in-stack-badge,
  .glass-panel::after {
    animation: none !important;
  }
}

/* Final ULD performance overrides must stay after the ULD animation block. */
body.flow-uld-mode .bg-orbs,
body.flow-uld-mode .scroll-fade {
  display: none !important;
}
body.flow-uld-mode .uld-area,
body.flow-uld-mode .uld-header,
body.flow-uld-mode .uld-stacks-panel,
body.flow-uld-mode .uld-list-panel,
body.flow-uld-mode .uld-filter-chips,
body.flow-switching.flow-uld-mode .uld-stack,
body.flow-switching.flow-uld-mode .uld-row {
  animation: none !important;
}
body.flow-uld-mode .uld-row,
body.flow-uld-mode .uld-stack,
body.flow-uld-mode .uld-si,
body.flow-uld-mode .uld-chip {
  will-change: auto !important;
}
body.flow-uld-mode .uld-row,
body.flow-uld-mode .uld-stack,
body.flow-uld-mode .uld-list .uld-row {
  transition: border-color .12s ease, background .12s ease, opacity .12s ease !important;
}
body.flow-uld-mode .uld-row:hover,
body.flow-uld-mode .uld-stack:hover {
  transform: none !important;
  box-shadow: none !important;
}
body.flow-uld-mode .uld-cd-critical .uld-cd-time,
body.flow-uld-mode .uld-cd-expired .uld-cd-time {
  animation: none !important;
}
/* Light-mode ULD contrast hardening. Keep this after the final performance overrides. */





























body.flow-uld-mode .uld-optimistic {
  animation: uldOptimisticIn .18s cubic-bezier(.22,1,.36,1) both !important;
}
@keyframes uldOptimisticIn {
  from { opacity: 0; transform: translateY(6px) scale(.985); }
  to   { opacity: 1; transform: none; }
}
body.flow-uld-mode .uld-stack-print:hover,
body.flow-uld-mode .uld-stack-copy:hover,
body.flow-uld-mode .uld-new-stack-btn:hover,
body.flow-uld-mode .uld-reset-btn:hover,
body.flow-uld-mode .uld-chip:hover {
  transform: none !important;
}

