@keyframes uldChipIn {
  0%   { opacity: 0; transform: translateY(10px) scale(.92); }
  60%  { opacity: 1; transform: translateY(-2px) scale(1.02); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes uldChipFly {
  0%   { transform: translateY(0) scale(1); opacity: 1; }
  60%  { transform: translateY(-30px) scale(1.04); opacity: .8; }
  100% { transform: translateY(-200px) scale(.4); opacity: 0; }
}
@keyframes uldSelectionFlash {
  0%, 100% { box-shadow: 0 20px 60px rgba(0,0,0,.45), 0 0 0 1px rgba(99,102,241,.18) inset; }
  50%      { box-shadow: 0 20px 60px rgba(0,0,0,.45), 0 0 0 2px rgba(99,102,241,.85) inset, 0 0 50px rgba(99,102,241,.36); }
}
.uld-selection-bar.uld-selection-flash {
  animation: uldSelectionFlash .55s ease;
}
@media (prefers-reduced-motion: reduce) {
  .uld-target-chip { animation: none; opacity: 1; transform: none; }
  .uld-selection-bar { transition: opacity .2s ease; }
}
.uld-main {
  display: grid;
  grid-template-columns: minmax(360px, .95fr) minmax(420px, 1.35fr);
  gap: 14px;
  align-items: start;
  /* The column reflow snaps (no grid-template-columns tween): interpolating it
     would relayout the whole stack list every frame and stutter with 25-item
     stacks. The snap is masked by the per-card GPU reveal + panel settle below,
     which are composited (opacity/transform) and stay smooth. */
}

/* ── Stack focus mode ────────────────────────────────────────────────────
   Toggled by "Mind kinyit": the stack-building panel takes most of the width
   so opened 15–18 item stacks get a wide inspection surface, while the ULD
   list compresses to a narrow single column. */
body.uld-stacks-focus .uld-main {
  grid-template-columns: minmax(520px, 1.95fr) minmax(232px, .62fr);
}
body.uld-stacks-focus-transitioning .uld-stacks-panel,
body.uld-stacks-focus-transitioning .uld-list-panel,
body.uld-stacks-focus-transitioning .uld-stack {
  backface-visibility: hidden;
  transform-style: flat;
  will-change: transform, opacity;
}
body.uld-stacks-focus-transitioning .uld-stacks-panel,
body.uld-stacks-focus-transitioning .uld-list-panel {
  z-index: 2;
}
/* Items inside an opened stack flow into multiple columns in focus mode, so a
   tall stack needs little or no internal scroll. */
body.uld-stacks-focus .uld-stack-expanded .uld-stack-col {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(168px, 1fr));
  gap: 6px;
  align-content: start;
}
/* Narrow list → single column of cards. */
body.uld-stacks-focus .uld-list {
  grid-template-columns: 1fr;
}
/* Gentle settle animation on the panels when focus toggles. */
body.uld-stacks-focus .uld-stacks-panel,
body.uld-stacks-focus .uld-list-panel {
  animation: uldFocusSettle .42s cubic-bezier(.22,1,.36,1);
}
@keyframes uldFocusSettle {
  0%   { transform: scale(.992); }
  100% { transform: scale(1); }
}
@media (prefers-reduced-motion: reduce) {
  body.uld-stacks-focus .uld-stacks-panel,
  body.uld-stacks-focus .uld-list-panel { animation: none; }
}
