/* ============================================================
   ULD liquid glass hierarchy
   ------------------------------------------------------------
   L1: ULD header, stack/list panels, floating selection bar.
   L2: stack cards and active rows.
   L3: chips/buttons/badges stay light for scan speed.
   ============================================================ */

.pcard-en-route {
  --glow: rgba(226,232,240,0.58);
  --glow-far: rgba(226,232,240,0.24);
  --glow-ultra: rgba(226,232,240,0.10);
  --glow-tint: rgba(226,232,240,0.18);
}

.badge-en-route {
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: #7dd3fc;
  background: rgba(56,189,248,0.13);
  border: 1px solid rgba(56,189,248,0.32);
  box-shadow: 0 0 16px rgba(56,189,248,0.15);
}

/* Aged urgency flag — 4+ órája felvéve. Icon-only clock (no emoji, no text), so
   it never changes the header row height. Amber, gently breathing glow. */
/* 4+h-waiting indicator: a small RED pill (clock icon + hour count). Compact so it
   never grows the card-strip height; red = "waited too long, bumped up". */
.badge-aged {
  flex-shrink: 0;
  display: inline-flex; align-items: center; gap: 3px;
  height: 17px; padding: 0 6px 0 5px;
  border-radius: 999px;
  background: linear-gradient(180deg, #ef4444, #dc2626);
  border: 1px solid rgba(255,128,128,0.5);
  color: #fff; font-size: 10px; font-weight: 900; line-height: 1; letter-spacing: 0.01em;
  box-shadow: 0 1px 5px rgba(220,38,38,0.42), inset 0 1px 0 rgba(255,255,255,0.22);
}
.badge-aged::before {
  content: ""; flex-shrink: 0; width: 11px; height: 11px;
  background-color: currentColor;
  -webkit-mask: var(--icon-clock) center / contain no-repeat;
  mask: var(--icon-clock) center / contain no-repeat;
}
/* Red edge accent so the bumped-up card is recognisable at a glance. */
.priority-card.is-aged-card { border-color: rgba(239,68,68,0.5); }


.since-en-route {
  color: #7dd3fc !important;
}

/* ── INBOUND "Összegzés" — TOP 10 priority modal ─────────────────────────── */
.summary-btn {
  border: 1px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.06);
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: 10px;
  font-size: 12.5px;
