/* light-mode ULD note colours also come from the inline _uld_note_style() */

body.flow-uld-mode .uld-header,
body.flow-uld-mode .uld-stacks-panel,
body.flow-uld-mode .uld-list-panel,
body.flow-uld-mode .uld-selection-bar {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background:
    radial-gradient(130% 90% at 7% -18%, rgba(255,255,255,0.13), transparent 45%),
    radial-gradient(90% 80% at 108% 0%, rgba(99,102,241,0.11), transparent 50%),
    linear-gradient(145deg, rgba(255,255,255,0.095), rgba(255,255,255,0.030)),
    rgba(13,18,32,0.54) !important;
  border: 1px solid rgba(210,230,255,0.15) !important;
  backdrop-filter: blur(26px) saturate(180%) brightness(1.06);
  -webkit-backdrop-filter: blur(26px) saturate(180%) brightness(1.06);
  box-shadow:
    0 18px 50px rgba(0,0,0,0.30),
    inset 1px 1px 0 rgba(255,255,255,0.22),
    inset -1px -1px 0 rgba(255,255,255,0.06);
}

/* The surface block above forces position:relative + overflow:hidden on EVERY
   surface. For the left stack-building panel that breaks two things: it can no
   longer stick under the header while scrolling, and its own content gets
   clipped instead of scrolling. Restore both here (must win → !important). */
body.flow-uld-mode .uld-stacks-panel.glass-panel {
  position: sticky !important;
  top: var(--uld-sticky-top, 96px) !important;
  align-self: start;
  max-height: calc(100vh - var(--uld-sticky-top, 96px) - 16px) !important;
  /* Panel stays fixed-frame so the glass rim never scrolls; the inner
     .uld-stacks-grid is the scroller instead. */
  overflow: hidden !important;
}
/* Inner grid is the scroller. It must NOT flex-grow (that fights the stable
   max-height inside a content-sized sticky panel and breaks scrolling); it sizes
   to content and scrolls once it hits the cap. */
body.flow-uld-mode .uld-stacks-panel.glass-panel .uld-stacks-grid {
  flex: 0 1 auto;
  min-height: 0;
  max-height: calc(100vh - var(--uld-sticky-top, 96px) - 16px - 52px);
  overflow-y: auto;
  overflow-x: hidden;
}

body.flow-uld-mode .uld-header::before,
body.flow-uld-mode .uld-stacks-panel::before,
body.flow-uld-mode .uld-list-panel::before,
body.flow-uld-mode .uld-selection-bar::before {
  content: '';
  position: absolute;
  inset: 1px;
  border-radius: inherit;
  pointer-events: none;
  z-index: 0;
  /* Single diagonal sheen only. The top-left radial glow lives on the surface
     background (see the .uld-* surface block) — duplicating it here produced the
     doubled top-left highlight, so it is intentionally NOT repeated. */
  background:
    linear-gradient(125deg, rgba(255,255,255,0.10), rgba(255,255,255,0.03) 20%, transparent 50%);
}

body.flow-uld-mode .uld-header::after,
body.flow-uld-mode .uld-stacks-panel::after,
body.flow-uld-mode .uld-list-panel::after,
body.flow-uld-mode .uld-selection-bar::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 9px;
  pointer-events: none;
  z-index: 1;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
  background: conic-gradient(from 135deg,
    rgba(125,211,252,0.00),
    rgba(125,211,252,0.13),
    rgba(167,139,250,0.10),
    rgba(45,212,191,0.11),
    rgba(125,211,252,0.00));
  /* No backdrop-filter here: a second backdrop-filter (the surface already has
     one) repainted on every scroll/poll frame and caused the visible flicker.
     The masked conic rim is fully static, so it is stable. */
  opacity: .35;
}

body.flow-uld-mode .uld-header > *,
body.flow-uld-mode .uld-stacks-panel > *,
body.flow-uld-mode .uld-list-panel > *,
body.flow-uld-mode .uld-selection-bar > * {
  position: relative;
  z-index: 2;
}

body.flow-uld-mode .uld-stack,
body.flow-uld-mode .uld-row {
  transform-style: preserve-3d;
  background:
    radial-gradient(110% 90% at 6% -12%, rgba(255,255,255,0.095), transparent 45%),
    linear-gradient(145deg, rgba(255,255,255,0.075), rgba(255,255,255,0.028)),
    rgba(15,23,42,0.46);
  border-color: rgba(210,230,255,0.12);
  box-shadow:
