    inset 1px 1px 0 rgba(255,255,255,0.13),
    inset -1px -1px 0 rgba(255,255,255,0.045);
  transition:
    transform .22s cubic-bezier(.22,1,.36,1),
    box-shadow .22s ease,
    border-color .18s ease,
    background .18s ease,
    opacity .12s ease;
}

body.flow-uld-mode .uld-stack:hover,
body.flow-uld-mode .uld-row:hover {
