/* Final stack accordion stability overrides.
   The stack panel is one fixed-frame scroller, while each large opened stack
   gets its own body scroller. This prevents open stack bodies from painting
   over following stack headers and removes hover-driven layout jitter. */
body.flow-uld-mode .uld-stacks-panel.glass-panel {
  display: flex !important;
  flex-direction: column !important;
  overflow: hidden !important;
}
body.flow-uld-mode .uld-stacks-panel.glass-panel .uld-stacks-grid {
  flex: 1 1 auto !important;
  min-height: 0 !important;
  max-height: calc(100vh - var(--uld-sticky-top, 96px) - 16px - 52px) !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  overscroll-behavior: contain;
  padding-bottom: 10px;
}
body.flow-uld-mode .uld-stack {
  flex: 0 0 auto !important;
  contain: layout style !important;
  transform-style: flat !important;
  overflow: hidden !important;
  will-change: auto !important;
}
body.flow-uld-mode .uld-stack:hover,
body.flow-uld-mode .uld-stack-accordion:hover {
  transform: none !important;
}
body.flow-uld-mode .uld-stack-body {
  min-height: 0 !important;
  overscroll-behavior: contain;
}
body.flow-uld-mode .uld-stack-collapsible.uld-stack-expanded .uld-stack-body {
  overflow-y: auto !important;
  overflow-x: hidden !important;
}
body.flow-uld-mode .uld-stack-col {
