body.flow-uld-mode.uld-stacks-focus-transitioning .uld-stacks-panel,
body.flow-uld-mode.uld-stacks-focus-transitioning .uld-list-panel,
body.flow-uld-mode.uld-stacks-focus-transitioning .uld-stack {
