/* --- Unified action badges (Kijelöl / Összekészít / Kiküld / print / copy / ×) --- */
body.flow-uld-mode .uld-stack-act {
  height: 25px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 10px;
  border-radius: 8px;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .3px;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  flex-shrink: 0;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(255,255,255,.05);
  color: var(--text-muted);
  transition: background .2s ease, border-color .2s ease, color .2s ease,
              transform .18s cubic-bezier(.34,1.45,.6,1), box-shadow .22s ease, filter .18s ease;
}
body.flow-uld-mode .uld-stack-act:hover {
  transform: translateY(-1px);
  color: var(--text);
  background: rgba(255,255,255,.1);
  border-color: rgba(255,255,255,.22);
}
body.flow-uld-mode .uld-stack-act:active { transform: scale(.92); }
body.flow-uld-mode .uld-stack-act:disabled,
body.flow-uld-mode .uld-stack-act.uld-stack-prep-disabled,
body.flow-uld-mode .uld-stack-act.uld-stack-dispatch-disabled {
  opacity: .4 !important;
  cursor: not-allowed !important;
  transform: none !important;
  box-shadow: none !important;
  filter: none !important;
}
/* Kijelöl — neutral/indigo */
body.flow-uld-mode .uld-stack-act.uld-stack-select:hover {
  color: #c7d2fe; border-color: rgba(99,102,241,.5); background: rgba(99,102,241,.16);
}
body.flow-uld-mode .uld-stack.uld-stack-selected .uld-stack-act.uld-stack-select {
  color: #fff; border-color: rgba(99,102,241,.7);
  background: linear-gradient(135deg, rgba(99,102,241,.5), rgba(79,70,229,.4));
  box-shadow: 0 0 0 1px rgba(99,102,241,.3) inset;
}
/* Összekészít — green */
body.flow-uld-mode .uld-stack-act.uld-stack-prep-btn.uld-stack-prep-empty {
  color: #86efac; border-color: rgba(34,197,94,.36); background: rgba(34,197,94,.08);
}
body.flow-uld-mode .uld-stack-act.uld-stack-prep-btn.uld-stack-prep-empty:hover {
  color: #fff; border-color: rgba(34,197,94,.7); background: rgba(34,197,94,.2);
  box-shadow: 0 6px 16px -6px rgba(34,197,94,.6);
}
body.flow-uld-mode .uld-stack-act.uld-stack-prep-btn.uld-stack-prep-active {
  color: #fff; border-color: rgba(34,197,94,.7);
  background: linear-gradient(135deg, rgba(34,197,94,.34), rgba(16,185,129,.24));
  box-shadow: 0 0 0 1px rgba(34,197,94,.3) inset;
}
/* Kiküld — cyan */
body.flow-uld-mode .uld-stack-act.uld-stack-dispatch-btn {
  color: #fecaca; border-color: rgba(248,113,113,.44);
  background: linear-gradient(135deg, rgba(239,68,68,.18), rgba(244,63,94,.12));
}
body.flow-uld-mode .uld-stack-act.uld-stack-dispatch-btn:hover {
  color: #fff; border-color: rgba(248,113,113,.86);
  background: linear-gradient(135deg, rgba(239,68,68,.34), rgba(244,63,94,.24));
  box-shadow: 0 7px 18px -7px rgba(239,68,68,.75);
}
/* icon-only square variant (print / copy / ×) */
body.flow-uld-mode .uld-stack-act.uld-stack-ico { width: 25px; padding: 0; }
body.flow-uld-mode .uld-stack-act.uld-stack-ico::before {
  content: '';
  width: 14px; height: 14px;
  background-color: currentColor;
  -webkit-mask: var(--ico) center / 14px 14px no-repeat;
          mask: var(--ico) center / 14px 14px no-repeat;
}
body.flow-uld-mode .uld-stack-print {
  --ico: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='black'%20stroke-width='2'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d='M6%209V3h12v6'/%3E%3Crect%20x='3'%20y='9'%20width='18'%20height='8'%20rx='2'/%3E%3Cpath%20d='M7%2017h10v4H7z'/%3E%3C/svg%3E");
}
body.flow-uld-mode .uld-stack-copy {
  --ico: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='black'%20stroke-width='2'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Crect%20x='9'%20y='9'%20width='12'%20height='12'%20rx='2'/%3E%3Cpath%20d='M5%2015H4a2%202%200%200%201-2-2V4a2%202%200%200%201%202-2h9a2%202%200%200%201%202%202v1'/%3E%3C/svg%3E");
}
body.flow-uld-mode .uld-stack-print:hover { color: #a5b4fc; border-color: rgba(99,102,241,.5); background: rgba(99,102,241,.14); }
body.flow-uld-mode .uld-stack-copy:hover  { color: #86efac; border-color: rgba(34,197,94,.5); background: rgba(34,197,94,.14); }
/* × close */
body.flow-uld-mode .uld-stack-act.uld-stack-del::before {
  content: '✕';
  width: auto; height: auto;
  -webkit-mask: none; mask: none;
  background: none;
  font-size: 12px; font-weight: 900; line-height: 1;
}
body.flow-uld-mode .uld-stack-act.uld-stack-del:hover {
  color: #fca5a5; border-color: rgba(239,68,68,.5); background: rgba(239,68,68,.15);
}
body.flow-uld-mode .uld-stack-act.uld-stack-copy.uld-copy-done {
  color: #fff; border-color: rgba(34,197,94,.7);
  background: linear-gradient(135deg, rgba(34,197,94,.4), rgba(16,185,129,.3));
  animation: uldActPop .4s cubic-bezier(.22,1,.36,1);
}
@keyframes uldActPop { 0%{transform:scale(.8);} 55%{transform:scale(1.12);} 100%{transform:scale(1);} }

/* =====================================================================
   Dispatched sub-view — strip the heavy active-view chrome, full-width list
   ===================================================================== */
body.uld-view-dispatched .uld-stacks-tools,
body.uld-view-dispatched .uld-selection-bar,
body.uld-view-dispatched .uld-filter-chips,
body.uld-view-dispatched .uld-select-all-btn,
body.uld-view-dispatched .uld-manual-open-btn,
body.uld-view-dispatched .uld-list-panel,
body.uld-view-dispatched .uld-loading-bar-wrap,
body.uld-view-dispatched .uld-loading-hint,
body.uld-view-dispatched .uld-stacks-hdr { display: none !important; }

body.uld-view-dispatched .uld-search-underbar {
  display: flex !important;
  justify-content: flex-end;
}

body.flow-uld-mode.uld-view-dispatched .uld-main { display: block !important; }
body.flow-uld-mode.uld-view-dispatched .uld-stacks-panel.glass-panel {
  position: static !important;
  top: auto !important;
  max-height: none !important;
  width: 100% !important;
  overflow: visible !important;
  animation: uldViewRowIn .4s cubic-bezier(.22,1,.36,1) both;
}
body.flow-uld-mode.uld-view-dispatched .uld-stacks-panel.glass-panel .uld-stacks-grid {
  max-height: none !important;
  overflow: visible !important;
  flex: 0 1 auto !important;
  padding-bottom: 0;
}

/* Minimal dispatched list */
.uld-dlist { display: flex; flex-direction: column; gap: 2px; }
.uld-dlist-top {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px; padding: 2px 6px 10px; flex-wrap: wrap;
}
.uld-dlist-top-info { display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.uld-dlist-tools { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.uld-dlist-selcount {
  font-size: 11px; font-weight: 800; color: var(--text-muted);
  padding: 3px 10px; border-radius: 999px;
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.08);
  transition: color .16s ease, background .16s ease, border-color .16s ease;
}
.uld-dlist-selcount-active {
  color: #c7d2fe; background: rgba(99,102,241,.16); border-color: rgba(129,140,248,.4);
}
.uld-dlist-bulk-btn {
  height: 30px; padding: 0 13px; border-radius: 999px;
  font-size: 11.5px; font-weight: 800; letter-spacing: .2px;
  cursor: pointer; white-space: nowrap;
  color: var(--text); background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.12);
  transition: background .16s ease, border-color .16s ease, color .16s ease,
              transform .16s cubic-bezier(.34,1.45,.6,1), box-shadow .2s ease;
}
.uld-dlist-bulk-btn:hover {
  background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.22);
  transform: translateY(-1px);
}
.uld-dlist-bulk-btn:active { transform: scale(.96); }
.uld-dlist-bulk-btn:disabled {
  opacity: .42; cursor: not-allowed; transform: none; box-shadow: none;
}
.uld-dlist-revert-selected:not(:disabled) {
  color: #fde68a; border-color: rgba(245,158,11,.42); background: rgba(245,158,11,.1);
}
.uld-dlist-revert-selected:not(:disabled):hover {
  color: #fff; border-color: rgba(245,158,11,.85);
  background: linear-gradient(135deg, rgba(245,158,11,.4), rgba(217,119,6,.32));
}
.uld-dlist-revert-all {
  color: #93c5fd; border-color: rgba(59,130,246,.4); background: rgba(59,130,246,.1);
}
.uld-dlist-revert-all:hover {
  color: #fff; border-color: rgba(59,130,246,.85);
  background: linear-gradient(135deg, rgba(59,130,246,.4), rgba(37,99,235,.32));
}
.uld-dlist-bulk-btn.uld-dlist-revert-armed {
  color: #fff; border-color: rgba(245,158,11,.95);
  background: linear-gradient(135deg, rgba(245,158,11,.5), rgba(217,119,6,.42));
  box-shadow: 0 0 0 3px rgba(245,158,11,.18);
}



.uld-dlist-title { font-size: 15px; font-weight: 900; color: var(--text); letter-spacing: .2px; }
.uld-dlist-sub { font-size: 11px; font-weight: 700; color: var(--text-muted); }
.uld-dlist-row, .uld-dlist-head {
  display: grid;
  grid-template-columns: minmax(140px,1.05fr) 72px minmax(260px,2fr) 176px minmax(104px,.8fr) 126px;
  gap: 10px;
  align-items: center;
}
.uld-dlist-head {
  padding: 8px 14px;
  font-size: 11px; font-weight: 800; letter-spacing: .5px; text-transform: uppercase;
  color: var(--text-muted);
  border-bottom: 1px solid rgba(255,255,255,.08);
  text-align: center;
}
/* Every column header sits centered above its centered value. */
.uld-dlist-head > span { text-align: center; justify-self: center; }
.uld-dlist-head .uld-dlist-h-name { justify-self: center; }
.uld-dlist-body { display: flex; flex-direction: column; }
.uld-dlist-row {
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.06);
  border-left: 3px solid var(--dc, #64748b);
  background: rgba(255,255,255,.03);
  margin-top: 8px;
  /* Clear visual separation between rows (cheap, static shadow — no animation cost). */
  box-shadow: 0 2px 8px rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.04);
  text-align: center;
  transition: background .16s ease, border-color .16s ease, transform .16s ease, box-shadow .18s ease;
  animation: uldDlistRowIn .3s cubic-bezier(.22,1,.36,1) both;
}
@keyframes uldDlistRowIn { from { opacity: 0; transform: translateX(-8px); } to { opacity: 1; transform: none; } }
.uld-dlist-row { cursor: pointer; }
.uld-dlist-row:hover {
  background: rgba(255,255,255,.06);
  border-color: rgba(255,255,255,.12);
  border-left-color: var(--dc, #64748b);
  box-shadow: 0 6px 18px rgba(0,0,0,.3), inset 0 1px 0 rgba(255,255,255,.06);
}
/* Selected for a bulk action — clear ring + tint, GHA accent kept on the left. */
.uld-dlist-row.uld-dlist-row-selected {
  background: rgba(99,102,241,.16);
  border-color: rgba(129,140,248,.5);
  box-shadow: 0 0 0 1px rgba(129,140,248,.45) inset, 0 6px 18px rgba(79,70,229,.18);
}
.uld-dlist-row.uld-dlist-row-selected:hover {
  background: rgba(99,102,241,.22);
}

.uld-dlist-name {
  font-size: 15px; font-weight: 850; color: var(--text);
  justify-self: center; text-align: center;
  max-width: 100%;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.uld-dlist-name-gha {
  justify-self: center;
  max-width: 100%;
  padding: 4px 10px;
  border-radius: 9px;
  color: var(--gha-color, #c7d2fe);
  background: var(--gha-bg, rgba(79,70,229,.14));
  border: 1px solid var(--gha-border, rgba(79,70,229,.42));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.07);
}
.uld-dlist-count { font-size: 16px; font-weight: 900; color: var(--text); justify-self: center; text-align: center; }
/* Name + optional search-match badge stacked, centered in the column. */
.uld-dlist-name-wrap {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  justify-self: center; min-width: 0; max-width: 100%;
}
.uld-dlist-match-badge {
  font-size: 10px; font-weight: 900; letter-spacing: .2px;
  padding: 1px 8px; border-radius: 999px; white-space: nowrap;
  color: #0f172a; background: #fde047; border: 1px solid #facc15;
  box-shadow: 0 1px 3px rgba(0,0,0,.25);
}
.uld-dlist-sub-match { color: #fde047 !important; font-weight: 900 !important; }
.uld-dlist-empty-sub { font-size: 11px; font-weight: 600; color: var(--text-muted); opacity: .85; }
/* A row that holds a searched ULD — subtle amber frame to find it instantly. */
.uld-dlist-row.uld-dlist-row-match {
  border-color: rgba(250,204,21,.5);
  box-shadow: 0 0 0 1px rgba(250,204,21,.3) inset, 0 4px 14px rgba(0,0,0,.22);
}
/* The matched ULD chip itself — bright amber, stands out in the bar. */
.uld-dlist-touch-item.uld-dlist-touch-item-match {
  color: #0f172a !important;
  background: linear-gradient(135deg, #fde047, #facc15) !important;
  border-color: #eab308 !important;
  box-shadow: 0 0 0 2px rgba(250,204,21,.35), 0 4px 12px rgba(202,138,4,.3) !important;
}
.uld-dlist-touch-item.uld-dlist-touch-item-match .uld-dlist-touch-uld { color: #0f172a !important; }
.uld-dlist-touch-item.uld-dlist-touch-item-match .uld-dlist-touch-pos {
  background: #0f172a !important; color: #fde047 !important; border-color: #0f172a !important;
}
.uld-dlist-touchbar {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 7px;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 5px 7px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.08);
  background: linear-gradient(135deg, rgba(255,255,255,.055), rgba(255,255,255,.025));
  scrollbar-width: thin;
  scrollbar-color: rgba(148,163,184,.45) transparent;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.07);
}
.uld-dlist-touchbar::before,
.uld-dlist-touchbar::after {
  content: '';
  position: sticky;
  top: 0;
  bottom: 0;
  z-index: 3;
  width: 34px;
  height: 30px;
  flex: 0 0 34px;
  opacity: 0;
  pointer-events: none;
  transition: opacity .18s ease;
}
.uld-dlist-touchbar::before {
  left: -7px;
  margin-right: -34px;
  background: linear-gradient(90deg, rgba(17,24,39,.92), rgba(17,24,39,0));
}
.uld-dlist-touchbar::after {
  right: -7px;
  margin-left: -34px;
  background: linear-gradient(270deg, rgba(17,24,39,.92), rgba(17,24,39,0));
}
.uld-dlist-touchbar.uld-touch-has-left::before,
.uld-dlist-touchbar.uld-touch-has-right::after {
  opacity: 1;
}
.uld-dlist-touchbar::-webkit-scrollbar { height: 6px; }
.uld-dlist-touchbar::-webkit-scrollbar-thumb {
  background: rgba(148,163,184,.38);
  border-radius: 999px;
}
.uld-dlist-touch-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  min-width: 118px;
  height: 30px;
  padding: 0 9px 0 6px;
  border-radius: 9px;
  color: var(--touch-color, #c7d2fe);
  background:
    linear-gradient(135deg, var(--touch-bg, rgba(99,102,241,.15)), rgba(255,255,255,.035)),
    linear-gradient(90deg, rgba(255,255,255,.06), transparent);
  border: 1px solid var(--touch-border, rgba(99,102,241,.32));
  cursor: pointer;
  transition: transform .16s ease, border-color .16s ease, box-shadow .18s ease, background .18s ease;
}
.uld-dlist-touch-item:hover {
  transform: translateY(-1px);
  border-color: var(--touch-color, #6366f1);
  box-shadow:
    0 8px 18px rgba(0,0,0,.20),
    0 0 0 1px color-mix(in srgb, var(--touch-color, #6366f1) 32%, transparent) inset;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--touch-color, #6366f1) 24%, transparent), rgba(255,255,255,.065)),
    linear-gradient(90deg, rgba(255,255,255,.10), transparent);
}
.uld-dlist-touch-pos {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 21px;
  height: 21px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 900;
  /* High, GHA-colour-independent contrast: solid dark disc + bright text. */
  color: #fff;
  background: #0f172a;
  border: 1.5px solid var(--touch-color, #6366f1);
  box-shadow: 0 1px 3px rgba(0,0,0,.4);
  text-shadow: 0 1px 2px rgba(0,0,0,.6);
}
.uld-dlist-touch-uld {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  font-weight: 900;
  color: var(--text);
  white-space: nowrap;
}
.uld-dlist-time { font-size: 13.5px; color: var(--text-muted); white-space: nowrap; justify-self: center; text-align: center; }
.uld-dlist-by {
  font-size: 13.5px; color: var(--text-muted);
  justify-self: center; text-align: center;
  max-width: 100%;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.uld-dlist-revert {
  justify-self: center;
  height: 28px; padding: 0 12px;
  border-radius: 8px;
  font-size: 11px; font-weight: 800; letter-spacing: .2px;
  cursor: pointer; white-space: nowrap;
  color: #93c5fd;
  border: 1px solid rgba(59,130,246,.4);
  background: rgba(59,130,246,.1);
  transition: background .18s ease, border-color .18s ease, color .18s ease,
              transform .16s cubic-bezier(.34,1.45,.6,1), box-shadow .2s ease;
}
.uld-dlist-revert:hover {
  color: #fff; border-color: rgba(59,130,246,.85);
  background: linear-gradient(135deg, rgba(59,130,246,.4), rgba(37,99,235,.34));
  transform: translateY(-1px);
  box-shadow: 0 6px 16px -6px rgba(59,130,246,.8);
}
.uld-dlist-revert:active { transform: scale(.94); }
.uld-dlist-revert.uld-dlist-revert-armed {
  color: #fff; border-color: rgba(245,158,11,.9);
  background: linear-gradient(135deg, rgba(245,158,11,.45), rgba(217,119,6,.4));
  animation: uldRevertArm 1s ease-in-out infinite;
}
@keyframes uldRevertArm {
  0%,100% { box-shadow: 0 0 0 0 rgba(245,158,11,.5); }
  50%     { box-shadow: 0 0 0 4px rgba(245,158,11,0); }
}
.uld-dlist-row.uld-dlist-row-reverting {
  animation: uldDlistRevertOut .36s cubic-bezier(.55,0,.67,.2) both;
  pointer-events: none;
}
@keyframes uldDlistRevertOut {
  0%   { opacity: 1; transform: translateX(0); }
  100% { opacity: 0; transform: translateX(40px); max-height: 0; padding-top: 0; padding-bottom: 0; margin: 0; }
}
.uld-dlist-empty {
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  padding: 48px 16px; color: var(--text-muted);
  border: 1px dashed rgba(255,255,255,.14); border-radius: 14px;
  background: rgba(255,255,255,.02);
  animation: uldViewRowIn .4s cubic-bezier(.22,1,.36,1) both;
}
.uld-dlist-empty-ico { font-size: 26px; opacity: .7; }
.uld-dlist-empty-txt { font-size: 12.5px; font-weight: 700; }









@media (max-width: 980px) {
  .uld-dlist-row, .uld-dlist-head {
    grid-template-columns: minmax(120px,1fr) 48px minmax(180px,1.5fr) 128px 92px;
  }
  .uld-dlist-row .uld-dlist-revert,
  .uld-dlist-head .uld-dlist-h-act {
    grid-column: 1 / -1;
    justify-self: end;
  }
}
@media (max-width: 720px) {
  .uld-dlist-row, .uld-dlist-head {
    grid-template-columns: minmax(120px,1fr) 48px;
  }
  .uld-dlist-touchbar,
  .uld-dlist-time,
  .uld-dlist-by,
  .uld-dlist-row .uld-dlist-revert,
  .uld-dlist-h-touch,
  .uld-dlist-h-time,
  .uld-dlist-h-by,
  .uld-dlist-head .uld-dlist-h-act {
    grid-column: 1 / -1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .uld-dlist-row, .uld-view-switch-row, .uld-dlist-empty { animation: none; }
  .uld-dlist-revert.uld-dlist-revert-armed { animation: none; }
}

/* Stability override: ULD active/dispatched view switches should not replay the
   center list/panel entrance animations during Dash refreshes. */
body.flow-uld-mode .uld-list.uld-page-in .uld-row,
body.flow-uld-mode.flow-switching .uld-header,
body.flow-uld-mode.flow-switching .uld-stacks-panel,
body.flow-uld-mode.flow-switching .uld-list-panel,
body.flow-uld-mode.flow-switching .uld-chip-row,
body.flow-uld-mode.flow-switching .uld-stack,
body.flow-uld-mode.flow-switching .uld-row {
  animation: none !important;
  animation-delay: 0s !important;
}

/* Dispatched view: only animate entrances during the brief view-switch window
   (body.uld-view-switching). In steady state a periodic data-version bump
   re-renders the grid/list; without this guard the empty state, the "nem
   jelennek meg" note and the rows REPLAY their entrance animation on every
   refresh — that is the row that "jumps up" in both panels. Freezing them in
   steady state makes the view stable. */
body.flow-uld-mode.uld-view-dispatched:not(.uld-view-switching) .uld-dlist-row,
body.flow-uld-mode.uld-view-dispatched:not(.uld-view-switching) .uld-dlist-empty,
body.flow-uld-mode.uld-view-dispatched:not(.uld-view-switching) .uld-dlist,
body.flow-uld-mode.uld-view-dispatched:not(.uld-view-switching) .uld-view-switch-row,
body.flow-uld-mode.uld-view-dispatched:not(.uld-view-switching) .uld-dispatched-list-note,
body.flow-uld-mode.uld-view-dispatched:not(.uld-view-switching) .uld-dispatched-empty-state {
  animation: none !important;
  animation-delay: 0s !important;
}

body.flow-uld-mode .uld-loading-bar,
body.flow-uld-mode .uld-loading-hint {
  animation: none !important;
}

body.flow-uld-mode .uld-list-panel::before,
body.flow-uld-mode .uld-list-panel::after,
body.flow-uld-mode.uld-view-dispatched .uld-stacks-panel::before,
body.flow-uld-mode.uld-view-dispatched .uld-stacks-panel::after {
  display: none !important;
}

