/* Inbound truck/ULD polish pass: plate grouping, focus mode, and theme tuning. */
.legend-bar {
  align-items: center;
  row-gap: 8px;
  max-height: 118px;
  overflow: visible;
}

.legend-group-label,
.legend-more-chip {
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
  text-transform: uppercase;
  color: rgba(184, 197, 221, 0.48);
  letter-spacing: 0.04em;
}

.legend-group-label {
  padding-left: 6px;
  border-left: 1px solid rgba(255, 255, 255, 0.12);
}

.legend-more-chip {
  padding: 5px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.055);
  border: 1px solid rgba(255, 255, 255, 0.09);
}

.legend-truck-chip {
  cursor: pointer;
  user-select: none;
  padding: 5px 8px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.10);
  background:
    radial-gradient(90% 130% at 0% 0%, rgba(255, 255, 255, 0.10), transparent 55%),
    rgba(255, 255, 255, 0.045);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transition:
    transform 0.18s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    opacity 0.18s ease;
}

.legend-truck-chip:hover,
.legend-truck-chip.legend-truck-hover,
.legend-truck-chip.legend-truck-active {
  transform: translateY(-1px);
  border-color: var(--truck-color, rgba(255, 255, 255, 0.28));
  background:
    radial-gradient(90% 130% at 0% 0%, rgba(255, 255, 255, 0.16), transparent 55%),
    rgba(255, 255, 255, 0.075);
  box-shadow:
    0 0 0 1px var(--truck-color, rgba(255, 255, 255, 0.20)),
    0 8px 22px rgba(0, 0, 0, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
}

.legend-truck-chip.legend-truck-active span:last-child {
  color: #f8fbff;
}

.inbound-uld-note {
  cursor: pointer;
}

.inbound-uld-note:hover {
  box-shadow:
    0 0 0 1px currentColor,
    0 8px 20px rgba(0, 0, 0, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);
  filter: brightness(1.10) saturate(1.08);
}

.inbound-uld-note.micro-tap,
.legend-truck-chip.micro-tap {
  animation: microTap 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes microTap {
  0% { transform: scale(1); }
  42% { transform: scale(0.94); }
  100% { transform: scale(1); }
}

.priority-card.plate-hover-dim {
  opacity: 0.46;
  filter: saturate(0.72) brightness(0.82);
}

.priority-card.plate-hover-match {
  opacity: 1;
  border-color: var(--plate-color, var(--card-color, #8b949e));
  box-shadow:
    0 0 0 1px var(--plate-color, var(--card-color, #8b949e)),
    0 0 22px var(--plate-color, rgba(139, 148, 158, 0.24)),
    0 16px 38px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.20);
}

.priority-card.plate-focus-dim {
  opacity: 0.24;
  filter: grayscale(0.24) saturate(0.54) brightness(0.70);
  transform: scale(0.992);
}

.priority-card.plate-focus-match {
  opacity: 1;
  border-color: var(--plate-color, var(--card-color, #8b949e));
  transform: translateY(-2px) scale(1.006);
  box-shadow:
    0 0 0 1px var(--plate-color, var(--card-color, #8b949e)),
    0 0 30px var(--plate-color, rgba(139, 148, 158, 0.26)),
    0 18px 44px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
}

.priority-card.plate-focus-match .inbound-uld-note,
.priority-card.plate-hover-match .inbound-uld-note {
  transform: translateY(-1px);
  box-shadow:
    0 0 0 1px currentColor,
    0 8px 22px rgba(0, 0, 0, 0.20),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.priority-card.plate-focus-pulse,
.priority-card.card-action-feedback,
.priority-card.card-expand-feedback {
  animation: cardMicroPulse 0.54s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes cardMicroPulse {
  0% {
    filter: brightness(1) saturate(1);
  }
  38% {
    filter: brightness(1.18) saturate(1.16);
  }
  100% {
    filter: brightness(1) saturate(1);
  }
}

.plate-focus-pill {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 9100;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid var(--plate-focus-color, rgba(255, 255, 255, 0.24));
  background:
    radial-gradient(120% 140% at 0% 0%, rgba(255, 255, 255, 0.16), transparent 55%),
    rgba(8, 12, 28, 0.82);
  color: #f8fbff;
  backdrop-filter: blur(18px) saturate(165%);
  -webkit-backdrop-filter: blur(18px) saturate(165%);
  box-shadow:
    0 14px 42px rgba(0, 0, 0, 0.38),
    0 0 24px var(--plate-focus-color, rgba(139, 148, 158, 0.18)),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 12px) scale(0.96);
  transition:
    opacity 0.22s ease,
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.plate-focus-pill-visible {
  opacity: 1;
  pointer-events: auto;
  transform: translate(-50%, 0) scale(1);
}

/* The pinned truck-focus pill belongs to the inbound flow only — keep it from
   bleeding onto the KPI page or the ULD / outbound flows. The focus state itself
   persists, so it reappears when you return to inbound. */
body.view-kpi-mode .plate-focus-pill,
body.flow-uld-mode .plate-focus-pill,
body.flow-outbound-mode .plate-focus-pill {
  display: none !important;
}

.plate-focus-dot {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--plate-focus-color, #8b949e);
  box-shadow: 0 0 16px var(--plate-focus-color, rgba(139, 148, 158, 0.55));
}

.plate-focus-text {
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.plate-focus-clear {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.10);
  color: rgba(248, 251, 255, 0.82);
  font-size: 15px;
  line-height: 1;
}

.action-pending {
  position: relative;
  filter: saturate(0.9) brightness(0.96);
}

.badge-stored-empty.action-pending::after,
.badge-stored-active.action-pending::after,
.refresh-btn.action-pending::after {
  content: '';
  width: 9px;
  height: 9px;
  margin-left: 7px;
  border-radius: 999px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  display: inline-block;
  vertical-align: -1px;
  animation: pendingSpin 0.72s linear infinite;
}

@keyframes pendingSpin {
  to { transform: rotate(360deg); }
}





























