/* ── KPI page interactions (clickable cards, swap, drill-down) ──────────── */

/* Metric cards are now buttons: pointer + lift + active-view ring. */
.kpi-page-metric {
  cursor: pointer;
  position: relative;
  transition:
    transform 0.16s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    background 0.2s ease,
    opacity 0.18s ease;
}
.kpi-page-metric:hover {
  transform: translateY(-2px);
}
/* Hover border only on the NON-selected cards — the selected (is-active-view) card
   keeps its conic ring untouched. Both flows excluded symmetrically so inbound (orange)
   and outbound (purple) behave identically on the selected card. */
.kpi-page-metric:not(.is-active-view):hover { border-color: rgba(255,180,120,0.55); }
.kpi-page-chart-outbound .kpi-page-metric:not(.is-active-view):hover { border-color: rgba(190,165,255,0.55); }
.kpi-page-metric:not(.is-active-view):hover { opacity: 1; }
.kpi-page-metric:focus-visible {
  outline: 2px solid rgba(255,255,255,0.55);
  outline-offset: 2px;
}
/* "Shown on chart" indicator dot — bound-coloured (orange / purple). */
.kpi-page-metric.is-active-view::after {
  content: "";
  position: absolute;
  top: 9px;
  right: 9px;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: #ff8a3d;
  box-shadow: 0 0 10px #ff8a3d;
}
.kpi-page-chart-outbound .kpi-page-metric.is-active-view::after { background: #a78bfa; box-shadow: 0 0 10px #a78bfa; }
/* Disabled "Previous" card when there's no previous shift. */
.kpi-page-metric.prev.is-empty {
  cursor: default;
  opacity: 0.5;
  pointer-events: none;
}

/* Chart points are clickable for the hourly drill-down. */
.kpi-page-chart-svg { cursor: pointer; }

/* Pinned hourly detail popover on a chart. */
.kpi-page-point-detail {
  position: absolute;
  top: 8px;
  transform: translateX(-50%);
  min-width: 150px;
  padding: 10px 12px 11px;
  border-radius: 10px;
  background: rgba(8, 12, 26, 0.94);
  border: 1px solid rgba(255,255,255,0.14);
  box-shadow: 0 16px 38px rgba(0,0,0,0.46), inset 0 1px 0 rgba(255,255,255,0.12);
  backdrop-filter: blur(10px);
  pointer-events: auto;
  opacity: 0;
  transition: opacity 0.2s ease;
  z-index: 6;
}
.kpi-page-point-detail.is-open { animation: kpiDetailPop 0.26s cubic-bezier(0.22, 1, 0.36, 1); }
.kpi-page-detail-close {
  position: absolute;
  top: 5px;
  right: 6px;
  width: 18px;
  height: 18px;
  border: 0;
  border-radius: 6px;
  background: rgba(255,255,255,0.08);
  color: rgba(226,232,240,0.8);
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
}
.kpi-page-detail-close:hover { background: rgba(255,255,255,0.16); }
.kpi-page-detail-h {
  font-size: 11px;
  font-weight: 900;
  color: #f8fbff;
  margin-bottom: 7px;
  padding-right: 16px;
}
.kpi-page-detail-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 11px;
  font-weight: 800;
  padding: 2px 0;
  color: rgba(203,213,225,0.66);
}
.kpi-page-detail-row b { color: #f8fbff; font-variant-numeric: tabular-nums; }

@keyframes kpiDetailPop {
  from { opacity: 0; transform: translateX(-50%) translateY(4px) scale(0.96); }
  to { opacity: 1; transform: translateX(-50%) translateY(0) scale(1); }
}

/* Tracking drill-down panel under the summary. */
/* ── Tracking groups are clickable; breakdown opens in a shared dropdown ── */
.kpi-tracking-group {
  cursor: pointer;
  position: relative;
  transition:
    transform 0.16s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}
.kpi-tracking-group:hover {
  transform: translateY(-2px);
  border-color: var(--group-accent);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.10),
    0 16px 38px rgba(0,0,0,0.26),
    0 0 26px var(--group-accent);
}
.kpi-tracking-group:focus-visible { outline: 2px solid rgba(255,255,255,0.5); outline-offset: 2px; }
.kpi-tracking-group.is-detail-active {
  border-color: var(--group-accent);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.12),
    0 0 0 1px var(--group-accent),
    0 16px 38px rgba(0,0,0,0.28);
}
.kpi-group-chevron {
  width: 8px;
  height: 8px;
  border-right: 2px solid rgba(226,232,240,0.5);
  border-bottom: 2px solid rgba(226,232,240,0.5);
  transform: rotate(45deg);
  transition: transform 0.24s ease, border-color 0.2s ease;
}
.kpi-tracking-group:hover .kpi-group-chevron { border-color: rgba(248,251,255,0.85); }
.kpi-tracking-group.is-detail-active .kpi-group-chevron { transform: rotate(225deg); }

/* Decorative hover on the result cards inside a group (incl. 12h operations):
   a soft sheen sweep + lift, so every card reacts even though the group is the
   click target. */
.kpi-tracking-card {
  position: relative;
  overflow: hidden;
  transition: transform 0.18s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.18s ease;
}
.kpi-tracking-card::after {
  content: "";
  position: absolute;
  top: 0;
  left: -120%;
  width: 60%;
  height: 100%;
  pointer-events: none;
  background: linear-gradient(100deg, transparent, rgba(255,255,255,0.14), transparent);
  transition: left 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}
.kpi-tracking-group:hover .kpi-tracking-card { transform: translateY(-1px); }
.kpi-tracking-group:hover .kpi-tracking-card::after { left: 160%; }
.kpi-tracking-card.ratio-big strong { font-size: 23px; }

/* ── Shared breakdown dropdown ─────────────────────────────────────────── */
.kpi-tracking-detail {
  --detail-accent: rgba(129,140,248,0.9);
  --detail-accent-soft: rgba(129,140,248,0.14);
  --detail-accent-rgb: 129,140,248;
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  margin: 0;
  border-radius: 0 0 14px 14px;
  transition:
    max-height 0.42s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.26s ease,
    margin 0.26s ease;
}
.kpi-tracking-detail.group-warehouse  { --detail-accent: rgba(52,211,153,0.95);  --detail-accent-soft: rgba(52,211,153,0.13); --detail-accent-rgb: 52,211,153; }
.kpi-tracking-detail.group-operations { --detail-accent: rgba(251,146,60,0.95);  --detail-accent-soft: rgba(251,146,60,0.13); --detail-accent-rgb: 251,146,60; }
.kpi-tracking-detail.group-arrivals   { --detail-accent: rgba(168,85,247,0.95);  --detail-accent-soft: rgba(168,85,247,0.14); --detail-accent-rgb: 168,85,247; }
.kpi-tracking-detail.group-forecast   { --detail-accent: rgba(34,211,238,0.95);  --detail-accent-soft: rgba(34,211,238,0.13); --detail-accent-rgb: 34,211,238; }

.kpi-tracking-detail.is-open {
  position: relative;
  max-height: 720px;
  opacity: 1;
  margin: -4px 0 16px;
  padding: 18px 18px 16px;
  /* Clearly a pull-out panel: tinted glass, an accent rail on top, recessed. */
  background:
    radial-gradient(130% 120% at 0% 0%, var(--detail-accent-soft), transparent 58%),
    linear-gradient(180deg, rgba(10, 14, 30, 0.82), rgba(6, 9, 22, 0.74)),
    rgba(6, 9, 22, 0.6);
  border: 1px solid rgba(255,255,255,0.10);
  border-top: 3px solid var(--detail-accent);
  box-shadow:
    inset 0 14px 26px rgba(0,0,0,0.34),
    0 22px 48px rgba(0,0,0,0.34);
  backdrop-filter: blur(14px) saturate(150%);
  -webkit-backdrop-filter: blur(14px) saturate(150%);
  animation: kpiDropIn 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes kpiDropIn {
  from { clip-path: inset(0 0 100% 0); opacity: 0; }
  to { clip-path: inset(0 0 0 0); opacity: 1; }
}
.kpi-detail-body.kpi-detail-swap { animation: kpiSwapIn 0.3s cubic-bezier(0.22, 1, 0.36, 1) both; }
@keyframes kpiSwapIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.kpi-detail-close {
  position: absolute;
  top: 12px;
  right: 14px;
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 7px;
  background: rgba(255,255,255,0.08);
  color: rgba(226,232,240,0.82);
  font-size: 15px;
  cursor: pointer;
  z-index: 2;
  transition: background 0.16s ease, transform 0.16s ease;
}
.kpi-detail-close:hover { background: rgba(255,255,255,0.18); transform: scale(1.08); }
.kpi-detail-title {
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--detail-accent);
  margin-bottom: 12px;
  padding-right: 30px;
}

/* Stat cells row (warehouse / operations) */
.kpi-detail-cells {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 10px;
}
.kpi-detail-cell {
  display: grid;
  gap: 4px;
  padding: 11px 13px;
  border-radius: 10px;
  background: linear-gradient(150deg, rgba(255,255,255,0.06), rgba(255,255,255,0.022));
  border: 1px solid rgba(255,255,255,0.08);
}
.kpi-detail-cell span { font-size: 11.5px; font-weight: 800; letter-spacing: 0.02em; color: rgba(203,213,225,0.7); }
.kpi-cu { display: block; font-size: 19px; font-weight: 950; color: #f8fbff; font-variant-numeric: tabular-nums; }
.kpi-detail-cell .kpi-detail-prop {
  margin-top: 4px;
  height: 5px;
  border-radius: 999px;
  background: rgba(255,255,255,0.07);
  overflow: hidden;
}
.kpi-detail-cell .kpi-detail-prop i { display: block; height: 100%; border-radius: 999px; background: var(--detail-accent); }
.kpi-detail-cell.op-transfer .kpi-detail-prop i { background: #fb923c; }
.kpi-detail-cell.op-release .kpi-detail-prop i { background: #22d3ee; }
.kpi-detail-cell.op-late .kpi-detail-prop i { background: #fb7185; }

/* Warehouse breakdown extras: no side rails here. Keep the cards operational and
   understated; use typography, spacing and a low accent field instead of generic
   coloured strips. */
.kpi-detail-subtitle {
  margin: 16px 0 10px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: rgba(203,213,225,0.62);
}
.kpi-detail-subtitle::after {
  content: "";
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(255,255,255,0.14), transparent);
}
.kpi-detail-extra .kpi-detail-cell {
  border-left: 0;
}
.kpi-detail-extra .wh-free .kpi-cu { color: #fde68a; }
.kpi-detail-dual-vals {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px 9px;
}
.kpi-detail-dual-vals .kpi-cu { display: inline-block; font-size: 16px; }
.kpi-detail-dual-sep {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(255,255,255,0.34);
}




/* Big saturation bar */
.kpi-detail-satbar {
  position: relative;
  height: 12px;
  margin-bottom: 14px;
  border-radius: 999px;
  background: rgba(255,255,255,0.07);
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.3);
}
.kpi-detail-satbar i {
  display: block;
  height: 100%;
  width: var(--sat-pct, 0%);
  border-radius: 999px;
  background: var(--sat-color, #34d399);
  box-shadow: 0 0 14px var(--sat-color, #34d399);
  transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Daily rows table with a cohesive proportional row-fill behind the numbers */
.kpi-detail-rows { width: 100%; border-collapse: collapse; }
.kpi-detail-rows thead th {
  padding: 4px 10px 7px;
  text-align: right;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: rgba(203,213,225,0.5);
}
.kpi-detail-rows thead th:first-child { text-align: left; }
.kpi-detail-rows tbody tr {
  background: linear-gradient(90deg, var(--detail-accent-soft) var(--row-fill, 0%), transparent var(--row-fill, 0%));
}
.kpi-detail-rows tbody td {
  padding: 5px 10px;
  text-align: right;
  font-size: 11.5px;
  font-weight: 800;
  color: rgba(226,232,240,0.9);
  font-variant-numeric: tabular-nums;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.kpi-detail-rows tbody td.kpi-rowbar-day { text-align: left; color: rgba(203,213,225,0.62); }
.kpi-detail-rows tbody tr.is-today td { color: #fff; }
.kpi-detail-rows tbody tr.is-today td.kpi-rowbar-day { color: var(--detail-accent); }

/* Forecast ratio cells (larger numbers) */
.kpi-detail-ratios {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}
.kpi-detail-ratio {
  display: grid;
  gap: 3px;
  padding: 12px 14px;
  border-radius: 10px;
  background: linear-gradient(150deg, rgba(255,255,255,0.07), rgba(255,255,255,0.022));
  border: 1px solid rgba(255,255,255,0.09);
}
.kpi-detail-ratio span { font-size: 11px; font-weight: 800; color: rgba(203,213,225,0.62); }
.kpi-detail-ratio .kpi-cu { font-size: 26px; }

.kpi-detail-foot {
  margin-top: 11px;
  font-size: 11px;
  font-weight: 800;
  color: rgba(203,213,225,0.62);
}
.kpi-detail-foot .kpi-cu { display: inline; font-size: 12px; color: #f8fbff; }













/* Staggered smooth opening of KPI page sections. Tied to body.view-kpi-mode so
   the whole cascade replays every time the KPI page is (re)entered. */
body.view-kpi-mode .kpi-page-head { animation: kpiPageIn 0.42s cubic-bezier(0.22, 1, 0.36, 1) both; }
body.view-kpi-mode .kpi-tracking-section { animation: kpiPageIn 0.5s cubic-bezier(0.22, 1, 0.36, 1) 0.30s both; }

/* Inbound/outbound flow cards: a premium staggered entrance — inbound leads,
   outbound follows, and inside each card the header → metric chips cascade up
   before the SVG line draw-on + kg count-up (JS) play on top. */
body.view-kpi-mode .kpi-page-chart-card {
  animation: kpiCardRise 0.66s cubic-bezier(0.22, 1, 0.36, 1) both;
}
body.view-kpi-mode .kpi-page-chart-inbound  { animation-delay: 0.08s; }
body.view-kpi-mode .kpi-page-chart-outbound { animation-delay: 0.20s; }
@keyframes kpiCardRise {
  from { opacity: 0; transform: translateY(22px) scale(0.975); }
  55%  { opacity: 1; }
  to   { opacity: 1; transform: none; }
}
body.view-kpi-mode .kpi-page-chart-head,
body.view-kpi-mode .kpi-page-metric {
  animation: kpiInnerRise 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
}
body.view-kpi-mode .kpi-page-chart-inbound  .kpi-page-chart-head            { animation-delay: 0.20s; }
body.view-kpi-mode .kpi-page-chart-inbound  .kpi-page-metric:nth-child(1)   { animation-delay: 0.26s; }
body.view-kpi-mode .kpi-page-chart-inbound  .kpi-page-metric:nth-child(2)   { animation-delay: 0.32s; }
body.view-kpi-mode .kpi-page-chart-outbound .kpi-page-chart-head            { animation-delay: 0.32s; }
body.view-kpi-mode .kpi-page-chart-outbound .kpi-page-metric:nth-child(1)   { animation-delay: 0.38s; }
body.view-kpi-mode .kpi-page-chart-outbound .kpi-page-metric:nth-child(2)   { animation-delay: 0.44s; }
@keyframes kpiInnerRise {
  from { opacity: 0; transform: translateY(11px); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .kpi-page-metric, .kpi-tracking-group, .kpi-tracking-card { transition: none; }
  .kpi-tracking-card::after { display: none; }
  .kpi-page-point-detail.is-open,
  .kpi-tracking-detail.is-open,
  .kpi-detail-body.kpi-detail-swap,
  body.view-kpi-mode .kpi-page-head,
  body.view-kpi-mode .kpi-page-grid,
  body.view-kpi-mode .kpi-page-chart-card,
  body.view-kpi-mode .kpi-page-chart-head,
  body.view-kpi-mode .kpi-page-metric,
  body.view-kpi-mode .kpi-tracking-section { animation: none; }
}

.kpi-tracking-section {
  margin: 0 0 16px;
  padding: 18px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.105);
  background:
    radial-gradient(120% 90% at 10% 112%, rgba(52,211,153,0.16), transparent 62%),
    radial-gradient(110% 90% at 96% 8%, rgba(96,165,250,0.12), transparent 58%),
    linear-gradient(145deg, rgba(255,255,255,0.075), rgba(255,255,255,0.026)),
    rgba(22, 33, 57, 0.60);
  box-shadow:
    0 18px 46px rgba(0,0,0,0.24),
    inset 0 1px 0 rgba(255,255,255,0.10);
}

.kpi-tracking-card.skeleton strong {
  color: rgba(203,213,225,0.42);
}

.kpi-tracking-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
}

.kpi-tracking-title {
  margin: 4px 0 0;
  color: #f8fbff;
  font-size: 19px;
  font-weight: 900;
  letter-spacing: 0;
}

.kpi-tracking-subtitle {
  margin-top: 3px;
  color: rgba(203,213,225,0.5);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
}


.kpi-tracking-capacity {
  color: rgba(203,213,225,0.56);
  font-size: 12px;
  font-weight: 850;
  font-variant-numeric: tabular-nums;
}

.kpi-tracking-summary {
  display: grid;
  grid-template-columns: minmax(220px, 0.85fr) minmax(280px, 1fr) minmax(300px, 1.1fr) minmax(280px, 1fr);
  gap: 14px;
  align-items: stretch;
}

.kpi-tracking-group {
  --group-accent: rgba(96,165,250,0.24);
  min-width: 0;
  display: grid;
  grid-template-rows: auto 1fr 1fr 1fr;
  row-gap: 10px;
  padding: 12px;
  border-radius: 9px;
  border: 1px solid rgba(255,255,255,0.085);
  /* Soft centred wash, not a bottom-anchored glow (which formed a bright coloured
     bar along the group's lower edge). */
  background:
    radial-gradient(130% 130% at 50% 45%, var(--group-accent), transparent 75%),
    linear-gradient(145deg, rgba(255,255,255,0.070), rgba(255,255,255,0.026)),
    rgba(255,255,255,0.038);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.075),
    0 12px 32px rgba(0,0,0,0.18);
}

.kpi-tracking-group.warehouse { --group-accent: rgba(52,211,153,0.24); }
.kpi-tracking-group.operations { --group-accent: rgba(251,146,60,0.22); }
.kpi-tracking-group.arrivals { --group-accent: rgba(168,85,247,0.18); }
.kpi-tracking-group.forecast { --group-accent: rgba(34,211,238,0.16); }

.kpi-tracking-group-head {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 0;
  text-align: center;
}

.kpi-tracking-group-head::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--group-accent);
  box-shadow: 0 0 16px var(--group-accent);
}

.kpi-tracking-group-head span {
  color: rgba(226,232,240,0.76);
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.kpi-tracking-group-grid {
  display: grid;
  grid-row: 2 / 5;
  grid-template-rows: subgrid;
  grid-template-columns: minmax(0, 1fr);
  column-gap: 10px;
  align-items: stretch;
}

.kpi-tracking-group.warehouse .kpi-tracking-group-grid {
  grid-template-columns: 1fr;
}
.kpi-tracking-group.warehouse .kpi-tracking-card.saturation {
  grid-row: 1 / 3;
  align-self: stretch;
}

.kpi-tracking-group.operations .kpi-tracking-group-grid {
  grid-template-columns: 1fr 1fr;
}
.kpi-tracking-group.arrivals .kpi-tracking-group-grid {
  grid-template-columns: 1fr 1fr;
}
.kpi-tracking-group.forecast .kpi-tracking-group-grid {
  grid-template-columns: repeat(3, 1fr);
}
.kpi-tracking-group.forecast .kpi-tracking-comp {
  grid-column: 1 / -1;
  grid-row: 1 / 3;
}
.kpi-tracking-card.span-full {
  grid-column: 1 / -1;
  grid-row: 2 / 4;
}
.kpi-tracking-previous-set {
  grid-column: 1 / -1;
}

.kpi-tracking-card {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 11px 12px;
  text-align: center;
  border-radius: 8px;
  border: 1px solid rgba(255,255,255,0.078);
  /* Centred, soft tint — NOT bottom-anchored. A radial at 50% 112% put its bright
     edge at the card bottom, so every card showed a coloured stripe along its base
     and a row of them read as a band. Centring it (50% 50%, fading by ~72%) tints
     the whole card with no hard edge; the top highlight is a hairline so card-tops
     don't line up into a light band. */
  background:
    radial-gradient(125% 125% at 50% 50%, rgba(96,165,250,0.12), transparent 72%),
    linear-gradient(145deg, rgba(255,255,255,0.070), rgba(255,255,255,0.024)),
    rgba(255,255,255,0.050);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04);
}

.kpi-tracking-card.saturation {
  min-height: 146px;
  background:
    radial-gradient(125% 125% at 50% 50%, rgba(52,211,153,0.20), transparent 72%),
    linear-gradient(145deg, rgba(255,255,255,0.080), rgba(255,255,255,0.026)),
    rgba(255,255,255,0.056);
}

.kpi-tracking-card.transfer {
  background:
    radial-gradient(125% 125% at 50% 50%, rgba(251,146,60,0.18), transparent 72%),
    rgba(255,255,255,0.052);
}

.kpi-tracking-card.release {
  background:
    radial-gradient(125% 125% at 50% 50%, rgba(34,211,238,0.16), transparent 72%),
    rgba(255,255,255,0.052);
}

.kpi-tracking-card.late {
  background:
    radial-gradient(125% 125% at 50% 50%, rgba(244,63,94,0.19), transparent 72%),
    rgba(255,255,255,0.052);
}

.kpi-tracking-card.expected,
.kpi-tracking-card.arrived,
.kpi-tracking-card.transferred,
.kpi-tracking-card.remaining,
.kpi-tracking-card.free-capacity,
.kpi-tracking-card.capacity-used {
  background:
    radial-gradient(125% 125% at 50% 50%, rgba(168,85,247,0.15), transparent 72%),
    rgba(255,255,255,0.048);
}

.kpi-tracking-card span,
.kpi-tracking-card em {
  display: block;
  color: rgba(203,213,225,0.58);
  font-size: 11px;
  font-style: normal;
  font-weight: 800;
  line-height: 1.25;
}

.kpi-tracking-card strong {
  display: block;
  margin: 5px 0 3px;
  color: #f8fbff;
  font-size: 18px;
  font-weight: 950;
  font-variant-numeric: tabular-nums;
}

.kpi-tracking-card.saturation strong {
  font-size: 28px;
  margin-top: 7px;
}

.kpi-tracking-card.saturation .kpi-saturation-kg {
  color: #ffffff;
  font-size: 17px;
