/* KPI refinement pass: stronger report surface, individual tracking hovers,
   integrated header saturation line and smoother staged motion. */
.kpi-page {
  position: relative;
  isolation: isolate;
  min-height: calc(100vh - 120px);
}

.kpi-page::before {
  content: "";
  position: absolute;
  inset: -20px -24px -64px;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(80% 60% at 15% 4%, rgba(56,189,248,0.16), transparent 60%),
    radial-gradient(86% 70% at 88% 18%, rgba(168,85,247,0.15), transparent 64%),
    radial-gradient(70% 80% at 48% 118%, rgba(52,211,153,0.12), transparent 68%),
    linear-gradient(180deg, rgba(122,151,212,0.08), rgba(122,151,212,0.0) 42%);
}



