.kpi-page-chart-card {
  border-color: rgba(255,190,132,0.36);
  background:
    radial-gradient(130% 92% at 0% 0%, rgba(255,138,61,0.22), transparent 60%),
    radial-gradient(85% 65% at 84% 112%, rgba(14,165,233,0.11), transparent 62%),
    linear-gradient(145deg, rgba(255,255,255,0.155), rgba(255,255,255,0.055)),
    rgba(22, 33, 58, 0.78);
  box-shadow:
    0 28px 70px rgba(0,0,0,0.36),
    0 0 0 1px rgba(255,138,61,0.16),
    0 0 46px rgba(255,138,61,0.18),
    inset 0 1px 0 rgba(255,255,255,0.20),
    inset 0 -18px 34px rgba(255,138,61,0.035);
}

.kpi-page-chart-outbound {
  border-color: rgba(203,180,255,0.38);
  background:
    radial-gradient(130% 92% at 0% 0%, rgba(167,139,250,0.24), transparent 60%),
    radial-gradient(85% 65% at 84% 112%, rgba(52,211,153,0.11), transparent 62%),
    linear-gradient(145deg, rgba(255,255,255,0.155), rgba(255,255,255,0.055)),
    rgba(22, 33, 58, 0.78);
  box-shadow:
    0 28px 70px rgba(0,0,0,0.36),
    0 0 0 1px rgba(167,139,250,0.18),
    0 0 46px rgba(167,139,250,0.20),
    inset 0 1px 0 rgba(255,255,255,0.20),
    inset 0 -18px 34px rgba(167,139,250,0.04);
}

/* Diagonal glass sheen. No idle loop (a continuous sweep here repaints the whole
   card every frame — it stuttered the page and froze as a streak in screenshots).
   It now rests off-card and sweeps across only on hover, so the motion is an
   intentional reaction to the cursor rather than perpetual background churn. */
.kpi-page-chart-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background:
    linear-gradient(120deg, transparent 22%, rgba(255,255,255,0.12) 48%, transparent 72%);
  background-size: 230% 100%;
  background-position: 130% 0;
  opacity: 0.5;
  transition: background-position 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}

.kpi-page-chart-card:hover::before {
  background-position: -60% 0;
}

@media (prefers-reduced-motion: reduce) {
  .kpi-page-chart-card::before { transition: none; }
}

.kpi-page-chart-card:hover {
  transform: translateY(-2px);
  border-color: rgba(255,210,160,0.52);
}

.kpi-page-chart-outbound:hover {
  border-color: rgba(216,196,255,0.54);
}

.kpi-page-metric {
  position: relative;
  isolation: isolate;
  text-align: center;
  padding: 12px 13px;
  transition:
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.24s ease,
    box-shadow 0.26s ease,
    background 0.28s ease,
    opacity 0.22s ease;
}

/* Selected shift card. Echoes the warehouse-tracking active block (a gradient
   ring that drifts slowly around the element) but much milder — low-opacity
   conic, gentle glow — so it reads as "selected" without competing with the
   chart. Accent follows the bound: inbound orange, outbound purple. */
.kpi-page-chart-inbound  { --metric-accent-rgb: 255,138,61; }
.kpi-page-chart-outbound { --metric-accent-rgb: 167,139,250; }

.kpi-page-metric.is-active-view {
  transform: translateY(-1px);
  border: 2px solid transparent;
  /* Static interior — only a soft accent fill, NO animation inside the card. */
  background:
    radial-gradient(125% 100% at 50% 112%, rgba(var(--metric-accent-rgb),0.12), transparent 70%) padding-box,
    linear-gradient(145deg, rgba(255,255,255,0.05), rgba(255,255,255,0.018)) padding-box,
    linear-gradient(rgba(255,255,255,0.05), rgba(255,255,255,0.05)) border-box;
  box-shadow:
    0 10px 28px rgba(var(--metric-accent-rgb),0.18),
    0 0 24px rgba(var(--metric-accent-rgb),0.16),
    inset 0 1px 0 rgba(255,255,255,0.16);
}

/* The slow rotating gradient lives ONLY on the frame: a masked conic ring drawn in
   the 1px border via ::before, so nothing inside the card animates. */
.kpi-page-metric.is-active-view::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  padding: 2px;
  pointer-events: none;
  background: conic-gradient(from var(--tracking-border-angle),
    rgba(var(--metric-accent-rgb),0.18),
    rgba(var(--metric-accent-rgb),0.88),
    rgba(255,255,255,0.30),
    rgba(var(--metric-accent-rgb),0.88),
    rgba(var(--metric-accent-rgb),0.18));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
  animation: kpiTrackingBorderSpin 5.2s linear infinite;
}
/* Keep the card's own content above the ring. */
.kpi-page-metric.is-active-view > * { position: relative; z-index: 1; }

@media (prefers-reduced-motion: reduce) {
  .kpi-page-metric.is-active-view::before { animation: none; }
}

.kpi-page-metric.is-active-view strong {
  font-size: 27px;
  color: #ffffff;
  text-shadow: 0 0 18px rgba(255,255,255,0.12);
}

.kpi-page-metric:not(.is-active-view) strong {
  font-size: 20px;
}

