  fill: rgba(9,13,26,0.92);
  stroke: rgba(226,232,240,0.40);
  stroke-width: 1.6;
}


/* "Now" divider between the recorded and upcoming hours. */
.kpi-page-nowline {
  stroke: rgba(255,255,255,0.30);
  stroke-width: 1.4;
  stroke-dasharray: 2 4;
  vector-effect: non-scaling-stroke;
  opacity: 0;
  animation: kpiPageNowIn 0.5s ease 0.35s forwards;
}

@keyframes kpiPageNowIn { to { opacity: 1; } }

/* Peak hour — a soft static halo + a crisp marker (no idle pulse: a continuous
   animation here was a needless per-frame cost on a page that already stutters). */
.kpi-page-peak-halo {
  opacity: 0;
  transition: opacity 0.5s ease 1.4s;
}
.kpi-page-chart-stage.is-line-complete .kpi-page-peak-halo { opacity: 0.18; }
.kpi-page-peak {
  stroke-width: 2.4;
  opacity: 0;
  filter: drop-shadow(0 0 4px rgba(255,138,61,0.55));
  transition: opacity 0.4s ease;
}
.kpi-page-chart-stage.is-line-complete .kpi-page-peak { opacity: 1; }
.kpi-page-chart-outbound .kpi-page-peak { filter: drop-shadow(0 0 5px rgba(167,139,250,0.6)); }

.kpi-page-dot {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition:
    opacity 0.38s ease,
    transform 0.38s cubic-bezier(0.22, 1, 0.36, 1);
  transform: scale(0.55);
}

.kpi-page-chart-stage.is-line-complete .kpi-page-dot {
  opacity: 1;
  transform: scale(1);
}

/* Per-hour value chips above the line. The <rect> is a dark translucent pill, the
   <text> inherits the bound's hue (orange inbound / purple outbound). Without these
   rules the rect fell back to default black fill and the text to invisible black —
   the "value shows only as a black circle" bug. They fade in with the draw-on so
   they don't pop in over a half-drawn curve. */
.kpi-page-value-label {
  opacity: 0;
  transition: opacity 0.4s ease;
}
.kpi-page-chart-stage.is-line-complete .kpi-page-value-label { opacity: 1; }
.kpi-page-chart-stage.is-line-complete .kpi-page-value-label.is-future { opacity: 0.5; }
/* Zero hours would otherwise render an empty "0" pill at the baseline — hide them. */
.kpi-page-value-label.is-zero { opacity: 0 !important; }

.kpi-page-value-label rect {
  fill: rgba(9,13,26,0.78);
  stroke: rgba(255,255,255,0.12);
  stroke-width: 1;
}
.kpi-page-value-label text {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.01em;
  fill: #ffd9b8;
}
.kpi-page-chart-outbound .kpi-page-value-label text { fill: #e4dcff; }

.kpi-page-value-label.is-current-hour rect { stroke: rgba(255,255,255,0.42); }

.kpi-page-value-label.is-peak rect {
  fill: rgba(255,138,61,0.92);
  stroke: rgba(255,255,255,0.32);
}
.kpi-page-value-label.is-peak text { fill: #1b1205; }
.kpi-page-chart-outbound .kpi-page-value-label.is-peak rect { fill: rgba(167,139,250,0.92); }
.kpi-page-chart-outbound .kpi-page-value-label.is-peak text { fill: #15102b; }

