@property --tracking-border-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@keyframes kpiTrackingBorderSpin {
  to { --tracking-border-angle: 360deg; }
}

.kpi-tracking-section {
  position: relative;
  /* Fallback for the rotating border: if @property isn't registered, the conic's
     `from var(--tracking-border-angle)` would be invalid and the whole border
     would drop out — this inherited base value keeps a static border visible. */
  --tracking-border-angle: 0deg;
  padding: 16px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.09);
  background: rgba(8, 15, 30, 0.34);
  box-shadow:
    0 14px 36px rgba(0,0,0,0.18),
    inset 0 1px 0 rgba(255,255,255,0.08);
  /* Lighter blur + skip rendering entirely while scrolled off-screen: the
     rotating borders inside then cost nothing when the section isn't visible. */
  backdrop-filter: blur(7px) saturate(125%);
  -webkit-backdrop-filter: blur(7px) saturate(125%);
  content-visibility: auto;
  contain-intrinsic-size: 0 620px;
}

