    linear-gradient(145deg, rgba(255,255,255,0.066), rgba(255,255,255,0.024)) padding-box,
    linear-gradient(rgba(255,255,255,0.035), rgba(255,255,255,0.035)) padding-box,
    conic-gradient(
      from var(--tracking-border-angle),
      rgba(var(--group-active-rgb), 0.16),
      rgba(var(--group-active-rgb), 0.72),
      rgba(255,255,255,0.18),
      rgba(var(--group-active-rgb), 0.72),
      rgba(var(--group-active-rgb), 0.16)
    ) border-box;
  box-shadow:
    0 0 0 1px rgba(var(--group-active-rgb), 0.14),
    0 12px 28px rgba(0,0,0,0.22),
    0 0 22px rgba(var(--group-active-rgb), 0.16),
    inset 0 1px 0 rgba(255,255,255,0.10);
  animation: kpiTrackingBorderSpin 7s linear infinite;
}

/* The card grid inside an open block gets its own border ring — a nested detail
   that echoes the block + dropdown. A permanent transparent border keeps the
   layout from shifting when it lights up. */
.kpi-tracking-group-grid {
  border: 1px solid transparent;
  border-radius: 9px;
  padding: 4px;
}
.kpi-tracking-group.is-detail-active .kpi-tracking-group-grid {
  position: relative;
  z-index: 0;
  isolation: isolate;
  overflow: hidden;
  border-color: rgba(var(--group-active-rgb), 0.20);
  background: rgba(8, 13, 26, 0.34);
}
/* The rotating gradient lives ONLY here — behind the cards, on the grid. An
   oversized, blurred conic glow clipped to the grid box; the cards stack above
   it (z-index) so the gleam reads through the gaps + padding, never on the card
   faces. Oversizing past every edge removes the old border's missing-corner
   artefact entirely — there is no border to clip, just a glow that always fills. */
.kpi-tracking-group.is-detail-active .kpi-tracking-group-grid::before {
  content: "";
  position: absolute;
  inset: -50%;
  z-index: -1;
  background: conic-gradient(
    from var(--tracking-border-angle),
    rgba(var(--group-active-rgb), 0.04),
    rgba(var(--group-active-rgb), 0.55),
    rgba(var(--group-active-rgb), 0.10),
    rgba(var(--group-active-rgb), 0.55),
    rgba(var(--group-active-rgb), 0.04)
  );
  filter: blur(20px);
  opacity: 0.85;
  pointer-events: none;
  animation: kpiTrackingBorderSpin 7s linear infinite;
}
.kpi-tracking-group.is-detail-active .kpi-tracking-card {
