.kpi-tracking-group.operations .kpi-tracking-card.late {
  grid-column: 1 / -1;
  min-height: 82px;
}

.kpi-tracking-card {
  min-height: 78px;
  padding: 10px 11px;
}

.kpi-tracking-card.saturation {
  min-height: 0;
}

.kpi-tracking-card strong {
  font-size: 19px;
  transition:
    font-size 0.24s ease,
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    text-shadow 0.24s ease;
}

.kpi-tracking-card.saturation strong {
  font-size: 26px;
}

.kpi-tracking-card.ratio-big strong,
.kpi-tracking-card.unit strong {
  font-size: 22px;
}

.kpi-tracking-detail.is-open {
  position: relative;
  max-height: min(520px, calc(100vh - 180px));
  overflow: auto;
  margin: 8px 0 10px;
  padding: 16px 14px;
  border: 1.5px solid transparent;
  border-radius: 14px;
  contain: paint;
  background:
    linear-gradient(180deg,
      var(--detail-accent-soft) 0%,
      rgba(255,255,255,0.045) 13%,
      rgba(255,255,255,0.016) 46%,
      rgba(255,255,255,0.008) 100%) padding-box,
    linear-gradient(rgba(11,17,32,0.92), rgba(8,13,26,0.90)) padding-box,
    conic-gradient(
      from var(--tracking-border-angle),
      rgba(var(--detail-accent-rgb), 0.42),
      rgba(var(--detail-accent-rgb), 0.88),
      rgba(255,255,255,0.5),
      rgba(var(--detail-accent-rgb), 0.88),
      rgba(var(--detail-accent-rgb), 0.42)
    ) border-box;
  /* The animated conic ring is brightest on the sides and dims as it spins; a
     uniform inset ring underneath guarantees every corner (incl. bottom-left /
     bottom-right) always shows a crisp border regardless of the spin phase.
     Inset is used (not an outset 0 0 0 ring) because `contain: paint` would clip
     an outset spread shadow. */
  box-shadow:
    inset 0 0 0 1.5px rgba(var(--detail-accent-rgb), 0.5),
    inset 0 16px 22px -14px var(--detail-accent),
    inset 0 -18px 22px -16px rgba(0,0,0,0.6),
    inset 0 1px 0 rgba(255,255,255,0.07),
    0 0 22px rgba(var(--detail-accent-rgb), 0.14),
    0 18px 40px rgba(0,0,0,0.30);
  animation:
    kpiDropSlide 0.36s cubic-bezier(0.22, 1, 0.36, 1) both,
    kpiTrackingBorderSpin 7s linear infinite;
}

.kpi-tracking-detail.is-open::before,
.kpi-tracking-detail.is-open::after {
  content: none;
  display: none;
}

.kpi-detail-close {
  position: absolute;
  top: 10px;
  right: 12px;
  left: auto;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 1px solid color-mix(in srgb, var(--detail-accent) 45%, rgba(255,255,255,0.16));
  border-radius: 8px;
  background:
    radial-gradient(120% 120% at 0% 0%, color-mix(in srgb, var(--detail-accent) 22%, transparent), transparent 62%),
    rgba(255,255,255,0.075);
  color: rgba(248,251,255,0.88);
  line-height: 1;
  z-index: 6;
}

.kpi-detail-title {
  margin-bottom: 8px;
  padding-right: 28px;
  font-size: 12px;
  letter-spacing: 0.02em;
}

.kpi-detail-cells {
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 8px;
}

.kpi-detail-ops {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.kpi-detail-ops .kpi-detail-cell.op-late {
  grid-column: auto;
}

.kpi-detail-cell {
  min-height: 0;
  padding: 8px 10px;
  border-radius: 8px;
}

.kpi-detail-cell span,
.kpi-detail-cell.op-release span,
.kpi-detail-cell.op-transfer span,
.kpi-detail-cell.op-late span {
  font-size: 10.5px;
}

.kpi-detail-cell .kpi-cu,
.kpi-tracking-detail .kpi-cu {
  font-size: 18px;
}

.kpi-detail-satbar {
  height: 9px;
  margin-bottom: 10px;
}

.kpi-detail-ratios {
  grid-template-columns: repeat(2, minmax(130px, 180px));
  gap: 8px;
  margin-bottom: 9px;
}

.kpi-detail-ratio {
  min-height: 68px;
  padding: 9px 11px;
  border-radius: 8px;
}

.kpi-detail-ratio .kpi-cu {
  font-size: 22px;
}

.kpi-detail-rows thead th {
  padding: 4px 8px 6px;
  font-size: 10px;
}

.kpi-detail-rows tbody td {
  padding: 6px 8px;
  font-size: 12.5px;
}

.kpi-detail-rows tbody td.kpi-rowbar-day {
  font-size: 12px;
}

.kpi-detail-rows tbody tr {
  background: transparent;
}

.kpi-detail-rows tbody tr:not(.is-today):not(.is-near-day) td {
  background: transparent;
}

.kpi-detail-rows tbody tr:not(.is-today):not(.is-near-day):hover td {
  background: rgba(255,255,255,0.035);
}

.kpi-detail-rows tbody tr.is-today {
  outline: none;
}

.kpi-detail-rows tbody tr.is-today td {
  background: color-mix(in srgb, var(--detail-accent) 9%, rgba(255,255,255,0.018));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--detail-accent) 16%, transparent),
    inset 0 -1px 0 color-mix(in srgb, var(--detail-accent) 16%, transparent);
}

.kpi-detail-rows tbody tr.is-today td.kpi-rowbar-day {
  color: #f8fbff;
  border-left: 2px solid var(--detail-accent);
}

.kpi-detail-rows tbody tr.is-near-day td {
  background: rgba(96,165,250,0.045);
  color: rgba(226,232,240,0.88);
}

.kpi-detail-foot {
  margin-top: 8px;
}

.kpi-detail-foot .kpi-cu {
  font-size: 12px;
}



