/* ═══════════════════════════════════════════════════════════════════════════
   KPI page — full-width volume-trend chart   (assets/kpi_trend.js)
   Breakdown (LMP / Országok / Prefix) + view (Nap / Hét) over the NOA-dated
   E_COMM history. Matches the inbound/outbound chart card language below it.
   ═══════════════════════════════════════════════════════════════════════════ */
.kpi-trend-section {
  position: relative;
  overflow: hidden;
  margin-bottom: 18px;
  padding: 18px 20px 16px;
  border-radius: 12px;
  border: 1px solid rgba(120, 170, 255, 0.22);
  background:
    radial-gradient(120% 80% at 100% 0%, rgba(96,165,250,0.13), transparent 60%),
    radial-gradient(120% 90% at 0% 0%, rgba(167,139,250,0.13), transparent 60%),
    linear-gradient(145deg, rgba(255,255,255,0.10), rgba(255,255,255,0.035)),
    rgba(21, 32, 56, 0.66);
  box-shadow:
    0 24px 60px rgba(0,0,0,0.32),
    0 0 0 1px rgba(120,170,255,0.08),
    inset 0 1px 0 rgba(255,255,255,0.14);
  animation: kpiChartCardIn 0.5s cubic-bezier(0.22,1,0.36,1) both;
}
.kpi-trend-section::before {
  content: "";
  position: absolute;
  inset: 1px;
  border-radius: inherit;
  pointer-events: none;
  background:
    linear-gradient(116deg, rgba(255,255,255,0.18), transparent 18%, transparent 76%, rgba(34,211,238,0.10)),
    repeating-linear-gradient(104deg, rgba(255,255,255,0.035) 0 1px, transparent 1px 18px);
  opacity: 0.38;
  mask-image: linear-gradient(to bottom, #000, transparent 72%);
}
.kpi-trend-section::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  pointer-events: none;
  background:
    conic-gradient(from 218deg at 50% 50%, transparent 0 23%, rgba(96,165,250,0.24) 32%, transparent 43%, rgba(255,138,61,0.16) 60%, transparent 76%, rgba(34,211,238,0.18) 88%, transparent 100%);
  filter: blur(13px);
  opacity: 0.24;
  mix-blend-mode: screen;
}
.kpi-trend-card-glow {
  position: absolute;
  inset: -34% -10% auto -10%;
  height: 62%;
  pointer-events: none;
  background: radial-gradient(50% 80% at 50% 0%, rgba(96,165,250,0.16), transparent 72%);
  filter: blur(26px);
}

.kpi-trend-head {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 18px;
  margin-bottom: 14px;
}
.kpi-trend-head-titles { min-width: 0; }
.kpi-trend-title {
