}
.kpi-trend-meta {
  margin-top: 5px;
  color: rgba(203,213,225,0.56);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.kpi-trend-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
/* Controls reuse the header-button language (refresh / theme / Operatív) so they
   sit naturally in the same UI — subtle base, accent border + glow on hover,
   tinted accent fill when active. Breakdown = blue accent, view = warm accent. */
.kpi-trend-ctl { display: inline-flex; gap: 6px; align-items: center; }
.kpi-trend-ctl-view::before {
  content: "";
  align-self: stretch;
  width: 1px;
  margin: 5px 4px 5px 2px;
  background: rgba(255,255,255,0.12);
}
.kpi-trend-btn {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: 32px;
  padding: 6px 15px 6px 18px;
  border-radius: 9px;
  border: 1px solid transparent;
  background:
    linear-gradient(145deg, rgba(13,21,38,0.88), rgba(22,33,56,0.68)) padding-box,
    linear-gradient(135deg, rgba(96,165,250,0.32), rgba(255,255,255,0.08), rgba(34,211,238,0.18)) border-box;
  color: var(--text-secondary, rgba(203,213,225,0.72));
  font-family: inherit;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.02em;
  white-space: nowrap;
  cursor: pointer;
  transition: color 0.18s ease, background 0.18s ease, border-color 0.18s ease,
              box-shadow 0.18s ease, transform 0.16s cubic-bezier(0.22,1,0.36,1);
}
.kpi-trend-btn::before {
  content: "";
  position: absolute;
  z-index: -1;
  left: 5px;
  top: 6px;
  bottom: 6px;
  width: 4px;
  border-radius: 99px;
  background: linear-gradient(180deg, #60a5fa, #22d3ee);
  opacity: 0.45;
  box-shadow: 0 0 14px rgba(96,165,250,0.24);
  transition: width 0.2s ease, opacity 0.2s ease, box-shadow 0.2s ease;
}
.kpi-trend-btn:hover {
  transform: translateY(-1px);
  border-color: rgba(120,170,255,0.55);
