  box-shadow: 0 10px 28px rgba(16,24,48,0.34), 0 0 18px rgba(96,165,250,0.17);
}
.kpi-trend-btn.is-active {
  border-color: rgba(120,170,255,0.60);
  color: #eaf2ff;
