    linear-gradient(145deg, rgba(34,211,238,0.55), rgba(96,165,250,0.72), rgba(167,139,250,0.38)) border-box;
  box-shadow: 0 12px 30px rgba(16,24,48,0.38), 0 0 24px rgba(96,165,250,0.22), inset 0 1px 0 rgba(255,255,255,0.16);
}
.kpi-trend-btn.is-active::before {
