  background: linear-gradient(180deg, #f8fbff, #38bdf8);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.24), 0 0 18px rgba(56,189,248,0.62);
}
.kpi-trend-ctl-view .kpi-trend-btn:hover {
  border-color: rgba(255,138,61,0.55);
