  background: rgba(255,138,61,0.10);
  box-shadow: 0 0 18px rgba(255,138,61,0.20);
}
.kpi-trend-ctl-view .kpi-trend-btn.is-active {
  border-color: rgba(255,138,61,0.60);
  color: #ffe6d2;
  background:
    radial-gradient(90% 150% at 0% 0%, rgba(255,138,61,0.38), transparent 64%) padding-box,
    linear-gradient(145deg, rgba(251,191,36,0.62), rgba(255,138,61,0.74), rgba(248,113,113,0.42)) border-box;
  box-shadow: 0 12px 30px rgba(16,24,48,0.36), 0 0 24px rgba(255,138,61,0.20), inset 0 1px 0 rgba(255,255,255,0.16);
}
.kpi-trend-ctl-view .kpi-trend-btn::before {
  background: linear-gradient(180deg, #fbbf24, #fb923c);
  box-shadow: 0 0 14px rgba(251,146,60,0.24);
}
.kpi-trend-ctl-view .kpi-trend-btn.is-active::before {
  width: 4px;
  opacity: 1;
  background: linear-gradient(180deg, #fff7ed, #fb923c);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.22), 0 0 18px rgba(251,146,60,0.62);
}

/* "Vizsgált időszak" — preset chips + from/to date inputs */
