  transform-origin: center;
}
.kpi-trend-search-clear::before { transform: translate(-50%,-50%) rotate(45deg); }
.kpi-trend-search-clear::after  { transform: translate(-50%,-50%) rotate(-45deg); }
.kpi-trend-search-clear:hover {
  background: rgba(248,113,113,0.30);
}
.kpi-trend-search-clear:hover::before,
.kpi-trend-search-clear:hover::after { background: #fff; }


.kpi-trend-chiprow { display: flex; flex-wrap: wrap; gap: 7px; }
.kpi-trend-chip {
  --chip: #94a3b8;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  max-width: 100%;
  min-height: 28px;
  padding: 5px 13px 5px 9px;
  border-radius: 999px;
  border: 1px solid transparent;
  background:
    linear-gradient(145deg, rgba(255,255,255,0.045), rgba(255,255,255,0.018)) padding-box,
    linear-gradient(135deg, rgba(255,255,255,0.12), color-mix(in srgb, var(--chip) 30%, transparent), rgba(255,255,255,0.06)) border-box;
  color: rgba(203,213,225,0.6);
  font-size: 11.5px;
  font-weight: 750;
  cursor: pointer;
  transition: color 0.2s ease, background 0.22s ease, border-color 0.22s ease,
              transform 0.16s cubic-bezier(0.22,1,0.36,1), box-shadow 0.22s ease;
}
.kpi-trend-chip:hover {
  transform: translateY(-1px);
  border-color: transparent;
  color: rgba(237,242,255,0.92);
  box-shadow: 0 9px 22px rgba(0,0,0,0.20), 0 0 18px color-mix(in srgb, var(--chip) 18%, transparent);
}
.kpi-trend-chip-dot {
  width: 9px; height: 9px;
  flex: none;
  border-radius: 999px;
  background: var(--chip);
  opacity: 0.38;
  transition: opacity 0.22s ease, box-shadow 0.22s ease;
}
.kpi-trend-chip-l {
  max-width: 200px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-trend-chip.is-on {
  color: #f3f7ff;
  border-color: transparent;
  background:
    radial-gradient(120% 170% at 0% 0%, color-mix(in srgb, var(--chip) 28%, transparent), transparent 62%) padding-box,
    linear-gradient(135deg, color-mix(in srgb, var(--chip) 74%, white 8%), rgba(255,255,255,0.15)) border-box;
  box-shadow: 0 0 20px color-mix(in srgb, var(--chip) 18%, transparent), inset 0 1px 0 rgba(255,255,255,0.12);
}
.kpi-trend-chip.is-on .kpi-trend-chip-dot { opacity: 1; box-shadow: 0 0 9px var(--chip); }
.kpi-trend-chip.is-focused {
  color: #f3f7ff;
  border-color: transparent;
  transform: translateY(-1px);
  box-shadow: 0 0 0 2px var(--chip), 0 0 16px -2px var(--chip), inset 0 1px 0 rgba(255,255,255,0.14);
}
.kpi-trend-chip.is-focused .kpi-trend-chip-dot { opacity: 1; box-shadow: 0 0 9px var(--chip); }
.kpi-trend-empty-chip {
  padding: 4px 2px;
  color: rgba(203,213,225,0.45);
  font-size: 12px;
  font-weight: 700;
}

.kpi-trend-chart-shell {
  position: relative;
  z-index: 1;
  overflow: hidden;
  padding: 8px 12px 12px;
  border-radius: 18px;
  border: 1px solid rgba(176,205,255,0.18);
  background:
    linear-gradient(118deg, rgba(255,255,255,0.11) 0%, transparent 17%, rgba(34,211,238,0.045) 36%, transparent 58%, rgba(255,255,255,0.055) 100%),
    repeating-linear-gradient(101deg, rgba(255,255,255,0.035) 0 1px, transparent 1px 22px),
    linear-gradient(155deg, rgba(28,44,76,0.70), rgba(20,30,52,0.46) 48%, rgba(24,40,66,0.60)),
    rgba(18, 28, 48, 0.38);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.18),
    inset 0 -1px 0 rgba(255,255,255,0.055),
    inset 18px 0 42px rgba(96,165,250,0.045),
    inset -18px 0 42px rgba(34,211,238,0.05),
    0 20px 48px rgba(0,0,0,0.22);
}
.kpi-trend-chart-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  /* A very soft glass sheen only — the old bright diagonal band (white 0.18) read
     as a light beam striking across the chart data. Kept faint so it's an edge
     gloss, not a streak over the lines. */
  background:
    linear-gradient(105deg, transparent 0 10%, rgba(255,255,255,0.06) 15%, rgba(255,255,255,0.012) 22%, transparent 30% 100%);
  opacity: 0.5;
  transform: skewX(-7deg) translateX(-2%);
}
.kpi-trend-chart-shell::after {
  content: "";
  position: absolute;
  inset: 6px;
  pointer-events: none;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.070);
  box-shadow:
    0 0 0 1px rgba(96,165,250,0.12),
    10px 0 30px rgba(34,211,238,0.075),
    -10px 0 26px rgba(167,139,250,0.060),
    inset 0 0 28px rgba(255,255,255,0.022);
}
.kpi-trend-chart { position: relative; z-index: 1; min-height: 280px; }
.kpi-trend-chart.is-swapping .kpi-trend-stage {
  animation: kpiTrendSwap 0.42s cubic-bezier(0.22,1,0.36,1);
}
@keyframes kpiTrendSwap {
  from { opacity: 0.2; transform: translateY(7px) scale(0.99); filter: saturate(0.8); }
  to   { opacity: 1; transform: none; filter: saturate(1); }
}
.kpi-trend-stage { position: relative; }
.kpi-trend-svg { display: block; width: 100%; height: auto; overflow: visible; }

.kpi-trend-grid {
  stroke: rgba(255,255,255,0.08);
  stroke-width: 1;
  stroke-dasharray: 3 6;
  vector-effect: non-scaling-stroke;
}
.kpi-trend-grid.base { stroke: rgba(255,255,255,0.18); stroke-dasharray: none; }
.kpi-trend-ylabel { fill: rgba(241,245,249,0.78); font-size: 11px; font-weight: 900; font-variant-numeric: tabular-nums; }
.kpi-trend-xlabel { fill: rgba(226,232,240,0.66); font-size: 11px; font-weight: 850; font-variant-numeric: tabular-nums; }

/* Hover a legend entry to isolate its line — the rest dim back (declutter). */
.kpi-trend-series { transition: opacity 0.2s ease, filter 0.2s ease; }
/* Ctrl+click focus (solo): non-focused series fade right out, focused ones pop. */
.kpi-trend-series.is-unfocused { opacity: 0.06; }
.kpi-trend-series.is-focused .kpi-trend-line { stroke-width: 3.1; }
/* The data layer scales about the baseline (y=266 in the 0..300 viewBox) so the
   remaining lines can glide to a recalculated Y-scale (see morphScale in JS). */
.kpi-trend-scale { transform-box: view-box; transform-origin: 0px 266px; }
.kpi-trend-line {
  fill: none;
  stroke-width: 2.55;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  /* No drop-shadow filter: with ~30 lines that's 30 per-path filter passes every
     repaint — the main CPU cost on weak machines. The wide glow stroke below gives
     a filterless halo instead. */
  transition: stroke-dashoffset 1.9s cubic-bezier(0.22, 1, 0.36, 1);
}
.kpi-trend-line-glow {
  fill: none;
  stroke-width: 6.5;
  opacity: 0.16;
  /* Filterless halo (no blur()): a wide, low-opacity stroke reads as a soft glow
     without forcing every series into its own expensive blur layer. */
  vector-effect: non-scaling-stroke;
  transition: stroke-dashoffset 1.9s cubic-bezier(0.22, 1, 0.36, 1);
}
.kpi-trend-line-glow.dim { opacity: 0.07; }
.kpi-trend-area { opacity: 0; transition: opacity 0.7s ease 0.4s; }
.kpi-trend-stage.is-done .kpi-trend-area { opacity: 1; }
.kpi-trend-stage.is-opening-lines .kpi-trend-area,
.kpi-trend-stage.is-opening-lines .kpi-trend-dot {
  opacity: 0;
}
.kpi-trend-dot {
  fill: #0b1322;
  stroke-width: 1.8;
  opacity: 0;
  vector-effect: non-scaling-stroke;
  transition: opacity 0.35s ease;
}
.kpi-trend-stage.is-done .kpi-trend-dot { opacity: 0.92; }
.kpi-trend-series.is-entering .kpi-trend-dot { opacity: 0; }
.kpi-trend-series.is-entering.is-done .kpi-trend-dot { opacity: 0.92; }
.kpi-trend-series.kpi-trend-exit {
  pointer-events: none;
  opacity: 0.98;
  filter: saturate(1.05);
}
.kpi-trend-cross {
  stroke: rgba(255,255,255,0.30);
  stroke-width: 1;
  stroke-dasharray: 3 4;
  vector-effect: non-scaling-stroke;
  transition: opacity 0.12s ease;
}

.kpi-trend-tip {
  position: absolute;
  top: 6px;
  transform: translateX(-50%);
  min-width: 178px;
  max-width: 300px;
  padding: 9px 11px;
  border-radius: 11px;
  background: rgba(8,12,24,0.97);
  border: 1px solid rgba(255,255,255,0.12);
  box-shadow: 0 16px 36px rgba(0,0,0,0.45);
  /* Opaque bg instead of backdrop-filter: the tip follows the cursor, so a live
     backdrop blur would re-blur the chart behind it on every mousemove. */
  pointer-events: none;
  z-index: 5;
  transition: opacity 0.12s ease;
}
.kpi-trend-tip.flip { transform: translateX(-100%); }
.kpi-trend-tip-h {
  margin-bottom: 7px;
  color: rgba(226,232,240,0.62);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.kpi-trend-tip-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 4px;
  font-size: 12px;
}
.kpi-trend-tip-l { display: inline-flex; align-items: center; gap: 7px; min-width: 0; color: rgba(226,232,240,0.86); }
.kpi-trend-tip-l i { width: 8px; height: 8px; flex: none; border-radius: 999px; }
.kpi-trend-tip-t { max-width: 168px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.kpi-trend-tip-row b { color: #f8fbff; font-weight: 850; font-variant-numeric: tabular-nums; }

.kpi-trend-table-panel {
  position: relative;
  z-index: 1;
  margin-top: 12px;
}
.kpi-trend-table-panel:empty { display: none; }
.kpi-trend-table-drawer {
  border-radius: 13px;
  border: 1px solid rgba(255,255,255,0.09);
  background:
    linear-gradient(145deg, rgba(255,255,255,0.052), rgba(255,255,255,0.018)),
    rgba(6,11,24,0.42);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.09);
}
.kpi-trend-table-drawer.is-open {
  border-color: rgba(96,165,250,0.18);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.10), 0 12px 30px rgba(0,0,0,0.18);
}
.kpi-trend-data-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 11px;
}
.kpi-trend-table-toggle {
  min-width: 0;
  flex: 1;
  display: inline-flex;
  align-items: center;
  gap: 11px;
  border: 0;
  background: transparent;
  color: inherit;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  padding: 0;
}
.kpi-trend-toggle-icon {
  position: relative;
  flex: none;
  width: 28px;
  height: 28px;
  border-radius: 9px;
  border: 1px solid rgba(96,165,250,0.24);
  background:
    radial-gradient(90% 130% at 20% 0%, rgba(96,165,250,0.28), transparent 62%),
    rgba(15,23,42,0.58);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.12), 0 0 18px rgba(96,165,250,0.12);
}
.kpi-trend-toggle-icon::before,
.kpi-trend-toggle-icon::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 11px;
  height: 2px;
  border-radius: 99px;
  background: #bfdbfe;
  transform: translate(-50%, -50%);
}
.kpi-trend-toggle-icon::after {
  transform: translate(-50%, -50%) rotate(90deg);
  transition: transform 0.18s ease, opacity 0.18s ease;
}
.kpi-trend-table-drawer.is-open .kpi-trend-toggle-icon::after {
  transform: translate(-50%, -50%) rotate(0deg);
  opacity: 0;
}
.kpi-trend-data-kicker {
  margin-bottom: 3px;
  color: rgba(148,163,184,0.70);
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.kpi-trend-data-head strong {
  display: block;
  color: rgba(241,245,249,0.92);
  font-size: 13px;
  font-weight: 900;
}
.kpi-trend-table-actions {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  flex: none;
}
.kpi-trend-table-count {
  color: rgba(148,163,184,0.64);
  font-size: 11px;
  font-weight: 850;
  white-space: nowrap;
}
.kpi-trend-export {
  position: relative;
  min-height: 32px;
  padding: 6px 14px 6px 34px;
  border-radius: 9px;
  border: 1px solid transparent;
  background:
    linear-gradient(145deg, rgba(16,185,129,0.16), rgba(34,211,238,0.10)) padding-box,
    linear-gradient(135deg, rgba(52,211,153,0.58), rgba(34,211,238,0.38), rgba(96,165,250,0.34)) border-box;
  color: #dcfff4;
  font-family: inherit;
  font-size: 12px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 10px 28px rgba(0,0,0,0.25), 0 0 18px rgba(45,212,191,0.14);
  transition: transform 0.16s ease, box-shadow 0.18s ease, filter 0.18s ease;
}
.kpi-trend-export::before {
  content: "";
  position: absolute;
  left: 12px;
  top: 50%;
  width: 12px;
  height: 12px;
  transform: translateY(-50%);
  border: 2px solid currentColor;
  border-top: 0;
  border-radius: 0 0 3px 3px;
  opacity: 0.86;
}
.kpi-trend-export::after {
  content: "";
  position: absolute;
  left: 17px;
  top: 9px;
  width: 2px;
  height: 11px;
  border-radius: 99px;
  background: currentColor;
  box-shadow: 0 5px 0 -1px currentColor;
}
.kpi-trend-export:hover {
  transform: translateY(-1px);
  box-shadow: 0 14px 32px rgba(0,0,0,0.30), 0 0 24px rgba(45,212,191,0.22);
}
.kpi-trend-export:disabled { cursor: wait; opacity: 0.82; }
.kpi-trend-export.is-done {
  color: #ecfdf5;
  filter: saturate(1.18);
}
.kpi-trend-export.is-error {
  color: #fee2e2;
  background:
    linear-gradient(145deg, rgba(248,113,113,0.18), rgba(251,146,60,0.08)) padding-box,
    linear-gradient(135deg, rgba(248,113,113,0.70), rgba(251,146,60,0.40)) border-box;
}
.kpi-trend-table-wrap {
  overflow: auto;
  max-height: 380px;
  opacity: 1;
  overscroll-behavior: contain;
  margin: 0 10px 10px;
  border-radius: 11px;
  border: 1px solid rgba(255,255,255,0.08);
  background:
    linear-gradient(145deg, rgba(255,255,255,0.058), rgba(255,255,255,0.022)),
    rgba(19,29,50,0.52);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.09);
  transform: translateY(0);
  transition:
    max-height 420ms cubic-bezier(0.22,1,0.36,1),
    opacity 300ms ease,
    margin 420ms cubic-bezier(0.22,1,0.36,1),
    transform 420ms cubic-bezier(0.22,1,0.36,1),
    border-color 300ms ease;
}
/* Closed drawer: collapse the table away with a smooth height/opacity transition. */
.kpi-trend-table-drawer:not(.is-open) .kpi-trend-table-wrap {
  max-height: 0;
  opacity: 0;
  margin-top: 0;
  margin-bottom: 0;
  transform: translateY(-8px);
  border-color: transparent;
  pointer-events: none;
}
/* A filter / view change re-renders the table → a brief settle so it doesn't pop. */
.kpi-trend-table-swap { animation: kpiTrendTableSwap 320ms cubic-bezier(0.22,1,0.36,1); }
@keyframes kpiTrendTableSwap {
  from { opacity: 0.35; transform: translateY(7px); }
  to   { opacity: 1; transform: translateY(0); }
}
.kpi-trend-data-table {
  width: 100%;
  min-width: 760px;
  border-collapse: separate;
  border-spacing: 0;
  color: rgba(226,232,240,0.88);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.kpi-trend-data-table th,
.kpi-trend-data-table td {
  padding: 9px 11px;
  border-bottom: 1px solid rgba(255,255,255,0.055);
  white-space: nowrap;
}
.kpi-trend-data-table thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: #18243d;   /* opaque — avoids a backdrop-filter repaint on every table scroll */
  color: rgba(241,245,249,0.90);
  font-size: 11px;
  font-weight: 900;
  text-align: right;
}
.kpi-trend-data-table thead th:first-child,
.kpi-trend-data-table tbody th,
.kpi-trend-data-table tfoot th {
  text-align: left;
}
.kpi-trend-data-table thead th:first-child {
  border-top-left-radius: 12px;
}
.kpi-trend-data-table thead th:last-child {
  border-top-right-radius: 12px;
}
.kpi-trend-table-series {
  box-shadow: inset 0 3px 0 var(--series);
}
.kpi-trend-table-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: 7px;
  border-radius: 50%;
  background: var(--series);
  box-shadow: 0 0 10px var(--series);
  vertical-align: -1px;
}
.kpi-trend-data-table tbody th {
  color: #f8fbff;
  font-weight: 900;
}
.kpi-trend-row-key {
  display: block;
}
.kpi-trend-data-table tbody th .date-range {
  display: block;
  margin-top: 2px;
  color: rgba(203,213,225,0.58);
  font-size: 11px;
  font-weight: 800;
}
.kpi-trend-data-table tbody tr:nth-child(odd) td,
.kpi-trend-data-table tbody tr:nth-child(odd) th {
  background: rgba(255,255,255,0.018);
}
.kpi-trend-data-table tbody tr:hover td,
.kpi-trend-data-table tbody tr:hover th {
  background: rgba(96,165,250,0.08);
}
.kpi-trend-data-table .date-range {
  color: rgba(203,213,225,0.58);
  font-size: 11px;
  font-weight: 800;
}
.kpi-trend-data-table .num {
  text-align: right;
  font-weight: 850;
}
.kpi-trend-data-table .total {
  color: #f8fbff;
  background: rgba(96,165,250,0.07);
}
.kpi-trend-data-table .muted { color: rgba(148,163,184,0.38); }
.kpi-trend-data-table tfoot th,
.kpi-trend-data-table tfoot td {
  position: sticky;
  bottom: 0;
  /* Fully opaque + above the sticky body cells (z-index 1) so scrolling rows never
     bleed through the total row — it stays a solid bar across the whole footer. */
  z-index: 5;
  background: #18243d;
  color: #f8fbff;
  font-weight: 950;
  border-bottom: none;
}
.kpi-trend-data-table tfoot .total-spacer {
  color: transparent;
  background: #18243d;
}

/* ── structured browsing ─────────────────────────────────────────────────
   The period/week label is pinned to the left so series columns can be
   scrolled horizontally without losing the row's identity. */
.kpi-trend-data-table thead th:first-child { left: 0; z-index: 4; }
.kpi-trend-data-table tbody th[scope="row"] {
  position: sticky;
  left: 0;
  z-index: 1;
  background: #141d33;   /* opaque — series columns glide cleanly beneath it */
  box-shadow: 1px 0 0 rgba(255,255,255,0.07);
}
.kpi-trend-data-table tbody tr:nth-child(odd) th[scope="row"] { background: #18223c; }
.kpi-trend-data-table tbody tr:hover th[scope="row"] { background: #233355; }
.kpi-trend-data-table tfoot th:first-child { left: 0; z-index: 11; }

/* Peak value of each row (and the dominant column total): the heaviest series
   per period gets a clear emphasis + a baseline rule in its own series colour. */
.kpi-trend-data-table td.num.is-peak {
  color: #f8fbff;
  font-weight: 950;
  background: rgba(125,211,252,0.12);
  box-shadow: inset 0 -2px 0 var(--series, #60a5fa);
}

/* The totals column is pinned to the right edge as well, so each period's
   magnitude (value + data bar) stays on screen while scrolling across the many
   series columns. */
.kpi-trend-data-table thead th:last-child { right: 0; z-index: 4; }
.kpi-trend-data-table .total { position: sticky; right: 0; overflow: hidden; }
.kpi-trend-data-table tbody td.total {
  z-index: 1;
  background: #141d33;
  box-shadow: -1px 0 0 rgba(255,255,255,0.07);
}
.kpi-trend-data-table tbody tr:nth-child(odd) td.total { background: #18223c; }
.kpi-trend-data-table tbody tr:hover td.total { background: #233355; }
.kpi-trend-data-table tfoot td.total { z-index: 12; }

/* In-cell data bar on the totals column → magnitude is readable at a glance. */
.kpi-trend-total-bar {
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: var(--p, 0%);
  border-radius: 0 6px 6px 0;
  background: linear-gradient(90deg, rgba(96,165,250,0.34), rgba(34,211,238,0.20));
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.10);
  pointer-events: none;
  z-index: 0;
}
.kpi-trend-total-val { position: relative; z-index: 1; }

.kpi-trend-chart-empty {
  display: grid;
  place-items: center;
  min-height: 300px;
  color: rgba(203,213,225,0.5);
  font-size: 13px;
  font-weight: 800;
}

@media (max-width: 880px) {
  .kpi-trend-head { flex-direction: column; }
