/* ── light theme ─────────────────────────────────────────────────────────── */






















































/* KPI scroll-triggered reveal and chart/table polish. */
@keyframes kpiRevealUp {
  from { opacity: 0; transform: translateY(14px) scale(0.985); filter: blur(5px); }
  to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}

@keyframes kpiRevealChip {
  from { opacity: 0; transform: translateY(8px) scale(0.94); filter: saturate(0.7); }
  to { opacity: 1; transform: translateY(0) scale(1); filter: saturate(1); }
}

@keyframes kpiTrackingCardOpen {
  0%   { opacity: 0; transform: translateY(24px) scale(0.84); filter: blur(8px) saturate(0.66); }
  52%  { opacity: 1; }
  72%  { transform: translateY(-3px) scale(1.035); filter: blur(0) saturate(1.05); }
  100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0) saturate(1); }
}

.kpi-trend-section.kpi-reveal-pending .kpi-trend-head,
.kpi-trend-section.kpi-reveal-pending .kpi-trend-range,
.kpi-trend-section.kpi-reveal-pending .kpi-trend-filter-head,
.kpi-trend-section.kpi-reveal-pending .kpi-trend-search,
.kpi-trend-section.kpi-reveal-pending .kpi-trend-chip {
  opacity: 0;
}

.kpi-trend-section.kpi-reveal-pending,
.kpi-tracking-section.kpi-reveal-pending {
  animation: none !important;
}

.kpi-trend-section.is-opening .kpi-trend-head {
  animation: kpiRevealUp 0.46s cubic-bezier(0.22, 1, 0.36, 1) 0.02s both;
}

.kpi-trend-section.is-opening .kpi-trend-range {
  animation: kpiRevealUp 0.46s cubic-bezier(0.22, 1, 0.36, 1) 0.08s both;
}

.kpi-trend-section.is-opening .kpi-trend-filter-head,
.kpi-trend-section.is-opening .kpi-trend-search {
  animation: kpiRevealUp 0.42s cubic-bezier(0.22, 1, 0.36, 1) 0.14s both;
}

.kpi-trend-section.is-opening .kpi-trend-chip {
  animation: kpiRevealChip 0.38s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(1) { animation-delay: 0.18s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(2) { animation-delay: 0.21s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(3) { animation-delay: 0.24s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(4) { animation-delay: 0.27s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(5) { animation-delay: 0.30s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(6) { animation-delay: 0.33s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(7) { animation-delay: 0.36s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(8) { animation-delay: 0.39s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(9) { animation-delay: 0.42s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(10) { animation-delay: 0.45s; }
.kpi-trend-section.is-opening .kpi-trend-chip:nth-child(n+11) { animation-delay: 0.48s; }

.kpi-trend-data-table tbody tr:last-child th,
