/* ════════════════════════════════════════════════════════════════════════════
   KPI page — "Napszak bontás" (daypart distribution) section
   Inbound (felvétel) vs outbound (kiadás), 4-hour bands of the day.
   Rendered client-side by assets/kpi_bands.js. No color-mix() (renderer-safe).
   ════════════════════════════════════════════════════════════════════════════ */
.kpi-bands-section {
  --band-in: #60a5fa;
  --band-in-rgb: 96,165,250;
  --band-out: #fbbf24;
  --band-out-rgb: 251,191,36;
  position: relative;
  margin-top: 16px;
  padding: 16px 18px 18px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.09);
  background: rgba(8, 15, 30, 0.34);
  box-shadow:
    0 14px 36px rgba(0,0,0,0.18),
    inset 0 1px 0 rgba(255,255,255,0.08);
  backdrop-filter: blur(7px) saturate(125%);
  -webkit-backdrop-filter: blur(7px) saturate(125%);
  content-visibility: auto;
  contain-intrinsic-size: 0 520px;
}
/* Entrance is CSS-driven (tied to the KPI view class) so the section is NEVER
   gated on JS — if a script error stopped the renderer, the frame still shows. */
body.view-kpi-mode .kpi-bands-section {
  animation: kpiPageIn 0.5s cubic-bezier(0.22, 1, 0.36, 1) 0.34s both;
}

/* ── header + controls ─────────────────────────────────────────────────────── */
.kpi-bands-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}
.kpi-bands-eyebrow {
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(148,163,184,0.85);
}
.kpi-bands-title {
  margin: 2px 0 3px;
  font-size: 19px;
  font-weight: 900;
  letter-spacing: 0.01em;
  color: #f1f5f9;
}
.kpi-bands-subtitle {
  font-size: 12px;
  color: rgba(148,163,184,0.92);
}
.kpi-bands-controls {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.kpi-bands-toggle {
  display: inline-flex;
  padding: 3px;
  border-radius: 10px;
  background: rgba(2, 8, 20, 0.5);
  border: 1px solid rgba(255,255,255,0.08);
  gap: 2px;
}
.kpi-bands-tg-btn {
  border: 0;
  background: transparent;
  color: rgba(203,213,225,0.78);
  font-size: 12px;
  font-weight: 800;
  padding: 5px 12px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.16s ease, color 0.16s ease;
}
.kpi-bands-tg-btn:hover { color: #e2e8f0; }
.kpi-bands-tg-btn.is-active {
  background: linear-gradient(180deg, rgba(96,165,250,0.30), rgba(96,165,250,0.16));
  color: #fff;
  box-shadow: inset 0 0 0 1px rgba(125,211,252,0.35);
}

/* ── summary chips ─────────────────────────────────────────────────────────── */
.kpi-bands-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 14px;
}
.kpi-bands-chip {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 130px;
  padding: 9px 13px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.08);
  background: rgba(255,255,255,0.035);
}
.kpi-bands-chip span {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: rgba(148,163,184,0.9);
}
.kpi-bands-chip b { font-size: 17px; font-weight: 900; color: #f1f5f9; }
.kpi-bands-chip.in  { border-color: rgba(var(--band-in-rgb),0.4);  background: rgba(var(--band-in-rgb),0.10); }
.kpi-bands-chip.in b  { color: var(--band-in); }
.kpi-bands-chip.out { border-color: rgba(var(--band-out-rgb),0.4); background: rgba(var(--band-out-rgb),0.10); }
.kpi-bands-chip.out b { color: var(--band-out); }
.kpi-bands-chip.net.pos b { color: #34d399; }
.kpi-bands-chip.net.neg b { color: #fb7185; }
.kpi-bands-chip.peak b { color: #c4b5fd; font-size: 14px; }

/* ── grouped bar chart ─────────────────────────────────────────────────────── */
.kpi-bands-chart { margin-bottom: 16px; }
.kpi-bands-chart-inner {
  border-radius: 12px;
  padding: 16px 14px 10px;
  background: linear-gradient(180deg, rgba(255,255,255,0.025), rgba(255,255,255,0));
  border: 1px solid rgba(255,255,255,0.06);
}
.kpi-bands-cols {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  height: 210px;
}
.kpi-bands-col {
  position: relative;
  flex: 1 1 0;
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: 9px;
  transition: background 0.16s ease;
}
.kpi-bands-col:hover { background: rgba(255,255,255,0.03); }
.kpi-bands-col.is-current {
  background: rgba(var(--band-in-rgb),0.07);
  box-shadow: inset 0 0 0 1px rgba(var(--band-in-rgb),0.28);
}
.kpi-bands-col.is-future { opacity: 0.5; }
.kpi-bands-bars {
  flex: 1 1 auto;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 9px;
  padding: 0 4px;
  min-height: 0;
}
.kpi-bands-bar {
  position: relative;
  width: 100%;
  max-width: 40px;
  min-height: 2px;
  border-radius: 7px 7px 3px 3px;
  transition: height 0.7s cubic-bezier(0.22, 1, 0.36, 1), filter 0.16s ease;
}
.kpi-bands-bar.inbound {
  background: linear-gradient(180deg, var(--band-in), rgba(var(--band-in-rgb),0.55));
  box-shadow: 0 0 14px rgba(var(--band-in-rgb),0.30), inset 0 1px 0 rgba(255,255,255,0.4);
}
.kpi-bands-bar.outbound {
  background: linear-gradient(180deg, var(--band-out), rgba(var(--band-out-rgb),0.55));
  box-shadow: 0 0 14px rgba(var(--band-out-rgb),0.28), inset 0 1px 0 rgba(255,255,255,0.45);
}
.kpi-bands-col:hover .kpi-bands-bar { filter: brightness(1.12); }
.kpi-bands-barval {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  margin-bottom: 4px;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
  color: #e2e8f0;
}
.kpi-bands-col-label {
  flex: 0 0 auto;
  margin-top: 8px;
  text-align: center;
  font-size: 12px;
  font-weight: 800;
  color: rgba(203,213,225,0.85);
}
.kpi-bands-col-now {
  display: block;
  margin-top: 1px;
  font-size: 9px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--band-in);
}
.kpi-bands-legend {
