@media (max-width: 980px) {
  .kpi-bands-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 560px) {
  .kpi-bands-grid { grid-template-columns: minmax(0, 1fr); }
  .kpi-bands-cols { height: 170px; }
}
@media (prefers-reduced-motion: reduce) {
  body.view-kpi-mode .kpi-bands-section { animation: none; }
  .kpi-bands-bar, .kpi-bands-row-bar > i { transition: none; }
}

/* KPI time bands redesign - unified with the operational dashboard surface.
   This later block intentionally overrides the first implementation above. */
.kpi-bands-section {
  --band-in: #ff8a3d;
  --band-in-rgb: 255,138,61;
  --band-out: #a78bfa;
  --band-out-rgb: 167,139,250;
  position: relative;
  isolation: isolate;
  margin-top: 18px;
  padding: 18px;
  overflow: hidden;
  border-radius: 14px;
  border: 1px solid rgba(170, 186, 216, 0.18);
  background:
    radial-gradient(90% 120% at 6% 0%, rgba(var(--band-in-rgb), 0.13), transparent 58%),
    radial-gradient(80% 110% at 96% 6%, rgba(var(--band-out-rgb), 0.16), transparent 56%),
    linear-gradient(180deg, rgba(19, 30, 54, 0.88), rgba(12, 20, 39, 0.80)),
    rgba(12, 19, 34, 0.86);
  box-shadow:
    0 16px 40px rgba(3, 8, 20, 0.26),
    inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(8px) saturate(118%);
  -webkit-backdrop-filter: blur(8px) saturate(118%);
  content-visibility: auto;
  contain-intrinsic-size: 0 560px;
  animation: none !important;
}

.kpi-bands-section::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image:
    linear-gradient(rgba(157, 187, 234, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(157, 187, 234, 0.045) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.75), transparent 82%);
  pointer-events: none;
}

.kpi-bands-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  flex-wrap: wrap;
