  border: 1px solid rgba(125, 150, 198, 0.24); padding: 5px 12px; border-radius: 999px;
  color: rgba(196, 209, 233, 0.86); background: rgba(12, 20, 38, 0.5);
  font-size: 11px; font-weight: 760; cursor: pointer;
  transition: color 0.18s ease, background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}
.kpi-temu-chip:hover { color: #eaf0fc; border-color: rgba(var(--temu-accent-rgb), 0.4); transform: translateY(-1px); }
.kpi-temu-chip.is-active {
  color: #1a1205; border-color: transparent;
  background: linear-gradient(135deg, rgba(var(--temu-accent-rgb), 0.92), rgba(255, 198, 110, 0.86));
}

/* inspected-period range row */
.kpi-temu-range { margin-bottom: 12px; }
.kpi-temu-range-label {
  margin-bottom: 6px; color: rgba(166, 183, 214, 0.62);
  font-size: 9.5px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase;
}
.kpi-temu-range-row { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.kpi-temu-presets { display: inline-flex; gap: 5px; flex-wrap: wrap; }
.kpi-temu-preset {
  border: 1px solid rgba(125, 150, 198, 0.22); padding: 4px 11px; border-radius: 8px;
  color: rgba(196, 209, 233, 0.82); background: rgba(12, 20, 38, 0.45);
  font-size: 10.5px; font-weight: 760; cursor: pointer;
  transition: color 0.16s ease, background 0.16s ease, border-color 0.16s ease;
}
.kpi-temu-preset:hover { color: #eaf0fc; border-color: rgba(var(--temu-accent-rgb), 0.4); }
.kpi-temu-preset.is-active { color: #f8fbff; border-color: rgba(var(--temu-accent-rgb), 0.55); background: rgba(var(--temu-accent-rgb), 0.16); }
.kpi-temu-range-active {
  display: inline-flex; align-items: center; gap: 8px; margin-left: auto;
  color: rgba(190, 203, 227, 0.7); font-size: 11px; font-weight: 700; font-variant-numeric: tabular-nums;
}
.kpi-temu-range-active.is-zoomed { color: #ffd79a; }
.kpi-temu-range-reset {
  border: 1px solid rgba(var(--temu-accent-rgb), 0.4); padding: 3px 9px; border-radius: 7px;
  color: #ffd79a; background: rgba(var(--temu-accent-rgb), 0.12); font-size: 10px; font-weight: 800; cursor: pointer;
}
.kpi-temu-range-reset:hover { background: rgba(var(--temu-accent-rgb), 0.2); }
.kpi-temu-range-hint { margin-top: 6px; color: rgba(150, 167, 198, 0.5); font-size: 10px; font-weight: 600; font-style: italic; }

/* summary stat chips */
.kpi-temu-summary { display: flex; flex-direction: column; gap: 10px; margin-bottom: 14px; }
.kpi-temu-headline { display: flex; flex-wrap: wrap; align-items: stretch; gap: 10px; }
.kpi-temu-headline-main {
  position: relative; display: flex; flex-direction: column; gap: 2px;
  flex: 1 1 260px; min-width: 240px; padding: 12px 16px; border-radius: 12px;
  border: 1px solid rgba(var(--temu-accent-rgb), 0.28);
  background:
    radial-gradient(120% 140% at 0% 0%, rgba(var(--temu-accent-rgb), 0.14), transparent 60%),
    linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.012)),
    rgba(10, 17, 32, 0.5);
}
.kpi-temu-headline-label { color: rgba(178, 193, 219, 0.78); font-size: 10px; font-weight: 820; letter-spacing: 0.08em; text-transform: uppercase; }
.kpi-temu-headline-val { color: #fff; font-size: 30px; font-weight: 950; line-height: 1.05; font-variant-numeric: tabular-nums; }
.kpi-temu-headline-unit { color: rgba(178, 193, 219, 0.66); font-size: 10.5px; font-weight: 700; }
.kpi-temu-delta { display: inline-flex; align-items: center; gap: 5px; margin-top: 5px; font-size: 12px; font-weight: 850; font-style: normal; font-variant-numeric: tabular-nums; }
.kpi-temu-delta i { font-size: 9px; }
.kpi-temu-delta small { color: rgba(178,193,219,0.6); font-weight: 700; }
.kpi-temu-delta.is-good { color: #5fe0a0; }
.kpi-temu-delta.is-bad { color: #ff8a8a; }
.kpi-temu-delta.is-flat { color: rgba(190,203,227,0.7); }
.kpi-temu-delta.is-none { color: rgba(150,167,198,0.5); }
.kpi-temu-headline-peaks { display: flex; gap: 10px; flex: 1 1 280px; }
.kpi-temu-chip-card {
  display: flex; flex-direction: column; gap: 3px; flex: 1 1 0; min-width: 120px;
  padding: 11px 13px; border-radius: 11px;
  border: 1px solid rgba(125, 150, 198, 0.2);
  background: linear-gradient(180deg, rgba(255,255,255,0.035), rgba(255,255,255,0.01)), rgba(10, 17, 32, 0.45);
}
.kpi-temu-chip-card span { color: rgba(178, 193, 219, 0.72); font-size: 9.5px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; }
.kpi-temu-chip-card.is-fast { border-color: rgba(95, 224, 160, 0.3); }
.kpi-temu-chip-card.is-slow { border-color: rgba(255, 138, 138, 0.3); }
.kpi-temu-chip-badge { color: #eef3fb; font-size: 14px; font-weight: 880; }
.kpi-temu-chip-val { color: rgba(212, 223, 243, 0.92); font-size: 12px; font-weight: 800; font-variant-numeric: tabular-nums; }
.kpi-temu-chip-val small { color: rgba(178,193,219,0.6); font-weight: 700; }
.kpi-temu-stage-chips { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; }
.kpi-temu-stage-chip {
  display: flex; flex-direction: column; gap: 2px; padding: 9px 11px 9px 13px;
  border-radius: 10px; position: relative; overflow: hidden;
  border: 1px solid rgba(125, 150, 198, 0.18);
  background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.008)), rgba(9, 16, 31, 0.5);
}
.kpi-temu-stage-chip > i {
  position: absolute; left: 0; top: 0; bottom: 0; width: 4px;
  background: rgb(var(--seg-rgb)); box-shadow: 0 0 12px rgba(var(--seg-rgb), 0.5);
}
.kpi-temu-stage-chip span { color: rgba(196, 209, 233, 0.82); font-size: 10px; font-weight: 740; line-height: 1.2; }
.kpi-temu-stage-chip b { color: #f4f8ff; font-size: 16px; font-weight: 920; font-variant-numeric: tabular-nums; }

/* chart */
.kpi-temu-chart-shell { position: relative; display: flex; flex-direction: column; gap: 12px; }
.kpi-temu-chart-inner {
  position: relative; display: flex; gap: 10px; padding: 14px 14px 6px;
  border: 1px solid rgba(135, 160, 201, 0.17); border-radius: 12px;
  background: linear-gradient(180deg, rgba(255,255,255,0.035), rgba(255,255,255,0.010)), rgba(7, 13, 25, 0.46);
}
.kpi-temu-yaxis {
  display: flex; flex-direction: column; justify-content: space-between;
  width: 44px; height: 300px; padding: 22px 0 34px; text-align: right; flex: 0 0 auto;
}
.kpi-temu-section.metric-count .kpi-temu-yaxis { padding-top: 6px; }
.kpi-temu-tick { color: rgba(166, 183, 214, 0.6); font-size: 10px; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1; }
.kpi-temu-plot { position: relative; flex: 1 1 auto; min-width: 0; }
.kpi-temu-gridlines { position: absolute; left: 0; right: 0; top: 22px; bottom: 34px; z-index: 0; pointer-events: none; }
.kpi-temu-section.metric-count .kpi-temu-gridlines { top: 6px; }
.kpi-temu-gridline { position: absolute; left: 0; right: 0; height: 1px; background: rgba(147, 171, 214, 0.08); }
.kpi-temu-cols { position: relative; z-index: 1; display: flex; align-items: stretch; gap: 8px; height: 300px; overflow-x: auto; touch-action: pan-y; }
.kpi-temu-col {
  position: relative; display: flex; flex-direction: column; justify-content: flex-end;
  flex: 1 1 0; min-width: 44px; height: 100%; padding: 0 2px; border: 0; border-radius: 10px;
  background: transparent; color: inherit; cursor: pointer; user-select: none;
  transition: transform 0.2s cubic-bezier(0.22,1,0.36,1), background 0.2s ease, opacity 0.2s ease;
}
.kpi-temu-col:hover { transform: translateY(-2px); background: rgba(255,255,255,0.04); }
.kpi-temu-col.is-selected { background: rgba(var(--temu-accent-rgb), 0.12); box-shadow: inset 0 0 0 1px rgba(var(--temu-accent-rgb), 0.4); }
.kpi-temu-col.is-muted { opacity: 0.4; }
.kpi-temu-col.in-brush { background: rgba(var(--temu-accent-rgb), 0.16); }
.kpi-temu-col-total { height: 18px; margin-bottom: 4px; color: #f6f9ff; font-size: 12px; font-weight: 950; font-variant-numeric: tabular-nums; text-align: center; text-shadow: 0 1px 6px rgba(0,0,0,0.4); }
.kpi-temu-bar-track { flex: 1 1 auto; display: flex; align-items: flex-end; min-height: 0; width: 100%; }
.kpi-temu-bar {
  display: flex; flex-direction: column-reverse; width: 100%; border-radius: 5px 5px 3px 3px; overflow: hidden;
  box-shadow: 0 4px 14px rgba(0,0,0,0.3); transition: height 0.7s cubic-bezier(0.22,1,0.36,1);
}
.kpi-temu-bar.is-count {
  align-items: center; justify-content: flex-start; flex-direction: column;
  background: linear-gradient(180deg, rgba(var(--temu-accent-rgb), 1), rgba(255, 196, 110, 0.85));
}
.kpi-temu-count-val { margin-top: 4px; color: #1a1205; font-size: 11px; font-weight: 900; font-variant-numeric: tabular-nums; }
.kpi-temu-seg {
  display: flex; align-items: center; justify-content: center; min-height: 0; width: 100%;
  background: rgb(var(--seg-rgb, 148,163,184));
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.16), inset 0 -1px 0 rgba(0,0,0,0.14); overflow: hidden;
}
.kpi-temu-seg b { font-size: 10px; font-weight: 850; font-variant-numeric: tabular-nums; color: #14110a; text-shadow: 0 1px 1px rgba(255,255,255,0.18); white-space: nowrap; }
.kpi-temu-seg.seg-outbound b, .kpi-temu-seg.seg-customs b, .kpi-temu-seg.seg-ata_noa b { color: #fbfdff; text-shadow: 0 1px 2px rgba(0,0,0,0.45); }
.kpi-temu-col-label { margin-top: 7px; height: 32px; display: flex; flex-direction: column; align-items: center; color: rgba(226,232,240,0.9); font-size: 11px; font-weight: 760; font-variant-numeric: tabular-nums; }
.kpi-temu-col-count { margin-top: 1px; color: rgba(166,183,214,0.55); font-size: 9px; font-style: normal; font-weight: 700; }

/* hover tooltip */
.kpi-temu-tooltip {
  position: absolute; bottom: calc(100% - 14px); left: 50%; transform: translate(-50%, 6px);
  z-index: 8; min-width: 188px; padding: 9px 11px; border-radius: 10px; pointer-events: none;
  border: 1px solid rgba(135, 160, 201, 0.3);
  background: linear-gradient(180deg, rgba(22, 33, 56, 0.98), rgba(13, 22, 41, 0.98));
  box-shadow: 0 14px 34px rgba(0,0,0,0.5);
  opacity: 0; visibility: hidden; transition: opacity 0.16s ease, transform 0.16s ease;
}
.kpi-temu-tooltip.is-on { opacity: 1; visibility: visible; transform: translate(-50%, 0); }
.kpi-temu-tt-head { margin-bottom: 6px; color: #f4f8ff; font-size: 11px; font-weight: 880; }
.kpi-temu-tt-row { display: flex; align-items: center; gap: 6px; padding: 1px 0; font-size: 10.5px; }
.kpi-temu-tt-row i { width: 9px; height: 9px; border-radius: 3px; background: rgb(var(--seg-rgb)); flex: 0 0 auto; }
.kpi-temu-tt-row span { flex: 1 1 auto; color: rgba(196, 209, 233, 0.82); }
.kpi-temu-tt-row b { color: #eef3fb; font-weight: 820; font-variant-numeric: tabular-nums; }
.kpi-temu-tt-total { display: flex; justify-content: space-between; margin-top: 6px; padding-top: 5px; border-top: 1px solid rgba(135,160,201,0.2); font-size: 11px; }
.kpi-temu-tt-total span { color: rgba(178,193,219,0.7); font-weight: 700; }
.kpi-temu-tt-total b { color: #ffd79a; font-weight: 900; font-variant-numeric: tabular-nums; }

/* detail panel */
.kpi-temu-detail {
  max-height: 0; overflow: hidden; opacity: 0; transform: translateY(-6px);
  transition: max-height 0.4s cubic-bezier(0.22,1,0.36,1), opacity 0.3s ease, transform 0.3s ease, padding 0.3s ease, margin 0.3s ease;
  border-radius: 12px; padding: 0 16px; border: 1px solid transparent;
}
.kpi-temu-detail.is-open {
  max-height: 420px; opacity: 1; transform: none; padding: 14px 16px;
  border-color: rgba(var(--temu-accent-rgb), 0.28);
  background: linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.012)), rgba(10, 17, 32, 0.5);
}
.kpi-temu-detail-head { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 10px; }
.kpi-temu-detail-head b { display: block; color: #f4f8ff; font-size: 14px; font-weight: 880; }
.kpi-temu-detail-head span { color: rgba(178, 193, 219, 0.7); font-size: 11px; font-weight: 700; }
.kpi-temu-detail-close { border: 0; width: 26px; height: 26px; border-radius: 8px; color: rgba(196,209,233,0.8); background: rgba(255,255,255,0.06); cursor: pointer; font-size: 12px; }
.kpi-temu-detail-close:hover { color: #fff; background: rgba(255,255,255,0.12); }
.kpi-temu-detail-rows { display: flex; flex-direction: column; gap: 7px; }
.kpi-temu-detail-row { display: grid; grid-template-columns: 1.6fr 3fr auto auto; align-items: center; gap: 10px; }
.kpi-temu-detail-name { display: inline-flex; align-items: center; gap: 7px; color: rgba(206, 217, 238, 0.9); font-size: 11.5px; font-weight: 740; }
.kpi-temu-detail-name i { width: 11px; height: 11px; border-radius: 3px; background: rgb(var(--seg-rgb)); flex: 0 0 auto; }
.kpi-temu-detail-bar { height: 10px; border-radius: 999px; background: rgba(255,255,255,0.06); overflow: hidden; }
.kpi-temu-detail-bar > b { display: block; height: 100%; width: 0; border-radius: 999px; background: rgb(var(--seg-rgb)); transition: width 0.6s cubic-bezier(0.22,1,0.36,1); }
.kpi-temu-detail-val { color: #f4f8ff; font-size: 12px; font-weight: 850; font-variant-numeric: tabular-nums; text-align: right; min-width: 44px; }
.kpi-temu-detail-pct { color: rgba(178,193,219,0.62); font-size: 11px; font-weight: 740; text-align: right; min-width: 34px; }
.kpi-temu-detail-total { display: flex; justify-content: space-between; align-items: center; margin-top: 11px; padding-top: 9px; border-top: 1px solid rgba(135,160,201,0.2); }
.kpi-temu-detail-total span { color: rgba(178,193,219,0.75); font-size: 11px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; }
.kpi-temu-detail-total b { color: #ffd79a; font-size: 18px; font-weight: 950; font-variant-numeric: tabular-nums; }

/* legend */
.kpi-temu-legend { display: flex; flex-wrap: wrap; gap: 14px; padding: 2px 2px 0; }
.kpi-temu-leg { display: inline-flex; align-items: center; gap: 6px; color: rgba(206,217,238,0.86); font-size: 11px; font-weight: 740; }
.kpi-temu-leg i { width: 12px; height: 12px; border-radius: 3px; box-shadow: inset 0 1px 0 rgba(255,255,255,0.2); }

.kpi-temu-empty { display: flex; align-items: center; justify-content: center; width: 100%; min-height: 200px; color: rgba(166,183,214,0.6); font-size: 13px; font-weight: 700; }

/* data table */
.kpi-temu-table-panel { margin-top: 14px; }
.kpi-temu-table-drawer { border: 1px solid rgba(135, 160, 201, 0.18); border-radius: 12px; overflow: hidden; background: rgba(9, 16, 31, 0.5); }
.kpi-temu-table-toggle {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 11px 14px; border: 0;
  color: #e8eefb; background: linear-gradient(180deg, rgba(255,255,255,0.035), rgba(255,255,255,0.01)); cursor: pointer; text-align: left;
}
.kpi-temu-table-chevron { display: inline-block; color: rgba(var(--temu-accent-rgb), 0.95); font-size: 12px; transition: transform 0.25s ease; }
.kpi-temu-table-drawer.is-open .kpi-temu-table-chevron { transform: rotate(90deg); }
.kpi-temu-table-title { font-size: 12.5px; font-weight: 860; }
.kpi-temu-table-sub { color: rgba(178, 193, 219, 0.66); font-size: 10.5px; font-weight: 700; }
.kpi-temu-table-actions { margin-left: auto; }
.kpi-temu-export {
  border: 1px solid rgba(var(--temu-accent-rgb), 0.45); padding: 5px 12px; border-radius: 8px;
  color: #ffd79a; background: rgba(var(--temu-accent-rgb), 0.12); font-size: 10.5px; font-weight: 820; cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease;
}
.kpi-temu-export:hover { background: rgba(var(--temu-accent-rgb), 0.22); }
.kpi-temu-export.is-loading { opacity: 0.7; cursor: progress; }
.kpi-temu-export.is-done { color: #5fe0a0; border-color: rgba(95,224,160,0.5); background: rgba(95,224,160,0.14); }
.kpi-temu-export.is-error { color: #ff8a8a; border-color: rgba(255,138,138,0.5); background: rgba(255,138,138,0.14); }
.kpi-temu-table-wrap { max-height: 420px; overflow: auto; transition: max-height 0.35s ease; }
.kpi-temu-table-wrap.is-collapsed { max-height: 0; overflow: hidden; }
.kpi-temu-table { width: 100%; border-collapse: collapse; font-size: 11.5px; font-variant-numeric: tabular-nums; }
.kpi-temu-table thead th {
  position: sticky; top: 0; z-index: 2; padding: 9px 8px; text-align: center; white-space: nowrap;
  color: #dbe6f7; font-size: 10px; font-weight: 820; background: #16233f;
  border-bottom: 1px solid rgba(135,160,201,0.25);
}
.kpi-temu-table thead th.kpi-temu-th-period { text-align: left; }
.kpi-temu-th-stage { position: relative; }
.kpi-temu-th-dot { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 5px; vertical-align: middle; background: rgb(var(--seg-rgb)); }
.kpi-temu-table tbody th { padding: 7px 8px; text-align: left; color: #eef3fb; font-weight: 780; white-space: nowrap; }
.kpi-temu-td-date { display: block; color: rgba(166,183,214,0.55); font-size: 9px; font-weight: 600; }
.kpi-temu-table td { padding: 7px 8px; text-align: center; color: rgba(212, 223, 243, 0.9); }
.kpi-temu-table td.total { color: #ffd79a; font-weight: 850; }
.kpi-temu-table td.pcs { color: rgba(178,193,219,0.75); }
.kpi-temu-trow { cursor: pointer; transition: background 0.15s ease; }
.kpi-temu-trow:hover { background: rgba(255,255,255,0.035); }
.kpi-temu-trow.is-selected { background: rgba(var(--temu-accent-rgb), 0.12); }
.kpi-temu-table tbody tr { border-bottom: 1px solid rgba(135,160,201,0.08); }
.kpi-temu-table tfoot th, .kpi-temu-table tfoot td {
  position: sticky; bottom: 0; z-index: 2; padding: 8px; background: #1a2842;
  color: #f4f8ff; font-weight: 880; border-top: 1px solid rgba(135,160,201,0.3); text-align: center;
}
.kpi-temu-table tfoot th { text-align: left; }

/* Flagged records — TEMU rows with unreliable milestone dates (data-entry warnings).
   Excluded from the averages, surfaced here so they can be fixed at source. Static
   (no idle animation); warm "alert" accent distinct from the cool data table. */
.kpi-temu-suspects-panel { margin-top: 12px; }
.kpi-temu-flag-drawer {
  border: 1px solid rgba(245, 170, 90, 0.30); border-radius: 12px; overflow: hidden;
  background: linear-gradient(180deg, rgba(42, 28, 12, 0.42), rgba(11, 16, 28, 0.5));
}
.kpi-temu-flag-bar {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 11px 14px; border: 0; cursor: pointer; text-align: left;
  color: #f4ead9; background: linear-gradient(180deg, rgba(255, 186, 92, 0.10), rgba(255,255,255,0.01));
}
.kpi-temu-flag-bar:hover { background: linear-gradient(180deg, rgba(255, 186, 92, 0.16), rgba(255,255,255,0.02)); }
.kpi-temu-flag-warn { font-size: 14px; line-height: 1; color: #ffb454; filter: drop-shadow(0 0 6px rgba(255,160,60,0.4)); }
.kpi-temu-flag-title { font-size: 12.5px; font-weight: 860; letter-spacing: 0.01em; }
.kpi-temu-flag-count {
  min-width: 20px; text-align: center; padding: 1px 7px; border-radius: 999px; font-size: 11px; font-weight: 880;
  color: #20160a; background: #ffb454; box-shadow: 0 2px 8px rgba(255,160,60,0.3);
}
.kpi-temu-flag-sub { color: rgba(210, 196, 172, 0.6); font-size: 10.5px; font-weight: 700; }
.kpi-temu-flag-chev { margin-left: auto; color: rgba(255, 186, 92, 0.9); font-size: 12px; transition: transform 0.25s ease; }
.kpi-temu-flag-drawer.is-open .kpi-temu-flag-chev { transform: rotate(90deg); }
.kpi-temu-flag-wrap { max-height: 460px; overflow: auto; transition: max-height 0.35s ease; }
.kpi-temu-flag-wrap.is-collapsed { max-height: 0; overflow: hidden; }
.kpi-temu-flag-group { border-top: 1px solid rgba(135,160,201,0.10); }
.kpi-temu-flag-day {
  position: sticky; top: 0; z-index: 1; display: flex; align-items: center; gap: 8px; padding: 6px 14px;
  background: rgba(22, 30, 49, 0.92); color: #cdd9ee; font-size: 10.5px; font-weight: 820; letter-spacing: 0.02em;
  border-bottom: 1px solid rgba(135,160,201,0.10);
}
.kpi-temu-flag-day i { font-style: normal; color: rgba(178,193,219,0.6); font-weight: 760; }
.kpi-temu-flag-day i::before { content: "· "; }
.kpi-temu-flag-row {
