@keyframes kpiTemuRing { from { transform: translate(-50%, -50%) rotate(0deg); } to { transform: translate(-50%, -50%) rotate(360deg); } }
@keyframes kpiTemuSheen { 0% { background-position: 0% 50%; } 100% { background-position: 100% 50%; } }
@keyframes kpiTemuCardIn { 0% { opacity: 0; transform: translateY(16px) scale(0.975); } 100% { opacity: 1; transform: none; } }

/* Card shell: transparent, centred, clipped; ring + fill live on the pseudos. */
.kpi-temu-headline-main,
.kpi-temu-peak,
.kpi-temu-stage-card {
  position: relative; z-index: 0; isolation: isolate; overflow: hidden;
  border: 0 !important; border-radius: 16px; background: transparent !important;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; gap: 3px; animation: none;
  box-shadow: 0 12px 26px rgba(0,0,0,0.26);
