.kpi-temu-stage-card { --card-rgb: var(--seg-rgb, 148,163,184); min-height: 96px; padding: 11px 10px; cursor: pointer; }

/* Rotating conic ring (transform-driven → works in the portable renderer). */
.kpi-temu-headline-main::before,
.kpi-temu-peak::before,
.kpi-temu-stage-card::before {
  content: ""; position: absolute; z-index: -2; inset: auto; left: 50%; top: 50%;
  width: 320%; height: 320%; border-radius: 0; opacity: 0.95; pointer-events: none;
  background: conic-gradient(
    rgba(var(--card-rgb), 0.30), rgba(var(--card-rgb), 0.95), rgba(255,255,255,0.7),
    rgba(124,196,255, 0.85), rgba(var(--card-rgb), 0.30));
  transform: translate(-50%, -50%) rotate(0deg);
  animation: kpiTemuRing 9s linear infinite;
}
.kpi-temu-peak::before { animation-duration: 11s; }
.kpi-temu-peak.is-slow::before { animation-duration: 12.5s; }
.kpi-temu-stage-card:nth-child(1)::before { animation-duration: 9.5s; }
.kpi-temu-stage-card:nth-child(2)::before { animation-duration: 10.5s; }
.kpi-temu-stage-card:nth-child(3)::before { animation-duration: 11.5s; }
.kpi-temu-stage-card:nth-child(4)::before { animation-duration: 12.5s; }
.kpi-temu-stage-card:nth-child(5)::before { animation-duration: 13.5s; }

/* Inner fill + drifting multi-hue gradient (the credit-card look). */
.kpi-temu-headline-main::after,
.kpi-temu-peak::after,
.kpi-temu-stage-card::after {
