  background:
    radial-gradient(120% 90% at 14% 10%, rgba(255,255,255,0.14), transparent 46%),
    linear-gradient(125deg,
      rgba(var(--card-rgb), 0.52) 0%,
      rgba(10,15,28, 0.92) 30%,
      rgba(124,196,255, 0.18) 52%,
      rgba(10,15,28, 0.92) 74%,
