/* Opening animation (staggered) — replays only on the section reveal / view swap. */
.kpi-temu-section.is-opening .kpi-temu-headline-main { animation: kpiTemuCardIn 0.55s cubic-bezier(0.22,1,0.36,1) both; }
.kpi-temu-section.is-opening .kpi-temu-peak.is-fast { animation: kpiTemuCardIn 0.55s cubic-bezier(0.22,1,0.36,1) 0.07s both; }
.kpi-temu-section.is-opening .kpi-temu-peak.is-slow { animation: kpiTemuCardIn 0.55s cubic-bezier(0.22,1,0.36,1) 0.13s both; }
