.kpi-temu-section.is-opening .kpi-temu-stage-card:nth-child(3) { animation: kpiTemuCardIn 0.5s cubic-bezier(0.22,1,0.36,1) 0.30s both; }
.kpi-temu-section.is-opening .kpi-temu-stage-card:nth-child(4) { animation: kpiTemuCardIn 0.5s cubic-bezier(0.22,1,0.36,1) 0.36s both; }
.kpi-temu-section.is-opening .kpi-temu-stage-card:nth-child(5) { animation: kpiTemuCardIn 0.5s cubic-bezier(0.22,1,0.36,1) 0.42s both; }

@media (prefers-reduced-motion: reduce) {
  .kpi-temu-headline-main::before, .kpi-temu-peak::before, .kpi-temu-stage-card::before,
