.kpi-temu-stage-card-share { font-size: 10px; }

/* ── Inspected-period chips (Volume-trend look) ─────────────────────────────── */
.kpi-temu-range-row { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.kpi-temu-rchips { display: inline-flex; flex-wrap: wrap; gap: 6px; }
.kpi-temu-rchip {
