/* ───────────────────────────────────────────────────────────────────────────
   TEMU KPI v8 (2026-06-19) — use the EXACT Operational-time-bands card border on
   the TEMU cards (gradient border-box + the proven @property --kpi-band-border-angle
   ring via kpiBandBorderSpin), staggered; a slight radial "circle" gradient inside;
   glow on the selected card; smooth data-table open/close. The v6/v7 ring pseudos
   are disabled (they didn't render in the portable renderer).
   ─────────────────────────────────────────────────────────────────────────── */

/* Kill the earlier pseudo-based ring/fill — the border now lives on the element
   background exactly like the bands cards. */
.kpi-temu-headline-main::before, .kpi-temu-headline-main::after,
.kpi-temu-peak::before, .kpi-temu-peak::after,
.kpi-temu-stage-card::before, .kpi-temu-stage-card::after {
  display: none !important; content: none !important; animation: none !important;
}

/* Bands-style animated gradient border + slight radial circle gradient interior. */
.kpi-temu-headline-main,
.kpi-temu-peak,
.kpi-temu-stage-card {
  position: relative; z-index: 0; overflow: hidden;
  border: 1px solid transparent !important; border-radius: 14px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
  background:
    radial-gradient(82% 72% at 27% 16%, rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.26), transparent 60%) padding-box,
    linear-gradient(155deg, rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.15), rgba(12,19,34,0.92) 58%, rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.05)) padding-box,
    conic-gradient(from var(--kpi-band-border-angle),
      rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.92),
      rgba(255,255,255,0.20),
      rgba(124,196,255, 0.92),
      rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.92)) border-box !important;
  box-shadow: 0 12px 26px rgba(0,0,0,0.26), inset 0 1px 0 rgba(255,255,255,0.06);
  animation: kpiBandBorderSpin 9s linear infinite;
}
/* Stagger the spin so they don't rotate in lockstep. */
.kpi-temu-headline-main { animation: kpiBandBorderSpin 9s linear 0s infinite; }
.kpi-temu-peak.is-fast { animation: kpiBandBorderSpin 9s linear -1.5s infinite; }
.kpi-temu-peak.is-slow { animation: kpiBandBorderSpin 9s linear -3s infinite; }
.kpi-temu-stage-card:nth-child(1) { animation: kpiBandBorderSpin 9s linear -0.7s infinite; }
.kpi-temu-stage-card:nth-child(2) { animation: kpiBandBorderSpin 9s linear -1.9s infinite; }
.kpi-temu-stage-card:nth-child(3) { animation: kpiBandBorderSpin 9s linear -3.1s infinite; }
.kpi-temu-stage-card:nth-child(4) { animation: kpiBandBorderSpin 9s linear -4.4s infinite; }
.kpi-temu-stage-card:nth-child(5) { animation: kpiBandBorderSpin 9s linear -5.7s infinite; }

/* Opening animation: keep the spin AND add a one-shot card-in (different props). */
.kpi-temu-section.is-opening .kpi-temu-headline-main { animation: kpiBandBorderSpin 9s linear 0s infinite, kpiTemuCardIn 0.55s cubic-bezier(0.22,1,0.36,1) 0s both; }
.kpi-temu-section.is-opening .kpi-temu-peak.is-fast { animation: kpiBandBorderSpin 9s linear -1.5s infinite, kpiTemuCardIn 0.55s cubic-bezier(0.22,1,0.36,1) 0.08s both; }
.kpi-temu-section.is-opening .kpi-temu-peak.is-slow { animation: kpiBandBorderSpin 9s linear -3s infinite, kpiTemuCardIn 0.55s cubic-bezier(0.22,1,0.36,1) 0.14s both; }
.kpi-temu-section.is-opening .kpi-temu-stage-card:nth-child(1) { animation: kpiBandBorderSpin 9s linear -0.7s infinite, kpiTemuCardIn 0.5s cubic-bezier(0.22,1,0.36,1) 0.2s both; }
.kpi-temu-section.is-opening .kpi-temu-stage-card:nth-child(2) { animation: kpiBandBorderSpin 9s linear -1.9s infinite, kpiTemuCardIn 0.5s cubic-bezier(0.22,1,0.36,1) 0.26s both; }
.kpi-temu-section.is-opening .kpi-temu-stage-card:nth-child(3) { animation: kpiBandBorderSpin 9s linear -3.1s infinite, kpiTemuCardIn 0.5s cubic-bezier(0.22,1,0.36,1) 0.32s both; }
.kpi-temu-section.is-opening .kpi-temu-stage-card:nth-child(4) { animation: kpiBandBorderSpin 9s linear -4.4s infinite, kpiTemuCardIn 0.5s cubic-bezier(0.22,1,0.36,1) 0.38s both; }
.kpi-temu-section.is-opening .kpi-temu-stage-card:nth-child(5) { animation: kpiBandBorderSpin 9s linear -5.7s infinite, kpiTemuCardIn 0.5s cubic-bezier(0.22,1,0.36,1) 0.44s both; }

@media (prefers-reduced-motion: reduce) {
  .kpi-temu-headline-main, .kpi-temu-peak, .kpi-temu-stage-card,
  .kpi-temu-section.is-opening .kpi-temu-headline-main,
  .kpi-temu-section.is-opening .kpi-temu-peak,
  .kpi-temu-section.is-opening .kpi-temu-stage-card { animation: none !important; }
}

/* Glow on the selected (stage-focused) card. */
.kpi-temu-stage-card.is-focused {
  box-shadow: 0 0 0 2px rgba(var(--seg-rgb), 0.85), 0 0 28px -2px rgba(var(--seg-rgb), 0.65), 0 12px 26px rgba(0,0,0,0.3);
}
.kpi-temu-stage-card.is-focused::after { display: none !important; }

/* Peak hover lift (clickable to focus the period). */
.kpi-temu-peak:not([disabled]):hover,
.kpi-temu-stage-card:hover { transform: translateY(-2px); box-shadow: 0 16px 30px rgba(0,0,0,0.3), 0 0 20px rgba(var(--card-rgb, var(--seg-rgb,245,179,74)), 0.18); }

/* ── Smooth data-table open / close ─────────────────────────────────────────── */
.kpi-temu-table-wrap { max-height: 460px; overflow: auto; opacity: 1; transition: max-height 0.42s cubic-bezier(0.22,1,0.36,1), opacity 0.32s ease, padding 0.42s ease; }
.kpi-temu-table-wrap.is-collapsed { max-height: 0; opacity: 0; overflow: hidden; }
.kpi-temu-table-chevron { transition: transform 0.3s cubic-bezier(0.22,1,0.36,1); }
@media (prefers-reduced-motion: reduce) { .kpi-temu-table-wrap { transition: none; } }

/* Light mode card interior. */


/* ───────────────────────────────────────────────────────────────────────────
   TEMU KPI v9 (2026-06-19) — tone down card colours; shorter top-3; animated
   circle gradient ONLY on top-3; staggered & varied-speed border rings; selected
   card = mirrored + slightly faster ring + glow; hover = lift only; taller chart;
   very slight gradient on the solid bar segments; trend-exact preset chips; fixed
   Today-tag structure; selected-column glow; smaller stage cards.
   ─────────────────────────────────────────────────────────────────────────── */

@keyframes kpiTemuCircle { 0% { background-position: 18% 22%; } 100% { background-position: 78% 64%; } }

/* Softer (less vivid) card fill + border. */
.kpi-temu-headline-main, .kpi-temu-peak, .kpi-temu-stage-card {
  background:
    radial-gradient(82% 72% at 27% 16%, rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.13), transparent 62%) padding-box,
    linear-gradient(155deg, rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.08), rgba(12,19,34,0.95) 60%, rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.03)) padding-box,
    conic-gradient(from var(--kpi-band-border-angle),
      rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.60),
      rgba(255,255,255,0.16),
      rgba(124,196,255, 0.58),
      rgba(var(--card-rgb, var(--seg-rgb, 245,179,74)), 0.60)) border-box !important;
}

/* Top-3 a touch shorter. */
.kpi-temu-headline-main, .kpi-temu-peak { min-height: 100px; }

/* Staggered + varied-speed border rings (not in lockstep). */
.kpi-temu-headline-main { animation: kpiBandBorderSpin 9.5s linear 0s infinite; }
.kpi-temu-peak.is-fast { animation: kpiBandBorderSpin 8.2s linear -2.5s infinite; }
.kpi-temu-peak.is-slow { animation: kpiBandBorderSpin 10.6s linear -5s infinite; }
.kpi-temu-stage-card:nth-child(1) { animation: kpiBandBorderSpin 8.4s linear -0.7s infinite; }
.kpi-temu-stage-card:nth-child(2) { animation: kpiBandBorderSpin 9.7s linear -2.3s infinite; }
.kpi-temu-stage-card:nth-child(3) { animation: kpiBandBorderSpin 10.9s linear -4.0s infinite; }
.kpi-temu-stage-card:nth-child(4) { animation: kpiBandBorderSpin 9.1s linear -5.6s infinite; }
.kpi-temu-stage-card:nth-child(5) { animation: kpiBandBorderSpin 11.6s linear -7.3s infinite; }

/* Animated CIRCLE gradient — only on the top-3 cards (re-enable their ::before). */
.kpi-temu-headline-main::before, .kpi-temu-peak::before {
  display: block !important; content: "" !important;
  position: absolute; inset: 0; z-index: -1; border-radius: inherit; pointer-events: none;
  background: radial-gradient(58% 58% at 32% 26%, rgba(var(--card-rgb, 245,179,74), 0.22), transparent 62%);
  background-size: 200% 200%;
  animation: kpiTemuCircle 11s ease-in-out infinite alternate !important;
}
.kpi-temu-peak.is-fast::before { animation-duration: 13s !important; animation-delay: -3s !important; }
.kpi-temu-peak.is-slow::before { animation-duration: 15s !important; animation-delay: -6s !important; }
/* Stage cards keep what they have (static fill + ring) — no circle animation. */
.kpi-temu-stage-card::before { display: none !important; }

/* Hover = lift only (no competing glow). */
.kpi-temu-peak:not([disabled]):hover,
.kpi-temu-stage-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 28px rgba(0,0,0,0.28), inset 0 1px 0 rgba(255,255,255,0.06);
}

/* Selected stage card: same ring MIRRORED (reverse) + slightly faster + glow. */
.kpi-temu-stage-card.is-focused {
  animation: kpiBandBorderSpin 6.5s linear infinite reverse !important;
  box-shadow: 0 0 0 2px rgba(var(--seg-rgb), 0.82), 0 0 26px -3px rgba(var(--seg-rgb), 0.6), 0 12px 26px rgba(0,0,0,0.3);
}

/* Smaller ATA-NOA … cards. */
.kpi-temu-stage-card { min-height: 80px; padding: 9px 9px; gap: 2px; }
.kpi-temu-stage-card-name { font-size: 10.5px; }
.kpi-temu-stage-card-route { font-size: 8.5px; }
.kpi-temu-stage-card-val { font-size: 18px; margin-top: 1px; }
.kpi-temu-stage-card-share { font-size: 9px; }

/* Taller column chart so more is visible. */
.kpi-temu-cols { height: 360px; }
.kpi-temu-yaxis { height: 360px; }

/* Very, very slight gradient over the solid segment fill (keeps the flat colour). */
.kpi-temu-seg { background: linear-gradient(168deg, rgba(255,255,255,0.13), rgba(255,255,255,0) 36%, rgba(0,0,0,0.05)), rgb(var(--seg-rgb)) !important; }

/* Selected column glow. */
.kpi-temu-col.is-focus .kpi-temu-bar { box-shadow: 0 0 0 1.6px rgba(var(--temu-accent-rgb), 0.7), 0 0 18px rgba(var(--temu-accent-rgb), 0.3), 0 6px 18px rgba(0,0,0,0.34) !important; }
