  -webkit-mask-image: linear-gradient(90deg, transparent, #000 16px, #000 calc(100% - 16px), transparent);
  mask-image: linear-gradient(90deg, transparent, #000 16px, #000 calc(100% - 16px), transparent);
}
.kpi-temu-rgroup.is-week::-webkit-scrollbar { height: 5px; }
.kpi-temu-rgroup.is-week::-webkit-scrollbar-thumb { background: rgba(135,160,201,0.3); border-radius: 3px; }
.kpi-temu-rgroup.is-week .kpi-temu-rchip { flex: 0 0 auto; }
.kpi-temu-rsep { width: 1px; align-self: stretch; min-height: 18px; margin: 0 3px; background: linear-gradient(180deg, transparent, rgba(135,160,201,0.34), transparent); }
/* minimal per-category identity via the active-state hue */
