/* Compare = compact A/B deep-dive (replaces the oversized side cards). */
.kpi-temu-detail.is-compare.is-open { max-height: 600px; overflow: auto; }
.kpi-temu-cmp-head { display: flex; align-items: center; gap: 9px; margin-bottom: 11px; }
.kpi-temu-cmp-head b { color: #f4f8ff; font-size: 13.5px; font-weight: 880; }
.kpi-temu-cmp-head-sub { color: rgba(178,193,219,0.6); font-size: 10px; font-weight: 820; letter-spacing: 0.07em; text-transform: uppercase; }
.kpi-temu-cmp-head .kpi-temu-detail-close { margin-left: auto; }
.kpi-temu-cmp-slots { display: grid; grid-template-columns: 1fr auto 1fr; align-items: stretch; gap: 8px; margin-bottom: 11px; }
.kpi-temu-cmp-slot {
  position: relative; display: flex; flex-direction: column; gap: 2px; align-items: flex-start; text-align: left;
  padding: 9px 11px; border-radius: 11px; cursor: pointer; color: inherit;
  border: 1px solid rgba(135,160,201,0.22); background: rgba(255,255,255,0.03);
  transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}
.kpi-temu-cmp-slot:hover { background: rgba(255,255,255,0.05); }
.kpi-temu-cmp-slot.is-a { --slot-rgb: var(--temu-accent-rgb); }
.kpi-temu-cmp-slot.is-b { --slot-rgb: 124,196,255; }
.kpi-temu-cmp-slot.is-active { border-color: rgba(var(--slot-rgb),0.7); box-shadow: 0 0 0 1px rgba(var(--slot-rgb),0.45), 0 8px 20px rgba(0,0,0,0.22); background: rgba(var(--slot-rgb),0.08); }
.kpi-temu-cmp-slot.is-empty { justify-content: center; align-items: center; min-height: 62px; border-style: dashed; }
.kpi-temu-cmp-slot-tag { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 18px; border-radius: 6px; font-size: 10px; font-weight: 900; color: #0b1424; background: rgb(var(--slot-rgb)); }
.kpi-temu-cmp-slot.is-empty .kpi-temu-cmp-slot-tag { position: absolute; top: 8px; left: 9px; opacity: 0.85; }
.kpi-temu-cmp-slot-range { color: #eaf1fb; font-size: 11px; font-weight: 820; }
.kpi-temu-cmp-slot-val { color: #fff; font-size: 17px; font-weight: 900; font-variant-numeric: tabular-nums; line-height: 1.05; }
.kpi-temu-cmp-slot-val .kpi-temu-dur-min { font-size: 0.72em; opacity: 0.72; margin-left: 1px; }
.kpi-temu-cmp-slot-sub { color: rgba(178,193,219,0.66); font-size: 10px; font-weight: 720; }
.kpi-temu-cmp-slot-pick { color: rgba(192,206,230,0.72); font-size: 11px; font-weight: 780; }
.kpi-temu-cmp-slot-x { position: absolute; top: 7px; right: 8px; width: 18px; height: 18px; display: flex; align-items: center; justify-content: center; border-radius: 6px; color: rgba(200,212,236,0.5); font-size: 10px; }
.kpi-temu-cmp-slot-x:hover { color: #fff; background: rgba(255,255,255,0.12); }
.kpi-temu-cmp-swap { align-self: center; width: 30px; height: 30px; border-radius: 9px; border: 1px solid rgba(135,160,201,0.3); background: rgba(255,255,255,0.05); color: rgba(214,225,245,0.9); font-size: 14px; cursor: pointer; transition: transform 0.25s ease, background 0.18s ease; }
.kpi-temu-cmp-swap:hover { background: rgba(255,255,255,0.1); transform: rotate(180deg); }
.kpi-temu-cmp-verdict { border-radius: 11px; padding: 10px 12px; margin-bottom: 10px; background: rgba(255,255,255,0.025); border: 1px solid rgba(135,160,201,0.16); }
.kpi-temu-cmp-verdict.is-hint { color: rgba(178,193,219,0.66); font-size: 11.5px; font-weight: 760; text-align: center; }
.kpi-temu-cmp-verdict.is-good { --v-rgb: 95,224,160; }
.kpi-temu-cmp-verdict.is-bad { --v-rgb: 255,138,138; }
.kpi-temu-cmp-verdict.is-flat { --v-rgb: 148,163,184; }
.kpi-temu-cmp-vmain { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.kpi-temu-cmp-vlabel { color: rgba(178,193,219,0.7); font-size: 10px; font-weight: 820; letter-spacing: 0.05em; text-transform: uppercase; }
.kpi-temu-cmp-vval { color: rgb(var(--v-rgb)); font-size: 22px; font-weight: 950; font-variant-numeric: tabular-nums; }
.kpi-temu-cmp-vval .kpi-temu-dur-min { font-size: 0.66em; opacity: 0.78; }
.kpi-temu-cmp-vpct { color: rgba(var(--v-rgb),0.94); font-size: 11.5px; font-weight: 820; }
.kpi-temu-cmp-mover { display: flex; align-items: center; gap: 7px; margin-top: 7px; padding-top: 7px; border-top: 1px solid rgba(135,160,201,0.14); font-size: 11px; }
.kpi-temu-cmp-mover > i { width: 9px; height: 9px; border-radius: 3px; background: rgb(var(--seg-rgb)); flex: 0 0 auto; }
.kpi-temu-cmp-mover span { color: rgba(178,193,219,0.65); font-weight: 740; }
.kpi-temu-cmp-mover em { color: #eaf1fb; font-style: normal; font-weight: 820; }
.kpi-temu-cmp-mover b { margin-left: auto; color: #f4f8ff; font-weight: 880; font-variant-numeric: tabular-nums; }
.kpi-temu-cmp-stages { display: flex; flex-direction: column; gap: 2px; }
.kpi-temu-cmp-st { display: grid; grid-template-columns: 1.35fr 2.2fr auto auto auto; align-items: center; gap: 9px; padding: 5px 6px; border-radius: 7px; font-size: 11px; font-variant-numeric: tabular-nums; }
.kpi-temu-cmp-st.is-head { color: rgba(178,193,219,0.6); font-size: 9px; font-weight: 850; letter-spacing: 0.06em; text-transform: uppercase; }
.kpi-temu-cmp-st:not(.is-head):hover { background: rgba(255,255,255,0.025); }
.kpi-temu-cmp-st-name { display: inline-flex; align-items: center; gap: 6px; color: rgba(214,225,245,0.9); font-weight: 760; }
.kpi-temu-cmp-st-name::before { content: ""; width: 9px; height: 9px; border-radius: 3px; background: rgb(var(--seg-rgb)); flex: 0 0 auto; }
.kpi-temu-cmp-st.is-head .kpi-temu-cmp-st-name::before { display: none; }
.kpi-temu-cmp-st-bars { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.kpi-temu-cmp-st-bars i { display: block; height: 5px; border-radius: 999px; transition: width 0.5s cubic-bezier(0.22,1,0.36,1); }
.kpi-temu-cmp-st-bars i.a { background: rgb(var(--seg-rgb)); }
.kpi-temu-cmp-st-bars i.b { background: rgba(255,255,255,0.5); }
.kpi-temu-cmp-st-va { color: rgba(226,232,240,0.85); text-align: right; min-width: 42px; }
.kpi-temu-cmp-st-vb { color: #fff; font-weight: 820; text-align: right; min-width: 42px; }
.kpi-temu-cmp-st-d { text-align: right; min-width: 50px; font-weight: 850; }
