  mask-image: linear-gradient(90deg, transparent, #000 16px, #000 calc(100% - 16px), transparent);
}
.kpi-trend-rgroup.is-week::-webkit-scrollbar { height: 5px; }
.kpi-trend-rgroup.is-week::-webkit-scrollbar-thumb { background: rgba(135,160,201,0.3); border-radius: 3px; }
.kpi-trend-rgroup.is-week .kpi-trend-rchip { flex: 0 0 auto; }
.kpi-trend-rsep { width: 1px; align-self: stretch; min-height: 18px; margin: 0 3px; background: linear-gradient(180deg, transparent, rgba(135,160,201,0.34), transparent); }
.kpi-trend-rchip.is-cat-all { color: rgba(236,240,248,0.86); }
.kpi-trend-rchip.is-cat-all.is-on {
  border-color: rgba(255,255,255,0.5); color: #fff;
  background: radial-gradient(100% 160% at 0% 0%, rgba(255,255,255,0.22), transparent 62%) padding-box,
    linear-gradient(135deg, rgba(255,255,255,0.7), rgba(210,222,244,0.4)) border-box;
  box-shadow: 0 0 16px rgba(255,255,255,0.10), inset 0 1px 0 rgba(255,255,255,0.16);
}
.kpi-trend-rchip.is-cat-week.is-on {
  border-color: rgba(167,139,250,0.6); color: #f0ebff;
  background: radial-gradient(100% 160% at 0% 0%, rgba(167,139,250,0.32), transparent 62%) padding-box,
    linear-gradient(135deg, rgba(167,139,250,0.7), rgba(124,196,255,0.3)) border-box;
