/* ═══════════════════════════════════════════════════════════════════════════
   KPI PAGE REDESIGN (2026-06-23) — two snap subpages (KPI Tracking ⇄ Riport)
   with a fixed switch bar and two themed, slowly-moving backgrounds.
   ─ Tracking (default): cool blue / cyan / turquoise.
   ─ Riport:             warm green → amber → orange → red ("naplemente").
   Background drift is transform-only (GPU) and pauses during scroll/snap
   (body.kpi-bg-paused), when the tab is hidden (body.kpi-bg-hidden) and outside
   the KPI view — the documented weak-machine FPS rule. NO color-mix().
   ═══════════════════════════════════════════════════════════════════════════ */

/* Per-subpage environment accent (RGB triplets) — segments, dots and the bar
   pick this up so each part matches the active page. */
body.view-kpi-mode            { --kpi-env-accent: 64,206,228; }
body.view-kpi-mode.kpi-sub-report { --kpi-env-accent: 150,130,250; }

/* The dedicated .kpi-bg layer owns the KPI background, so retire the shared ops
   orbs while reporting (keeps the .bg-orbs::after view-switch veil intact). */
body.view-kpi-mode .bg-orb { opacity: 0 !important; animation: none !important; }

/* Riport (warm sunset) static base — overrides the cool tracking base above.
   NO green (user 2026-06-23). background-attachment: fixed is RE-DECLARED here —
   the `background` shorthand resets it to `scroll`, which made the gradient tile
   downward on the tall snap page ("ismétlődik lefele"); fixed pins it to the
   viewport so it never repeats. */
body.view-kpi-mode.kpi-sub-report {
  background:
    radial-gradient(115% 80% at 80% -8%,  #5b40b3 0%, transparent 52%),   /* violet glow, upper-right */
    radial-gradient(125% 86% at 50% 120%, #1d2a72 0%, transparent 58%),   /* deep blue rising from the floor */
    linear-gradient(168deg, #241b46 0%, #19153a 52%, #100c24 100%);       /* smooth indigo foundation */
  background-attachment: fixed;
}

/* ── Moving background field ─────────────────────────────────────────────── */
.kpi-bg {
  position: fixed; inset: 0; z-index: 1;
  overflow: hidden; pointer-events: none;
  opacity: 0;
  transition: opacity 0.55s ease;
}
body.view-kpi-mode .kpi-bg { opacity: 1; }

.kpi-bg-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(52px);
  opacity: 0.5;
  will-change: transform;
  transition: background 0.7s ease, opacity 0.7s ease;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
  animation-direction: alternate;
}
/* Chunky, distinct blobs ("darb") — large, fairly saturated, long offset drifts
   so the field never visibly loops. Tracking colours here; Riport overrides below. */
.kpi-bg-blob-1 { width: 46vw; height: 42vw; left: -8vw;  top: -10vw;
  background: radial-gradient(circle, #38c6ff 0%, transparent 66%); animation: kpiBgDrift1 53s; }
.kpi-bg-blob-2 { width: 40vw; height: 40vw; right: -10vw; top: -6vw;
  background: radial-gradient(circle, #19d3c0 0%, transparent 66%); animation: kpiBgDrift2 61s; }
.kpi-bg-blob-3 { width: 50vw; height: 44vw; left: 26vw;  top: 28vh; opacity: 0.42;
  background: radial-gradient(circle, #2f7bff 0%, transparent 68%); animation: kpiBgDrift3 71s; }
.kpi-bg-blob-4 { width: 38vw; height: 38vw; left: -6vw;  bottom: -12vw;
  background: radial-gradient(circle, #1aa0e6 0%, transparent 66%); animation: kpiBgDrift4 67s; }
.kpi-bg-blob-5 { width: 42vw; height: 40vw; right: -8vw; bottom: -10vw;
  background: radial-gradient(circle, #5ad9d0 0%, transparent 66%); animation: kpiBgDrift5 59s; }

/* Riport blobs — soft, harmonious purple-blue set (violet → indigo → blue): bigger
   blur + lower opacity so they read as a gentle wash, not garish patches. */
body.kpi-sub-report .kpi-bg-blob { filter: blur(66px); opacity: 0.42; }
body.kpi-sub-report .kpi-bg-blob-1 { background: radial-gradient(circle, #8f6cf2 0%, transparent 68%); }
body.kpi-sub-report .kpi-bg-blob-2 { background: radial-gradient(circle, #6979f2 0%, transparent 68%); }
body.kpi-sub-report .kpi-bg-blob-3 { background: radial-gradient(circle, #a878f0 0%, transparent 70%); }
body.kpi-sub-report .kpi-bg-blob-4 { background: radial-gradient(circle, #5566ee 0%, transparent 68%); }
body.kpi-sub-report .kpi-bg-blob-5 { background: radial-gradient(circle, #9b7af4 0%, transparent 68%); }

@keyframes kpiBgDrift1 {
  0%   { transform: translate3d(0,0,0)       scale(1);    }
  50%  { transform: translate3d(7vw,5vh,0)   scale(1.12); }
  100% { transform: translate3d(-4vw,9vh,0)  scale(0.96); }
}
@keyframes kpiBgDrift2 {
  0%   { transform: translate3d(0,0,0)       scale(1.04); }
  50%  { transform: translate3d(-8vw,6vh,0)  scale(0.94); }
  100% { transform: translate3d(5vw,-5vh,0)  scale(1.1);  }
}
@keyframes kpiBgDrift3 {
  0%   { transform: translate3d(0,0,0)       scale(1);    }
  50%  { transform: translate3d(-6vw,-7vh,0) scale(1.14); }
  100% { transform: translate3d(8vw,4vh,0)   scale(0.95); }
}
@keyframes kpiBgDrift4 {
  0%   { transform: translate3d(0,0,0)       scale(0.98); }
  50%  { transform: translate3d(9vw,-6vh,0)  scale(1.12); }
  100% { transform: translate3d(-5vw,-3vh,0) scale(1);    }
}
@keyframes kpiBgDrift5 {
  0%   { transform: translate3d(0,0,0)       scale(1.06); }
  50%  { transform: translate3d(-7vw,-5vh,0) scale(0.93); }
  100% { transform: translate3d(4vw,7vh,0)   scale(1.1);  }
}

/* Pause the drift during scroll/snap, when the tab is hidden, and outside the
   KPI view — blobs freeze in place and resume smoothly on idle. */
body.kpi-bg-paused .kpi-bg-blob,
body.kpi-bg-hidden .kpi-bg-blob,
body:not(.view-kpi-mode) .kpi-bg-blob { animation-play-state: paused; }
@media (prefers-reduced-motion: reduce) {
  .kpi-bg-blob { animation: none !important; }
  .kpi-bg { transition: none; }
}

/* Subpage cross-fade wash — masks the hard base-gradient swap when switching. */
.kpi-bg-veil {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(125% 100% at 50% 0%, rgba(110,220,255,0.20), transparent 70%);
}
body.kpi-sub-switching.kpi-sub-report .kpi-bg-veil {
  background: radial-gradient(125% 100% at 50% 0%, rgba(150,130,250,0.22), transparent 70%);
}
body.kpi-sub-switching .kpi-bg-veil { animation: kpiBgVeil 0.78s ease both; }
@keyframes kpiBgVeil { 0% { opacity: 0; } 42% { opacity: 1; } 100% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { body.kpi-sub-switching .kpi-bg-veil { animation: none; } }

/* ── Page intro (opacity-only) ───────────────────────────────────────────── */
@keyframes kpiPageFade { from { opacity: 0; } to { opacity: 1; } }
body.view-kpi-mode .kpi-page { animation: kpiPageFade 0.42s ease both; }

/* Header on the KPI page: no drop-shadow below (user), but keep a crisp inset edge
   so the outline stays defined; the Riport (bright warm) field washed out the old
   border — give it an extra inner ring + warmer border there. */
body.view-kpi-mode .app-header { box-shadow: inset 0 1px 0 rgba(255,255,255,0.10); }
body.view-kpi-mode.kpi-sub-report .app-header {
  border-color: rgba(202,196,255,0.28);
  box-shadow: inset 0 0 0 1px rgba(18,14,44,0.24), inset 0 1px 0 rgba(255,255,255,0.12);
}

/* ── App-header centre: the KPI Tracking ⇄ Riport switch (KPI page only) ───── */
.kpi-header-switch { display: none; }
body.view-kpi-mode .kpi-header-switch {
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
  z-index: 3;
  animation: kpiPageFade 0.4s ease both;
}
.kpi-header-switch .kpi-page-updated {
  font-size: 9.5px; font-weight: 700; letter-spacing: 0.01em; text-align: center;
  color: rgba(203,213,225,0.55);
  max-width: 260px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* Switch — mirrors the ULD active/dispatched switch, themed per subpage. */
.kpi-subview-switch {
  position: relative;
  display: inline-flex; align-items: center; gap: 4px;
  padding: 4px; border-radius: 11px; flex-shrink: 0;
  background: rgba(8,20,34,0.5);
  border: 1px solid rgba(148,193,224,0.18);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.06);
}
body.kpi-sub-report .kpi-subview-switch {
  background: rgba(22,18,42,0.5);
  border-color: rgba(160,140,250,0.22);
}
.kpi-subview-glow {
  position: absolute; inset: 0; border-radius: 11px; pointer-events: none;
  background: radial-gradient(120% 130% at 18% 0%, rgba(34,211,238,0.12), transparent 60%);
  transition: background 0.5s ease;
}
body.kpi-sub-report .kpi-subview-glow {
  background: radial-gradient(120% 130% at 82% 0%, rgba(150,130,250,0.16), transparent 60%);
}
.kpi-subview-btn {
  position: relative; z-index: 1;
  border: 1px solid transparent; border-radius: 8px;
  min-height: 30px; padding: 0 16px;
  background: transparent; color: var(--text-muted);
  font-size: 12px; font-weight: 850; letter-spacing: 0.02em;
  cursor: pointer; white-space: nowrap;
  transition: color 0.2s ease, background 0.2s ease, border-color 0.2s ease, transform 0.2s ease, box-shadow 0.24s ease;
}
.kpi-subview-btn:hover { color: var(--text); transform: translateY(-1px); background: rgba(255,255,255,0.05); }
.kpi-subview-btn.kpi-subview-btn-active {
  color: #e6fbff;
  background: linear-gradient(135deg, rgba(34,211,238,0.30), rgba(56,140,230,0.22));
  border-color: rgba(56,200,228,0.40);
  box-shadow: 0 8px 22px rgba(34,180,220,0.16), inset 0 1px 0 rgba(255,255,255,0.12);
}
body.kpi-sub-report .kpi-subview-btn.kpi-subview-btn-active {
  color: #efeaff;
  background: linear-gradient(135deg, rgba(150,130,250,0.32), rgba(96,118,242,0.24));
  border-color: rgba(160,140,250,0.42);
  box-shadow: 0 8px 22px rgba(120,110,240,0.16), inset 0 1px 0 rgba(255,255,255,0.12);
}

/* ── Subpages: show/hide + a brief cross-fade on switch ──────────────────── */
/* KPI header subview switch: shared morphing thumb, aligned to the KPI page controls. */
body.view-kpi-mode .kpi-subview-switch {
  --kpi-subview-index: 0;
  --kpi-subview-pad: 3px;
  --kpi-subview-radius: 10px;
  --kpi-subview-thumb-radius: calc(var(--kpi-subview-radius) - var(--kpi-subview-pad));
  --ks-foil-pos: var(--ks-pp, calc(10% + var(--kpi-subview-index, 0) * 80%));
  isolation: isolate;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  width: clamp(236px, 24vw, 292px);
  min-height: 39px;
  padding: var(--kpi-subview-pad);
  border-radius: var(--kpi-subview-radius);
  border: 1px solid rgba(148, 194, 225, 0.25);
  overflow: hidden;
  cursor: pointer;
  touch-action: manipulation;
  user-select: none;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.11), rgba(255,255,255,0.026) 52%, rgba(0,0,0,0.18)),
    radial-gradient(88% 128% at 0% 0%, rgba(34,211,238,0.18), transparent 58%),
    radial-gradient(78% 118% at 100% 0%, rgba(167,139,250,0.14), transparent 62%),
    linear-gradient(90deg, rgba(4,12,22,0.93), rgba(12,19,35,0.94));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.18),
    inset 0 -1px 0 rgba(0,0,0,0.54),
    inset 0 0 0 1px rgba(255,255,255,0.045),
    0 13px 32px rgba(0,0,0,0.32),
    0 1px 0 rgba(255,255,255,0.05);
  transition:
    border-color 0.22s ease,
    box-shadow 0.24s cubic-bezier(0.22,1,0.36,1),
    transform 0.18s cubic-bezier(0.22,1,0.36,1),
    background 0.44s ease;
}

body.view-kpi-mode.kpi-sub-report .kpi-subview-switch {
  border-color: rgba(255, 184, 108, 0.24);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.11), rgba(255,255,255,0.026) 52%, rgba(0,0,0,0.18)),
    radial-gradient(88% 128% at 0% 0%, rgba(255,138,61,0.16), transparent 58%),
    radial-gradient(78% 118% at 100% 0%, rgba(167,139,250,0.18), transparent 62%),
    linear-gradient(90deg, rgba(20,12,22,0.93), rgba(24,18,38,0.94));
}

body.view-kpi-mode .kpi-subview-switch:hover {
