    0 0 30px rgba(34,211,238,0.08),
    0 0 36px rgba(167,139,250,0.08);
}

body.view-kpi-mode .kpi-subview-switch:active {
  transform: translateY(0.5px) scale(0.997);
}

body.view-kpi-mode .kpi-subview-switch::before {
  content: "";
  position: absolute;
  top: var(--kpi-subview-pad);
  bottom: var(--kpi-subview-pad);
  left: var(--kpi-subview-pad);
  width: calc((100% - (var(--kpi-subview-pad) * 2)) / 2);
  border-radius: var(--kpi-subview-thumb-radius);
  z-index: 1;
  transform-origin: var(--ks-origin, 0%) center;
  transform:
    translateX(var(--ks-tx, calc(var(--kpi-subview-index, 0) * 100%)))
    scaleX(var(--ks-sx, 1))
    scaleY(var(--ks-sy, 1));
  background:
    linear-gradient(180deg,
      rgba(255,255,255,0.50) 0%,
      rgba(255,255,255,0.12) 27%,
      rgba(255,255,255,0.00) 51%,
      rgba(3,12,24,0.16) 80%,
      rgba(3,12,24,0.31) 100%),
    radial-gradient(58% 130% at 14% 26%, rgba(162,245,255,0.58), rgba(162,245,255,0) 60%),
    radial-gradient(56% 140% at 46% 74%, rgba(88,166,255,0.45), rgba(88,166,255,0) 58%),
    radial-gradient(60% 150% at 84% 34%, rgba(255,172,80,0.50), rgba(255,172,80,0) 60%),
    linear-gradient(107deg,
      rgba(255,255,255,0.00) 12%,
      rgba(255,255,255,0.28) 30%,
      rgba(255,255,255,0.00) 46%,
      rgba(255,255,255,0.14) 66%,
      rgba(255,255,255,0.00) 82%),
    linear-gradient(105deg,
      rgba(34,211,238,0.98) 0%,
      rgba(74,158,255,0.98) 28%,
      rgba(132,110,255,0.96) 56%,
      rgba(255,138,61,0.96) 100%);
  background-repeat: no-repeat;
  background-size: 100% 100%, 220% 100%, 220% 100%, 220% 100%, 220% 100%, 220% 100%;
  background-position:
    50% 0%,
    var(--ks-foil-pos) 26%,
    var(--ks-foil-pos) 74%,
    var(--ks-foil-pos) 34%,
    var(--ks-foil-pos) 0%,
    var(--ks-foil-pos) 0%;
  box-shadow:
    inset 0 1.6px 0 rgba(255,255,255,0.72),
    inset 0 -1px 1px rgba(8,15,32,0.38),
    inset 1px 0 0 rgba(255,255,255,0.26),
    inset -1px 0 0 rgba(8,15,32,0.24),
    0 0 0 1px rgba(255,255,255,0.18),
    0 2px 10px rgba(34,211,238,0.48),
    0 7px 24px rgba(74,158,255,0.38),
    0 13px 34px rgba(72,43,171,0.25),
    0 3px 9px rgba(0,0,0,0.38);
  filter:
    saturate(calc(1.06 + var(--ks-energy, 0) * 0.46))
    brightness(calc(1.02 + var(--ks-energy, 0) * 0.15))
    drop-shadow(0 0 calc(var(--ks-energy, 0) * 16px) rgba(125,211,252,0.45));
  transition:
    transform 0.52s cubic-bezier(0.34, 1.28, 0.5, 1),
    background-position 0.52s cubic-bezier(0.34, 1.28, 0.5, 1),
    box-shadow 0.3s ease,
    filter 0.3s ease;
}

body.view-kpi-mode.kpi-sub-report .kpi-subview-switch::before {
  box-shadow:
    inset 0 1.6px 0 rgba(255,255,255,0.72),
    inset 0 -1px 1px rgba(34,8,42,0.36),
    inset 1px 0 0 rgba(255,255,255,0.26),
    inset -1px 0 0 rgba(20,8,40,0.24),
    0 0 0 1px rgba(255,255,255,0.18),
    0 2px 10px rgba(255,138,61,0.50),
    0 7px 24px rgba(167,139,250,0.40),
    0 13px 34px rgba(72,43,171,0.27),
    0 3px 9px rgba(0,0,0,0.38);
}

body.view-kpi-mode .kpi-subview-switch::after {
  content: "";
  position: absolute;
  top: var(--kpi-subview-pad);
  left: var(--kpi-subview-pad);
  width: calc((100% - var(--kpi-subview-pad) * 2) / 2);
  height: calc(64% - var(--kpi-subview-pad));
  border-radius:
    var(--kpi-subview-thumb-radius) var(--kpi-subview-thumb-radius)
    40% 40% / var(--kpi-subview-thumb-radius) var(--kpi-subview-thumb-radius) 50% 50%;
  z-index: 2;
  pointer-events: none;
  opacity: 0.9;
  transform-origin: var(--ks-origin, 0%) center;
  transform:
    translateX(var(--ks-tx, calc(var(--kpi-subview-index, 0) * 100%)))
    scaleX(var(--ks-sx, 1))
    scaleY(var(--ks-sy, 1));
  background:
    radial-gradient(ellipse 60% 150% at 50% -22%,
      rgba(255,255,255,0.55) 0%,
      rgba(255,255,255,0.17) 46%,
      transparent 72%);
  background-size: 170% 100%;
  background-position: 50% 0;
  mix-blend-mode: screen;
  transition:
    transform 0.52s cubic-bezier(0.34, 1.28, 0.5, 1),
    opacity 0.3s ease;
}

body.view-kpi-mode .kpi-subview-switch.ks-physics::before,
body.view-kpi-mode .kpi-subview-switch.ks-physics::after {
  transition: none !important;
}

body.view-kpi-mode .kpi-subview-switch:hover::after {
  animation: kpiSubviewSpecDrift 2.6s ease-in-out infinite;
}

body.view-kpi-mode .kpi-subview-switch.is-morphing::after {
  animation: kpiSubviewMorphGlint 0.5s ease;
}

body.view-kpi-mode .kpi-subview-switch.is-landing {
  animation: kpiSubviewTrackRecoil 420ms cubic-bezier(0.16,1,0.3,1);
}

body.view-kpi-mode .kpi-subview-glow {
  z-index: 0;
  inset: 1px;
  border-radius: calc(var(--kpi-subview-radius) - 1px);
  background:
