}

body.view-kpi-mode .kpi-subview-btn,
body.view-kpi-mode .kpi-subview-btn.kpi-subview-btn-active,
body.view-kpi-mode.kpi-sub-report .kpi-subview-btn.kpi-subview-btn-active {
