/* ── Segment control physics skin (flow_glass_control.js) ─────────────────── */
/*
  --fg-tx  drives translateX on ::before (thumb) and ::after (shine).
  --fg-sx  drives scaleX on both.
  transform-origin: left center → stretch always goes rightward (no negative tx).
  NO backdrop-filter: causes compositor artifacts in the portable renderer.
  Glass look is achieved with gradients + multi-layer box-shadow only.
*/

/* ── Thumb (::before) — physics transform + rich glass skin ─────────────── */
body.view-kpi-mode .kpi-flow-mode-control::before {
  transform-origin: left center;
  transform:
    translateX(var(--fg-tx, calc(var(--flow-mode-index, 0) * 100%)))
    scaleX(var(--fg-sx, 1));

  /* Layered gradient: warm highlight → orange → violet → deep purple */
  background:
    linear-gradient(148deg,
      rgba(255, 218, 140, 0.35)  0%,
      rgba(255, 148,  55, 0.97) 22%,
      rgba(215,  88, 230, 0.88) 62%,
      rgba(120,  68, 248, 0.96) 100%),
    rgba(0, 0, 0, 0.08);

  /* Rim lighting + glow */
  box-shadow:
    /* inner rim — top bright, bottom/sides subtle */
    inset 0  1.5px  0   rgba(255, 255, 255, 0.60),
    inset 0 -1px   0   rgba(0,   0,   0,   0.24),
    inset 1px  0   0   rgba(255, 255, 255, 0.24),
    inset -1px 0   0   rgba(0,   0,   0,   0.14),
    /* outer border */
    0 0 0 1px rgba(255, 255, 255, 0.16),
    /* ambient glow — orange + purple layers */
    0  2px 12px rgba(255, 148,  55, 0.58),
    0  4px 28px rgba(170, 100, 255, 0.50),
    0  8px 40px rgba(120,  50, 240, 0.28),
    /* base depth */
    0  3px 10px rgba(0, 0, 0, 0.32);

  transition:
    transform 0.42s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.28s ease;
}

/* ── Shine layer (::after) — top-lit glass highlight ─────────────────────── */
/* Same footprint as ::before, tracks via identical --fg-tx/--fg-sx. */
body.view-kpi-mode .kpi-flow-mode-control::after {
  content: "";
  position: absolute;
  top: var(--flow-control-pad, 3px);
  left: var(--flow-control-pad, 3px);
  width: calc((100% - var(--flow-control-pad, 3px) * 2) / 2);
  height: calc(55% - var(--flow-control-pad, 3px));
  border-radius:
    var(--flow-thumb-radius, 7px) var(--flow-thumb-radius, 7px)
    40% 40% / var(--flow-thumb-radius, 7px) var(--flow-thumb-radius, 7px) 50% 50%;
  /* Soft top-lit specular — like light reflecting off rounded glass */
  background:
    radial-gradient(ellipse 80% 160% at 50% -15%,
      rgba(255, 255, 255, 0.42)  0%,
      rgba(255, 255, 255, 0.18) 35%,
      transparent               68%);
  transform-origin: left center;
  transform:
    translateX(var(--fg-tx, calc(var(--flow-mode-index, 0) * 100%)))
    scaleX(var(--fg-sx, 1));
  pointer-events: none;
  z-index: 3;
  transition: transform 0.42s cubic-bezier(0.22, 1, 0.36, 1);
}

/* ── Suppress CSS transitions during physics spring ──────────────────────── */
