      rgba(255,255,255,0.00) 12%,
      rgba(255,255,255,0.28) 30%,
      rgba(255,255,255,0.00) 46%,
      rgba(255,255,255,0.14) 66%,
      rgba(255,255,255,0.00) 82%),
    linear-gradient(105deg,
      rgba(255,172, 70,0.99)  0%,
      rgba(255,112, 92,0.98) 25%,
      rgba(231, 84,168,0.96) 50%,
      rgba(170, 96,238,0.97) 75%,
      rgba(108, 98,250,0.99) 100%);
  background-repeat: no-repeat;
  background-size:
    100% 100%,
    220% 100%, 220% 100%, 220% 100%,
    220% 100%,
    220% 100%;
  background-position:
    50% 0%,
    var(--fg-foil-pos) 26%, var(--fg-foil-pos) 74%, var(--fg-foil-pos) 34%,
    var(--fg-foil-pos) 0%,
