  box-shadow:
    inset 0 1.6px 0 rgba(255,255,255,0.72),
    inset 0 -1px 1px rgba(28,6,40,0.36),
    inset 1px 0 0 rgba(255,255,255,0.26),
    inset -1px 0 0 rgba(20,8,40,0.24),
    0 0 0 1px rgba(255,255,255,0.18),
    0 2px 10px rgba(255,138,61,0.52),
    0 7px 26px rgba(167,139,250,0.42),
    0 15px 38px rgba(72,43,171,0.30),
    0 3px 9px rgba(0,0,0,0.38);

  /* --fg-energy (speed) blooms brightness + a directional motion-glow */
  filter:
    saturate(calc(1.06 + var(--fg-energy, 0) * 0.5))
    brightness(calc(1.02 + var(--fg-energy, 0) * 0.16))
    drop-shadow(0 0 calc(var(--fg-energy, 0) * 18px) rgba(255,150,90,0.55));

  /* CSS fallback transition (when the JS spring is not running) */
  transition:
    transform           0.52s cubic-bezier(0.34, 1.28, 0.5, 1),
    background-position 0.52s cubic-bezier(0.34, 1.28, 0.5, 1),
    box-shadow 0.3s ease, filter 0.3s ease;
}

/* ── Specular highlight (::after) — tracks the window; drifts on hover ────── */
body.view-kpi-mode .kpi-flow-mode-control::after {
  transform-origin: var(--fg-origin, 0%) center;
  transform:
    translateX(var(--fg-tx, calc(var(--flow-mode-index, 0) * 100%)))
    scaleX(var(--fg-sx, 1))
    scaleY(var(--fg-sy, 1));
  opacity: 0.92;
  background:
    radial-gradient(ellipse 60% 150% at 50% -22%,
      rgba(255,255,255,0.55) 0%,
      rgba(255,255,255,0.16) 46%,
      transparent 72%);
  background-size: 170% 100%;
  background-position: 50% 0;
  mix-blend-mode: screen;
  transition:
    transform 0.52s cubic-bezier(0.34, 1.28, 0.5, 1),
    opacity 0.3s ease;
}

/* gentle glare drift — HOVER only (interaction-gated, single small element) */
