body.view-kpi-mode .kpi-flow-mode-btn.is-on {
  text-shadow:
    0 1px 1px rgba(0,0,0,0.88),
    0 0 2px rgba(0,0,0,0.72),
    0 0 10px rgba(255,138,61,0.24),
    0 0 14px rgba(167,139,250,0.18);
}

body.view-kpi-mode .kpi-subview-btn.kpi-subview-btn-active::after,
body.view-kpi-mode .kpi-flow-mode-btn.is-on::after {
  opacity: 0.36;
}

@keyframes kpiSegmentLabelActivate {
  0% {
    transform: translateY(1px) scale(0.975);
    filter: saturate(0.92) brightness(0.96);
  }
  48% {
    transform: translateY(-0.75px) scale(1.045);
    filter: saturate(1.10) brightness(1.07);
  }
  100% {
    transform: none;
    filter: saturate(1.05) brightness(1.04);
  }
}

@media (prefers-reduced-motion: reduce) {
  body.view-kpi-mode .kpi-subview-btn,
  body.view-kpi-mode .kpi-flow-mode-btn,
  body.view-kpi-mode .kpi-subview-btn.kpi-subview-btn-active,
  body.view-kpi-mode .kpi-flow-mode-btn.is-on {
    animation: none !important;
    transition: none !important;
  }
}

body.view-tv-mode .print-preview-overlay,
body.view-tv-mode .settings-overlay,
body.view-tv-mode .dev-overlay,
body.view-tv-mode .dev-pin-overlay { display: none !important; }

/* TV mód PERF (gyenge Acer mini PC): a `#tv-overlay` OPÁK és teljes képernyős, így a
   mögötte lévő teljes app-felület (KPI/ULD header + tartalom, háttér-orbok, azok
   backdrop-filter paneljei és végtelen animációi) LÁTHATATLAN — mégis kompozitálódna/
   animálódna egy iGPU-n = két UI renderelése egyszerre. `visibility:hidden` → nincs
   paint/composite és nincs backdrop-filter mintavételezés, DE a layout megmarad
   (Plotly/Dash méretek sértetlenek, kilépéskor azonnal, újrarajzolás nélkül visszajön).
   Az `animation-play-state:paused` biztosítja, hogy a kompozit (will-change) rétegek
   animációi tényleg megálljanak, ne csak ne fessenek. A `#tv-overlay` testvér, nem
   érintett. Kilépéskor (`view-tv-mode` levétele) minden visszaáll. */
body.view-tv-mode .app-root,
body.view-tv-mode .bg-orbs {
  visibility: hidden !important;
}
body.view-tv-mode .app-root *,
body.view-tv-mode .bg-orbs * {
  animation-play-state: paused !important;
}

/* ═══════════════════════════════════════════════════════════
   TV OVERLAY — dark glass, FM-stílushoz illeszkedő
   ═══════════════════════════════════════════════════════════ */
.tv-overlay {
  position: fixed; inset: 0; z-index: 9000;
  display: none; flex-direction: column;
  --tv-blob1: 255,138,61;
  --tv-blob2: 167,139,250;
  --tv-blob3: 74,158,255;
  --tv-blob1-op: 0.28;
  --tv-blob2-op: 0.22;
  --tv-blob3-op: 0.18;
  --tv-orange: #ff8a3d;
  --tv-purple: #a78bfa;
  --tv-green:  #4ade80;
  --tv-blue:   #60a5fa;
  --tv-amber:  #fbbf24;
  --tv-text:   rgba(255,255,255,0.92);
  --tv-text2:  rgba(255,255,255,0.55);
  --tv-text3:  rgba(255,255,255,0.30);
  --tv-glass:  rgba(255,255,255,0.07);
  --tv-border: rgba(255,255,255,0.10);
  background: #050916;
  font-family: 'Inter', system-ui, sans-serif;
  color: var(--tv-text);
  overflow: hidden;
  user-select: none;
}

/* ─── FAB EXIT BUTTON ─── */
.tv-exit-btn {
  position: absolute; top: 12px; right: 16px; z-index: 300;
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255,255,255,0.12); border: 1px solid var(--tv-border);
  color: var(--tv-text2); font-size: 1rem; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  transition: background 0.2s, color 0.2s, transform 0.15s;
  line-height: 1;
}
.tv-exit-btn:hover { background: rgba(220,38,38,0.3); color: #fca5a5; transform: scale(1.1); }

/* ─── REFRESH ARC FAB ─── */
.tv-refresh-fab {
  position: absolute; top: 56px; right: 16px; z-index: 200;
  width: 36px; height: 36px; display: flex; align-items: center; justify-content: center;
}
.tv-refresh-svg { width: 36px; height: 36px; transform: rotate(-90deg); }
.tv-refresh-track {
  fill: none; stroke: rgba(255,255,255,0.08); stroke-width: 3;
}
.tv-refresh-arc {
  fill: none; stroke: var(--tv-orange); stroke-width: 3; stroke-linecap: round;
  stroke-dasharray: 113; stroke-dashoffset: 113;
  transition: stroke-dashoffset 1s linear;
}
.tv-refresh-min {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-size: 0.52rem; font-weight: 700; color: var(--tv-text3);
  font-variant-numeric: tabular-nums;
}

/* ─── LAST REFRESH ─── */
.tv-last-refresh {
  position: absolute; bottom: 44px; right: 16px;
  font-size: 0.56rem; color: var(--tv-text3); z-index: 10;
}

/* ─── SETTINGS TV button ─── */
.tv-mode-open-btn {
  background: rgba(0,180,120,0.1) !important;
  border-color: rgba(0,180,120,0.3) !important;
  color: #5ee7b5 !important;
}

/* ─── Background blobs ─── */
.tv-bg {
  position: absolute; inset: 0; pointer-events: none; z-index: 0; overflow: hidden;
}
.tv-bg-blob {
  position: absolute; border-radius: 50%;
  filter: blur(100px);
  will-change: transform;
}
.tv-blob-1 {
  width: 65vw; height: 65vw; top: -25%; left: -20%;
  background: rgba(var(--tv-blob1), var(--tv-blob1-op));
  animation: tvB1 100s ease-in-out infinite alternate;
}
.tv-blob-2 {
  width: 55vw; height: 55vw; bottom: -15%; right: -15%;
  background: rgba(var(--tv-blob2), var(--tv-blob2-op));
  animation: tvB2 130s ease-in-out infinite alternate;
}
.tv-blob-3 {
  width: 45vw; height: 45vw; top: 35%; left: 35%;
  background: rgba(var(--tv-blob3), var(--tv-blob3-op));
  animation: tvB3 155s ease-in-out infinite alternate;
}
@keyframes tvB1 {
  from { transform: translate(0,0) scale(1); }
  to   { transform: translate(10vw,8vh) scale(1.12); }
}
@keyframes tvB2 {
  from { transform: translate(0,0) scale(1); }
  to   { transform: translate(-8vw,-10vh) scale(1.08); }
}
@keyframes tvB3 {
  from { transform: translate(0,0) scale(1); }
  to   { transform: translate(12vw,-7vh) scale(0.9); }
}
@media (prefers-reduced-motion: reduce) { .tv-bg-blob { animation: none; } }

.tv-overlay > *:not(.tv-bg) { position: relative; z-index: 1; }

/* ─── HEADER ─── */
.tv-header {
  display: grid;
  grid-template-columns: 210px 1fr 210px;
  align-items: center;
  padding: 10px 60px 10px 22px;
  background: rgba(5,9,22,0.82);
  backdrop-filter: blur(32px) saturate(1.8);
  -webkit-backdrop-filter: blur(32px) saturate(1.8);
  border-bottom: 1px solid var(--tv-border);
  box-shadow: 0 1px 0 rgba(255,255,255,0.04), 0 4px 24px rgba(0,0,0,0.3);
  flex-shrink: 0;
}
.tv-hdr-logo { display: flex; flex-direction: column; gap: 2px; }
.tv-hdr-logotext {
  font-size: 1rem; font-weight: 900; color: #fff;
  letter-spacing: 0.08em; text-transform: uppercase; line-height: 1;
}
.tv-hdr-logosub {
  font-size: 0.6rem; color: var(--tv-text3);
  text-transform: uppercase; letter-spacing: 0.06em;
}
.tv-hdr-meta { margin-top: 6px; }
.tv-hdr-shift-nm { font-size: 0.82rem; font-weight: 700; color: var(--tv-orange); }

/* 4 KPI cells */
.tv-hdr-kpis {
  display: flex; align-items: stretch; justify-content: center;
}
.tv-kpi-cell {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 6px 18px; position: relative;
  border-left: 1px solid var(--tv-border);
}
.tv-kpi-cell:first-child { border-left: none; }
.tv-kpi-val {
  font-size: 2.1rem; font-weight: 900; line-height: 1;
  color: #fff; font-variant-numeric: tabular-nums; letter-spacing: -0.02em;
  transition: color 0.5s;
}
.tv-kpi-lbl {
  font-size: 0.62rem; font-weight: 600; color: var(--tv-text3);
  text-transform: uppercase; letter-spacing: 0.1em; margin-top: 4px;
  white-space: nowrap;
}
.tv-kpi-accent {
  position: absolute; bottom: 0; left: 20%; right: 20%;
  height: 2px; border-radius: 1px;
}
.tv-kpi-accent-purple { background: var(--tv-purple); }
.tv-kpi-accent-orange { background: var(--tv-orange); }
.tv-kpi-accent-green  { background: var(--tv-green); }
.tv-kpi-accent-blue   { background: var(--tv-blue); }
.tv-col-green { color: var(--tv-green) !important; }
.tv-col-blue  { color: var(--tv-blue) !important; }

/* Clock */
.tv-hdr-clock { text-align: right; }
.tv-clock {
  font-size: 2.6rem; font-weight: 900; color: #fff; line-height: 1;
  letter-spacing: 0.02em; font-variant-numeric: tabular-nums;
}
.tv-date { font-size: 0.65rem; color: var(--tv-text3); margin-top: 3px; }
.tv-hdr-prev { margin-top: 5px; font-size: 0.68rem; }
.tv-hdr-prev-lbl  { color: var(--tv-text3); }
.tv-hdr-prev-nm   { color: var(--tv-text2); }
.tv-hdr-prev-sep  { color: var(--tv-text3); }
.tv-hdr-prev-val  { color: var(--tv-orange); font-weight: 800; font-variant-numeric: tabular-nums; }
.tv-hdr-prev-unit { color: var(--tv-text3); }

/* ─── SECTION HEADERS ─── */
.tv-sec-hdr {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 10px; flex-shrink: 0;
}
.tv-sec-label {
  font-size: 0.62rem; font-weight: 800; letter-spacing: 0.18em;
  text-transform: uppercase; color: var(--tv-text3);
}
.tv-sec-sub     { font-size: 0.72rem; color: var(--tv-text2); }
.tv-sec-hdr-right { margin-left: auto; display: flex; gap: 12px; align-items: center; }
.tv-sec-summary { font-size: 0.7rem; color: var(--tv-text2); }

/* ─── PAGINATION DOTS ─── */
.tv-page-dots { display: flex; gap: 5px; align-items: center; }
.tv-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: rgba(255,255,255,0.2);
  transition: background 0.3s, transform 0.3s;
}

/* ─── MAIN AREA ─── */
.tv-main {
  display: flex; flex-direction: row; flex: 1; min-height: 0;
}

/* ─── TRUCKS SECTION (left ~65%) ─── */
.tv-trucks-section {
  flex: 0 0 65%;
  display: flex; flex-direction: column;
  padding: 12px 10px 8px 18px;
  border-right: 1px solid var(--tv-border);
  min-height: 0;
}

/* Truck grid: 4 cols, rows fill available height */
.tv-trucks-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 1fr;
  gap: 8px;
  flex: 1; min-height: 0; overflow: hidden;
}

.tv-no-trucks {
  grid-column: 1/-1; display: flex; align-items: center; justify-content: center;
  color: var(--tv-text3); font-size: 0.9rem;
}

/* Grid page transition */
.tv-grid-exit  { animation: tvGridOut 0.27s ease forwards; }
.tv-grid-enter { animation: tvGridIn 0.45s cubic-bezier(0.16,1,0.3,1) forwards; }
@keyframes tvGridOut {
  to { opacity: 0; transform: translateY(-10px); }
}
@keyframes tvGridIn {
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ─── TRUCK CARD ─── */
.tv-truck-card {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 14px;
  padding: 14px 16px 12px 20px;
  display: flex; flex-direction: column; gap: 8px;
  backdrop-filter: blur(16px) saturate(1.5);
  -webkit-backdrop-filter: blur(16px) saturate(1.5);
  transition: border-color 0.4s, box-shadow 0.4s, opacity 0.4s;
  position: relative; overflow: hidden;
  box-shadow: 0 2px 16px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.12);
  min-height: 0;
}
/* Left accent bar */
.tv-truck-card::before {
  content: ""; position: absolute; left: 0; top: 12%; bottom: 12%;
  width: 4px; border-radius: 0 3px 3px 0;
  transition: background 0.4s;
}
.tv-tier-green::before { background: var(--tv-green); box-shadow: 0 0 10px rgba(74,222,128,0.4); }
.tv-tier-blue::before  { background: var(--tv-blue);  box-shadow: 0 0 10px rgba(96,165,250,0.4); }
.tv-tier-amber::before { background: var(--tv-amber); box-shadow: 0 0 10px rgba(251,191,36,0.4); }
.tv-tier-rest::before  { background: var(--tv-orange);box-shadow: 0 0 10px rgba(255,138,61,0.4); }
.tv-tier-dim::before   { background: rgba(255,255,255,0.15); }

.tv-tier-green { border-color: rgba(74,222,128,0.28); box-shadow: 0 0 24px rgba(74,222,128,0.07), inset 0 1px 0 rgba(255,255,255,0.12); }
.tv-tier-blue  { border-color: rgba(96,165,250,0.28); box-shadow: 0 0 24px rgba(96,165,250,0.07), inset 0 1px 0 rgba(255,255,255,0.12); }
.tv-tier-amber { border-color: rgba(251,191,36,0.28); box-shadow: 0 0 24px rgba(251,191,36,0.07), inset 0 1px 0 rgba(255,255,255,0.12); }
.tv-tier-rest  { border-color: rgba(255,138,61,0.28); box-shadow: 0 0 24px rgba(255,138,61,0.07), inset 0 1px 0 rgba(255,255,255,0.12); }
.tv-tier-dim   { opacity: 0.4; }
.tv-truck-closed { opacity: 0.22; filter: grayscale(0.5); }

.tv-truck-plate {
  font-size: 1.15rem; font-weight: 900; color: #fff;
  letter-spacing: 0.05em; line-height: 1; word-break: break-all;
}
.tv-drv-here { background: rgba(74,222,128,0.15); color: var(--tv-green); border: 1px solid rgba(74,222,128,0.3); }
.tv-drv-rest { background: rgba(255,138,61,0.15); color: var(--tv-orange); border: 1px solid rgba(255,138,61,0.3); }
.tv-drv-away { background: rgba(255,255,255,0.07); color: var(--tv-text3); border: 1px solid var(--tv-border); }

.tv-truck-lmp {
  font-size: 0.68rem; color: var(--tv-text2); text-transform: uppercase;
  letter-spacing: 0.04em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

.tv-truck-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.tv-stat-pill {
  font-size: 0.65rem; font-weight: 700; padding: 3px 9px;
  border-radius: 99px; white-space: nowrap; border: 1px solid transparent;
}
.tv-pill-ready   { background: rgba(74,222,128,0.12); color: var(--tv-green);  border-color: rgba(74,222,128,0.25); }
.tv-pill-active  { background: rgba(96,165,250,0.12); color: var(--tv-blue);   border-color: rgba(96,165,250,0.25); }
.tv-amber { color: var(--tv-amber) !important; }
.tv-green { color: var(--tv-green) !important; }

/* ─── WEATHER PANEL ─── */
.tv-weather-panel {
  flex-shrink: 0; padding: 10px 14px 10px;
  background: rgba(255,255,255,0.04);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  border-top: 1px solid var(--tv-border);
}

/* ─── TICKER ─── */
.tv-ticker {
  display: flex; align-items: center; gap: 12px;
  padding: 0 18px; height: 38px; flex-shrink: 0;
  background: rgba(5,9,22,0.90);
  border-top: 1px solid var(--tv-border);
}
.tv-ticker-in { animation: tvTkIn 0.4s ease; }
@keyframes tvTkIn {
  from { opacity: 0; transform: translateY(5px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ─── Value flash ─── */
.tv-val-flash { animation: tvFlash 0.8s ease; }
@keyframes tvFlash {
  0%  { color: var(--tv-orange); }
  50% { color: var(--tv-orange); }
  100% { color: inherit; }
}

/* TV mode layout/detail pass: wider loading board, compact side rail, bottom match strip */
.tv-overlay {
  --tv-text:   rgba(255,255,255,0.96);
  --tv-text2:  rgba(255,255,255,0.74);
  --tv-text3:  rgba(255,255,255,0.48);
  --tv-border: rgba(255,255,255,0.18);
  --tv-felveve: #4a9eff;
  --tv-ertesito: #ff6b35;
  --tv-megerkezett: #00d4aa;
  --tv-szemles: #ef4444;
  background:
    radial-gradient(circle at 24% -8%, rgba(var(--tv-blob1), 0.12), transparent 34%),
    radial-gradient(circle at 96% 18%, rgba(var(--tv-blob2), 0.10), transparent 32%),
    #050916;
  font-family: Bahnschrift, "DIN Condensed", "Aptos Display", "Segoe UI Variable Display", "Segoe UI", sans-serif;
}

.tv-header {
  padding: 11px 60px 11px 24px;
  background: rgba(5, 9, 22, 0.50);
  border-bottom-color: rgba(255,255,255,0.16);
  backdrop-filter: blur(8px) saturate(1.18);
  -webkit-backdrop-filter: blur(8px) saturate(1.18);
}

.tv-overlay .tv-exit-btn {
  position: absolute;
  top: 12px;
  right: 16px;
}

.tv-overlay .tv-refresh-fab {
  position: absolute;
  top: 56px;
  right: 16px;
}

.tv-overlay .tv-last-refresh {
  display: none;
}

.tv-main {
  gap: 0;
}

.tv-trucks-section {
  flex: 1 1 auto;
  padding: 14px 14px 10px 20px;
  border-right-color: rgba(255,255,255,0.14);
  position: relative;
}

.tv-sec-hdr {
  min-height: 28px;
  margin-bottom: 12px;
}

.tv-sec-label {
  font-size: 0.68rem;
  color: rgba(255,255,255,0.58);
}

.tv-sec-sub,
.tv-sec-summary {
  font-size: 0.82rem;
  color: rgba(255,255,255,0.78);
}

.tv-trucks-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-auto-rows: 1fr;
  gap: 12px;
  padding-bottom: 26px;
}

.tv-truck-page-footer {
  position: absolute;
  left: 20px;
  right: 14px;
  bottom: 8px;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.tv-page-dots {
  gap: 8px;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(5, 9, 22, 0.30);
  border: 1px solid rgba(255,255,255,0.16);
  backdrop-filter: blur(4px) saturate(1.12);
  -webkit-backdrop-filter: blur(4px) saturate(1.12);
}

.tv-dot {
  width: 8px;
  height: 8px;
  background: rgba(255,255,255,0.26);
  box-shadow: none;
}

.tv-dot-filled {
  background: rgba(255,255,255,0.94);
  box-shadow: 0 0 14px rgba(255,255,255,0.28);
}

.tv-truck-card {
  padding: 13px 14px 12px;
  gap: 7px;
  border: 1px solid rgba(255,255,255,0.16);
  border-radius: 18px;
  background:
    linear-gradient(145deg, rgba(255,255,255,0.095), rgba(255,255,255,0.018) 48%, rgba(255,255,255,0.050)),
    rgba(10, 17, 34, 0.12);
  backdrop-filter: blur(3px) saturate(1.12);
  -webkit-backdrop-filter: blur(3px) saturate(1.12);
  box-shadow:
    0 16px 36px rgba(0,0,0,0.28),
    inset 0 1px 0 rgba(255,255,255,0.20),
    inset 0 -18px 34px rgba(255,255,255,0.025);
  isolation: isolate;
}

.tv-truck-card::before {
  content: "";
  position: absolute;
  inset: 0;
  width: auto;
  border-radius: inherit;
  padding: 1px;
  background:
    linear-gradient(120deg, rgba(255,255,255,0.52), rgba(255,255,255,0.08) 28%, rgba(255,255,255,0.34) 54%, rgba(255,255,255,0.10) 76%, rgba(255,255,255,0.42)),
    radial-gradient(circle at 20% 0%, rgba(255,255,255,0.30), transparent 34%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  opacity: 0.88;
}

.tv-truck-card::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(ellipse at 24% 18%, var(--tv-card-glow, rgba(96,165,250,0.20)), transparent 42%),
    conic-gradient(from 128deg at 62% 46%, transparent 0 18%, rgba(255,255,255,0.10) 25%, transparent 34% 61%, rgba(255,255,255,0.08) 70%, transparent 78%);
  filter: blur(18px);
  opacity: 0.95;
  transform: rotate(-7deg);
  animation: tvCardMorph 18s ease-in-out infinite alternate;
}

@keyframes tvCardMorph {
  from { transform: translate3d(-2%, -1%, 0) rotate(-8deg) scale(1); border-radius: 42% 58% 45% 55%; }
  to   { transform: translate3d(2%, 1%, 0) rotate(7deg) scale(1.08); border-radius: 56% 44% 58% 42%; }
}

.tv-tier-green {
  --tv-card-glow: rgba(74,222,128,0.30);
  background:
