/* ── 2a. Sofőr badge — elegáns üveg-pill, bal oldali státusz-jelzővel ─────── */
.tv-overlay .tv-truck-meta { grid-template-columns: 2fr repeat(3, minmax(0, 1fr)); }
/* A badge SZÍNE viszi a státuszt (nincs külön pötty) */
.tv-overlay .tv-drv-here {
  background: linear-gradient(160deg, rgba(52,224,138,0.34), rgba(52,224,138,0.12));
  box-shadow: inset 0 0 0 1px rgba(52,224,138,0.55), 0 5px 16px rgba(52,224,138,0.14);
}
