/* TV detailed opening choreography: staggered, page-scoped, no idle loops. */
/* PERF: a nyitó animációk CSAK transform+opacity-t mozgatnak (kompozítor-barát, GPU).
   A `filter: blur()` per-frame offscreen buffert + újra-blurt kényszerít minden érintett
   (gyakran nagy) elemre — egy Intel iGPU-n ez a nyitás fő hitch-e. A mozgás (lift/scale/
   fade) változatlan, csak a blur-garnír kerül ki — falikijelzőn amúgy is alig látszott. */
@keyframes tvOpsTruckIn {
  0% { opacity: 0; transform: translate3d(-34px, 22px, 0) scale(0.975); }
  62% { opacity: 1; transform: translate3d(4px, -2px, 0) scale(1.006); }
  100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes tvOpsSideIn {
  0% { opacity: 0; transform: translate3d(28px, 0, 0) scale(0.985); }
  100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes tvTruckIconDriveIn {
  0% { opacity: 0; transform: translate3d(-42px, 10px, 0) scale(0.86); }
  72% { opacity: 1; transform: translate3d(5px, -1px, 0) scale(1.03); }
  100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes tvProgressFillIn {
  from { transform: scaleX(0); opacity: 0.48; }
  to { transform: scaleX(1); opacity: 1; }
}
@keyframes tvMetricPopIn {
  0% { opacity: 0; transform: translate3d(0, 9px, 0) scale(0.93); }
  72% { opacity: 1; transform: translate3d(0, -1px, 0) scale(1.035); }
  100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes tvReportPanelIn {
  0% { opacity: 0; transform: translate3d(0, 22px, 0) scale(0.982); }
  65% { opacity: 1; transform: translate3d(0, -3px, 0) scale(1.004); }
  100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes tvGaugeBootIn {
  0% { opacity: 0; transform: translate3d(0, 16px, 0) scale(0.95); }
  52% { opacity: 1; transform: translate3d(0, -3px, 0) scale(1.018); }
  100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes tvChartAreaIn {
  from { opacity: 0; transform: scaleY(0.2); transform-origin: bottom; }
  to { opacity: 1; transform: scaleY(1); transform-origin: bottom; }
}
@keyframes tvChartDotIn {
  0% { opacity: 0; transform: scale(0.2); }
  70% { opacity: 1; transform: scale(1.18); }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes tvSoftValueRise {
  0% { opacity: 0; transform: translate3d(0, 10px, 0); }
  100% { opacity: 1; transform: translate3d(0, 0, 0); }
}

