/* =============================================================================
   TV sync-stall banner (2026-07-08). Shown ONLY when the background refresh is
   stuck (tv_mode.js sets data-on="1"); the TV keeps showing the last good data,
   so a frozen board is no longer silent. Bottom-center, out of the way of the
   header stats, but unmistakable.
   ========================================================================== */
.tv-overlay .tv-stale-banner { display: none; }
.tv-overlay .tv-stale-banner[data-on="1"] {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  position: fixed;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%);
  z-index: 60;
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 1.02rem;
  font-weight: 850;
  letter-spacing: 0.01em;
  color: #ffdede;
  background:
    radial-gradient(circle at 18% 0%, rgba(239,68,68,0.34), transparent 60%),
    linear-gradient(180deg, rgba(127,29,29,0.92), rgba(87,20,20,0.92));
  border: 1px solid rgba(248,113,113,0.55);
  box-shadow: 0 10px 30px rgba(0,0,0,0.42), 0 0 22px rgba(239,68,68,0.28);
  animation: tvStalePulse 2.4s ease-in-out infinite;
}
.tv-overlay .tv-stale-ico {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
}
.tv-overlay .tv-stale-ico path:first-child {
  fill: rgba(239,68,68,0.30);
  stroke: #fca5a5;
  stroke-width: 1.6;
  stroke-linejoin: round;
}
.tv-overlay .tv-stale-ico-bang {
  fill: none;
  stroke: #fff2f2;
  stroke-width: 2.1;
  stroke-linecap: round;
}
@keyframes tvStalePulse {
  0%, 100% { box-shadow: 0 10px 30px rgba(0,0,0,0.42), 0 0 14px rgba(239,68,68,0.22); }
  50%      { box-shadow: 0 10px 30px rgba(0,0,0,0.42), 0 0 30px rgba(239,68,68,0.44); }
}
@media (prefers-reduced-motion: reduce) {
  .tv-overlay .tv-stale-banner[data-on="1"] { animation: none; }
}
